INSERT INTO chapters (chapter, section, title, notes, chapter_subheading_notes, supplementary_notes, export_licensing_notes, definitions, extraction_warnings, notes_sources, source_pdf, extracted_at, verified_against_wco_at) VALUES
  ('01', 'I', 'LIVE ANIMALS', '[{"number": "1", "text": "This Chapter covers all live animals except : (a) fish and crustaceans, molluscs and other aquatic invertebrates, of heading 0301, 0306, 0307 or 0308; (b) cultures of micro-organisms and other products of heading 3002; and (c) animals of heading 9508."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"number": "1", "text": "The term ?Cattle? covers cows, oxen, bulls and calves"}, {"number": "2", "text": "Export of wild animals and their products as defined in Wild Life (Protection) Act, 1972 including their part prohibited."}, {"number": "3", "text": "Germplasm of cattle is classified in heading 0511"}]'::jsonb, '[]'::jsonb, '["PDF source uses 6-digit subheading codes without dots (e.g., ''010121'') and 8-digit tariff line codes without dots (e.g., ''01012100''). Normalized to NNNN.NN (subheading) and NNNN.NN.NN (tariff line) per project schema.", "PDF Export Licensing Notes (page 3) contain ''?'' characters in place of typographic quote marks: ''The term ?Cattle? covers cows, oxen, bulls and calves''. The intended text is ''Cattle'' enclosed in quotation marks. Preserved verbatim as ''?Cattle?'' to flag the OCR/encoding artifact.", "PDF page 2 displays Policy Condition #3 (exotic birds) twice in succession — appears to be a duplicate row in the source PDF. Only one instance is captured in policy_conditions to avoid redundancy.", "PDF table-chrome headers (''Main Notes'', ''Policy Condition'', ''Export Licensing Notes'', ''Product Description and Export Policy'', ''Sl.No. Notes Notification No Notification Date'', ''Itc(hs) Code. Description Export Policy Policy Condition'') were recognized as repeating table headers and EXCLUDED from chapter_notes / section_notes / heading_notes per extraction rules.", "Section I title in PDF reads ''Section I, LIVE ANIMALS; ANIMAL PRODUCTS'' — captured at top-level ''section'' field as ''I''. Section I-level notes (2 notes about young of genus/species and ''dried'' products) are placed in section_notes.", "Several subheadings in the PDF have no explicit 6-digit subheading row but appear directly as 8-digit tariff lines (e.g., 01031000, 01042000, 01051100, 01059400, 01061100, 01062000, 01069000). For these, a synthetic subheading row is created (e.g., 0103.10, 0104.20, 0105.11, 0106.11) with one tariff line ending in ''.00'' (e.g., 0103.10.00, 0104.20.00) — this mirrors the convention used in chapter-09.json for single-tariff-line subheadings.", "Unit column is not present in the source PDF for Chapter 01 — the PDF table columns are ''Itc(hs) Code'', ''Description'', ''Export Policy'', ''Policy Condition''. All tariff_lines therefore have unit: null.", "Heading 0102 tariff line 01022990 description reads ''Other, including calves'' — verbatim, the comma is in the source.", "Heading 0105 description spans two lines in PDF: ''Live poultry, that is to say, fowls of the species Gallus domesticus, ducks, geese, turkeys and guinea fowls.'' — joined into a single string.", "Heading 0106 tariff line 01061200 description spans three lines in PDF: ''Mammals: -- Whales, dolphins and porpoises (mammals of the order Cetacea); manatees and dugongs (mammals of the order Sirenia); seals, sea lions and walruses (mammals of the suborder Pinnipedia)'' — joined into a single string.", "Heading 0106 includes the HS 2017+ split for insects (010641 Bees, 010649 Other) and the HS 2022 mammal subheadings (010611–010620, 010631–010639). All present in PDF and captured verbatim.", "Export Licensing Note 3 (''Germplasm of cattle is classified in heading 0511'') is a chapter-redirection clause — captured both in export_licensing_notes and as an exclusion_clause."]'::jsonb, '{}'::jsonb, 'Chapter 01 Live Animals.pdf', ('2026-05-22')::timestamptz, NOW()),
  ('02', 'I', 'MEAT AND EDIBLE MEAT OFFAL', '[]'::jsonb, '[{"number": "Supplementary Note 1 (page 2)", "text": "In this Chapter, \"wild animal\" means wild animal as defined in the Wild Life (Protection) Act, 1972 (53 of 1972)."}, {"number": "Supplementary Note 1 (page 4)", "text": "Beef includes meat and edible offal of cows, oxens and calf."}, {"number": "Supplementary Note 2 (page 4)", "text": "Offal includes heart, liver, tongue, kidneys and other organs."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["PDF source uses 8-digit codes without dots (e.g., ''02011000''). Normalized to NNNN.NN.NN format (e.g., ''0201.10.00'') per project schema. 6-digit subheading numbers (e.g., ''020110'') normalized to NNNN.NN (e.g., ''0201.10''). Heading codes (e.g., ''0201'') are 4-digit.", "PDF table-chrome headers (''Sl.No. Notes Notification No Notification Date'', ''SI.No. Notes Notification Date Notification No'', ''Itc(hs) Code. Description Export Policy Policy Condition'', ''Main Notes'', ''Supplementary Notes'', ''Policy Condition'', ''Export Licensing Notes'', ''Product Description and Export Policy'') were recognized as table headers and EXCLUDED from the legal notes per extraction rules.", "Section I Main Notes (pre-chapter) contain 2 notes: (1) reference to young of genus/species, and (2) definition of ''dried'' as including dehydrated/evaporated/freeze-dried products. These are captured in section_notes.", "Chapter 02 has a single Main Note (SI.No. 1) which is a ''This Chapter does not cover'' exclusion clause with sub-items (a), (b), (c), (d). Each sub-item is captured as a separate row in exclusion_clauses per project schema.", "Two distinct Supplementary Notes tables appear in the PDF. The first (page 2, immediately after Main Notes) contains 1 entry defining ''wild animal'' under Wild Life (Protection) Act, 1972 — captured in subheading_notes. The second Supplementary Notes table (page 4) contains 8 entries: items 1-2 are sub-heading definitions (''Beef includes meat and edible offal of cows, oxens and calf'' and ''Offal includes heart, liver, tongue, kidneys and other organs'') captured in subheading_notes; items 3-8 are restatements/cross-references of Policy Conditions 1-6 (with minor textual variations such as ''Restricted Export authorisation'' vs ''restricted export authorisation..'' and case differences) — these are NOT re-captured in subheading_notes to avoid duplication; the canonical text is preserved in policy_conditions.", "Policy Conditions table contains 8 numbered conditions covering: (1) chilled/frozen meat veterinary certification, (2) canned meat pre-shipment inspection, (3) gonads/reproductive organs/germplasm restricted authorisation, (4) APEDA declaration requirement, (5) carton labeling requirements, (6) State veterinary certification, (7) Wild Life (Protection) Act prohibition on wild animal exports, (8) Halal certification scheme (I-CAS Halal) for 15 listed countries.", "Policy Condition 8 (Halal) contains ''?'' characters in place of typographic quote marks (''?India Conformity Assessment Scheme(I-CAS)- Halal?'', ''importing country?s requirements''). These are OCR/encoding artifacts from the source PDF — preserved verbatim. Intended text uses curly quotes around ''India Conformity Assessment Scheme(I-CAS)- Halal'' and an apostrophe in ''country''s''.", "The ''Export Licensing Notes'' header appears at the bottom of page 3 immediately after Policy Condition 8 but is followed only by the Supplementary Notes table on page 4 and then the tariff table — no Export Licensing Notes content rows are present in this chapter. The header is preserved as a table-chrome artifact and no export_licensing_notes field is populated.", "Source PDF contains minor spelling/typo artifacts preserved verbatim: ''POUTRY'' (heading 0209, should be ''POULTRY''), ''oxens'' (Supp Note 1, should be ''oxen''), ''Conition'' (Policy Condition references, should be ''Condition''), ''dolphines'' (subheading 0208.40, should be ''dolphins''), ''authorisation..'' (with double period, Supp Note 5).", "Heading 0205 (Meat of horses, asses, mules or hinnies, fresh, chilled or frozen) appears in the PDF only as the 8-digit tariff line ''02050000'' with no separate 4-digit heading row. The heading title is reconstructed from the tariff line description per ITC(HS) convention; tariff line is attached directly under the heading.", "Subheading 0206.80 (Other, fresh or chilled) and 0206.90 (Other, frozen) appear with the 6-digit code in the PDF (020680, 020690). Subheading 0210.20 (''Meat of bovine animals'') appears as an 8-digit code 02102000 — preserved as the single tariff line ''0210.20.00'' under subheading ''0210.20''.", "Subheading 0210.99 (''Of primates'' for tariff line 02109200 area) — the PDF row ''02109100'' uses description ''Other, including edible flours and meals of meat or meat offal'' and on the next page shows '': -- Of primates'' as a continuation/orphan row without a tariff line code. This appears to be a layout artifact where ''-- Of primates'' is the sub-description fragment of 0210.91 in the source. Captured verbatim under 0210.91 tariff line.", "All tariff lines under headings 0204, 0206 (selected), 0207 partial, 0208, 0209, and 0210 are shown with Notification No ''34/2024-25'' dated ''01.10.2024'' in the Policy Condition column. Many of these tariff-line-specific Policy Condition cells contain text like ''Quality control and inspection under Policy Conition 1 and 2 respectively as well as Policy Condition 4 are required to be fulfilled. Exports shall also be subject to Policy Condition 8 of this Chapter.'' — these reference the chapter-level Policy Conditions and are not re-captured per tariff line in this extraction. The canonical Policy Conditions are in policy_conditions.", "Tariff line 0210.20.00 (Meat of bovine animals, salted/in brine/dried/smoked) carries a tariff-line-specific Policy Condition restating Policy Conditions 1, 2, 4, 6 with the same buffalo-not-for-breeding-and-milch-purposes condition. This is preserved as a chapter-wide pattern via policy_conditions; the per-tariff-line restatement is not duplicated here."]'::jsonb, '{}'::jsonb, 'Chapter 02 Meat And Edible Meat Offal.pdf', ('2026-05-22')::timestamptz, NOW()),
  ('03', 'I', 'FISH AND CRUSTACEANS, MOLLUSCS AND OTHER AQUATIC INVERTEBRATES', '[{"number": "1", "text": "This Chapter does not cover : (a) mammals of heading 0106; (b) meat of mammals of heading 0106 ( heading 0208 or 0210); (c) fish (includinglivers,roes andmilt thereof) or crustaceans,molluscs or other aquatic invertebrates, dead and unfit or unsuitable for human consumption by reason of either their species or their condition (Chapter 5); flours, meals or pellets of fish or of crustaceans, molluscs or other aquatic invertebrates, unfit for human consumption (heading 2301); or (d) caviar or caviar substitutes prepared from fish eggs (heading 1604)."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"number": "1", "text": "A consignment/ lot is considered to be undersized if it contains specified species any piece of which has a weight less than that indicated against the species or has been processed out of or obtained from individual pieces of the species weighing less than the minimum weight indicated against the species."}, {"number": "2", "text": "?as tail? means without head."}, {"number": "3", "text": "Exports of all wild animals, animal articles including their products and derivatives excluding those for which ownership certificates have been granted and also those required for transactions for education, scientific research and management under Wild Life (Protection) Act, 1972 including their parts and products are Prohibited and not permitted to be exported. Exports wherever permissible shall be against a Restricted Export Authorisation Only."}, {"number": "4", "text": "The term ?Marine Products? in this Chapter covers all the eight digit Exim Codes in the Chapter of the ITC(HS) Classification of Export and Import items. All marine species that have been included in the Schedules of the Wild Life (Protection) Act, 1972 are prohibited for exports and other species listed in CITES are subject to the provisions of the CITES. Exports wherever permissible shall be against a Restricted Export Authorisation Only."}]'::jsonb, '[]'::jsonb, '["PDF source uses 8-digit codes without dots (e.g., ''03011100''). Normalized to NNNN.NN.NN format (e.g., ''0301.11.00'') per project schema. 6-digit subheading numbers in PDF (e.g., ''030289'') normalized to NNNN.NN (e.g., ''0302.89'').", "PDF contains ''?'' characters in place of typographic quote marks in some Export Licensing Notes (e.g., ''?as tail?'' and ''?Marine Products?''). These are OCR/encoding artifacts from the source PDF — preserved verbatim as they appear in the source. The intended text is ''as tail'' and ''Marine Products'' enclosed in quotation marks.", "Section I Main Notes (2 notes about ''young of that genus or species'' and ''dried'' products) appear on PDF page 1 above the Chapter 03 title and are attributed to section_notes (Section I, LIVE ANIMALS; ANIMAL PRODUCTS), not chapter_notes.", "PDF table-chrome headers (''Main Notes'', ''Sl.No. Notes Notification No Notification Date'', ''Sl.No. Notes Notification Date Notification No'', ''Export Licensing Notes'', ''Product Description and Export Policy'', ''Itc(hs) Code. Description Export Policy Policy Condition'') were recognized as table headers and EXCLUDED from the legal notes per extraction rules.", "Chapter 03 has one main chapter note (the exclusions covering mammals of heading 0106, meat of mammals of heading 0106/0208/0210, fish unfit for human consumption of Chapter 5, flours/meals/pellets unfit for human consumption of heading 2301, and caviar/caviar substitutes of heading 1604). The note text contains spacing artifacts from the PDF (e.g., ''includinglivers,roes andmilt'') — preserved verbatim.", "Many headings (0301, 0302, 0303 etc.) do NOT have explicit 6-digit subheading rows in the PDF — tariff lines appear directly under the heading. The schema infers and groups tariff lines by their first 6 digits to create subheading containers. Where the PDF DOES have an explicit subheading row (e.g., ''030289'', ''030299'', ''030391'', ''030399'', ''030449'', ''030459'', ''030488'', ''030489'', ''030559'', ''030569'', ''030612'', ''030616'', ''030617'', ''030636'', ''030739'', ''030742'', ''030743'', ''030749'', ''030830'', ''030910'', ''030990''), that explicit row''s description is used as the subheading title; otherwise an inferred title is constructed from the tariff-line descriptions.", "Tariff line code 03011100 has description ''Ornamental fish : -- Freshwater''. WCO HS 2022 designates 0301.11 as ''Ornamental fish — Freshwater'' and 0301.19 as ''Ornamental fish — Other''. The PDF shows code 03011100 directly with description ''Ornamental fish : -- Freshwater'' and 03011900 with ''Ornamental fish : -- Other''. Preserved verbatim.", "Heading 0302 tariff lines 03022400 and 03022900 reference ''subheadings 030291 to 030299'' (without the dot/decimal form) — this is a typographical inconsistency in the source PDF. Other lines correctly reference ''0302.91 to 0302.99''. Preserved verbatim.", "Heading 0302 tariff line 03022900 description ends with '': - - Other'' (with extra spacing) and references ''sub-headings 0302 91 to 0301 99'' — the ''0301 99'' is clearly a typo in the source PDF for ''0302.99''. Preserved verbatim.", "Heading 0302 tariff line 03023300 description: ''Tunas (of the genus Thunnus), skipjack tuna (stripe-bellied bonito) (Katsuwonuspelamis), excluding edible fish offal of sub-headings 030291 to 030299: - - Skipjack tuna (stripe-bellied bonito) (Katsuwonuspelamis)''. The species name ''Katsuwonuspelamis'' is missing a space (should be ''Katsuwonus pelamis''). Preserved verbatim.", "Subheading 0302.91 — ''Livers, roes and milt'' — appears in the PDF as TWO codes: ''03029100'' (with Export Policy ''Free'') and ''03029110'' (no policy). Both preserved as separate tariff lines under subheading 0302.91.", "Subheading 0302.92 — ''Shark fins'' — appears in the PDF as TWO codes: ''03029200'' (Export Policy ''Prohibited'', Notification No ''110/2009-14'') and ''03029210'' (no policy). Both preserved as separate tariff lines under subheading 0302.92.", "Subheading 0302.99 in PDF appears as 6-digit code ''030299'' with description ''Livers, roes, milt, fish fins, heads, tails, maws and other edible fish offal : --Other'' followed by 8-digit children ''03029910'' (Fish fins other than shark fins; heads, tails and maws) and ''03029990'' (Other edible fish offal).", "Heading 0302 tariff line 03028930 (Pomfret) has a Policy Condition column entry: ''However, Exports of Fresh or Chilled or Frozen silver pomfrets of weight less than 300 gms is permitted only under Restricted Export Authorization.'' Captured in policy_conditions.", "Heading 0303 — subheading 0303.91 (Livers, roes and milt) is represented by 6-digit row ''030391'' and contains two 8-digit children: ''03039110'' (Egg or egg yolk of fish) and ''03039190'' (Other). Subheading 0303.92 (Shark fins) has only the 8-digit code ''03039200'' (Prohibited). Subheading 0303.99 (Other) is represented by 6-digit row ''030399'' with two children: ''03039910'' (Fish fins other than shark fins, heads, tails and maws) and ''03039990'' (Other edible fish offal).", "Heading 0303 — the PDF skips numbering between 03035100 and 03035300 (no 03035200); preserved verbatim.", "Heading 0303 — the PDF shows code 03035100 with full Herrings/anchovies/sardines/... family list and ends with ''--Herrings (Clupea harengus, Clupea pallasii)''. This is the WCO HS 2022 standard.", "Heading 0303 — the PDF shows ''030359'' (6-digit) with description ''Herrings ... excluding edible fish offal of subheadings 0303.91 to 0303.99 : --Other'', followed by 8-digit children ''03035910'' (Indian mackerels (Rastrelliger spp.)) and ''03035990'' (Other).", "Heading 0303 — the PDF shows ''030381'' (6-digit) with description ''Other fish, excluding edible fish offal of subheadings 0303.91 to 0303.99 : --Dogfish and other sharks'', followed by 8-digit children ''03038110'' (Dogfish) and ''03038190'' (Other sharks).", "Heading 0303 — the PDF shows ''030389'' (6-digit) with description ''Other fish, excluding edible fish offal of subheadings 0303.91 to 0303.99 : --Other'', followed by 8-digit children: 03038910 (Hilsa), 03038920 (Dara), 03038930 (Ribbon fish), 03038940 (Seer), 03038950 (Pomfret, white/silver/black; with policy condition note), 03038960 (Ghol), 03038970 (Threadfin), 03038980 (Croackers, groupers, flounders), 03038990 (Other).", "Heading 0304 — subheading 0304.49 is represented by 6-digit row ''030449'' with children 03044910 (Hilsa), 03044930 (Seer), 03044940 (Tuna), 03044990 (Other). Note: PDF skips 03044920 (no entry). Preserved verbatim.", "Heading 0304 — subheading 0304.59 is represented by 6-digit row ''030459'' with children 03045910 (Hilsa), 03045930 (Seer), 03045940 (Tuna), 03045990 (Other). Note: PDF skips 03045920.", "Heading 0304 — subheading 0304.88 is represented by 6-digit row ''030488'' with description ''Frozen fillets of other fish : --Dogfish, other sharks, rays and skates (Rajidae)'' and children 03048810 (Dog fish), 03048820 (Other sharks), 03048830 (Rays and skates (Rajidae)).", "Heading 0304 — subheading 0304.89 is represented by 6-digit row ''030489'' with children 03048910 (Hilsa), 03048930 (Seer), 03048940 (Tuna), 03048990 (Other). Note: PDF skips 03048920.", "Heading 0305 — subheading 0305.59 is represented by 6-digit row ''030559'' with children 03055910 (Mumbai Duck), 03055920 (Seer without head), 03055930 (Sprats), 03055990 (Other).", "Heading 0305 — subheading 0305.69 is represented by 6-digit row ''030569'' with children 03056910 (Mumbai duck), 03056920 (Seer without head), 03056930 (Sprats), 03056990 (Other).", "Heading 0306 — subheading 0306.12 represented by 6-digit row ''030612'' (Frozen : -- Lobsters (Homarus spp.)) with children 03061210 (Whole cooked) and 03061290 (Other), both with policy condition for Sand Lobster (Thenus orientalis).", "Heading 0306 — subheading 0306.16 represented by 6-digit row ''030616'' (Frozen : -- Cold-water shrimps and prawns (Pandalus spp., Crangon cragon)) with children 03061610 (Accelerated Freeze Dried (AFD)) and 03061690 (Other).", "Heading 0306 — subheading 0306.17 represented by 6-digit row ''030617'' (Frozen : -- Other shrimps and prawns) with children 03061711 (Scampi — AFD), 03061719 (Scampi — Other), 03061720 (Vannamei shrimp), 03061730 (Indian white shrimp), 03061740 (Black tiger shrimp), 03061750 (Flower shrimp), 03061790 (Other).", "Heading 0306 — subheading 0306.36 represented by 6-digit row ''030636'' (Live, fresh or chilled: -- Other shrimps and prawns) with children 03063610 (Scampi), 03063620 (Vannamei), 03063630 (Indian white shrimp), 03063640 (Black tiger shrimp), 03063650 (Flower Shrimp), 03063660 (Artemia), 03063690 (Other).", "Heading 0306 — code 03063100 description in PDF includes a multi-part policy condition spanning Panulirus polyphagus, Panulirus homarus, and Panulirus Ornatus sizing/processing rules. Captured verbatim in policy_conditions.", "Heading 0307 — subheading 0307.39 represented by 6-digit row ''030739'' (Mussels (Mytilus spp., Perna spp.) : -- Other) with children 03073910 (Clams, clam meat (bivalves-Victorita, spp., Mertrix spp. and Katalysia spp.)) and 03073990 (Other).", "Heading 0307 — subheading 0307.42 represented by 6-digit row ''030742'' (Cuttle fish and squid : -- Live, fresh or chilled) with children 03074210 (Cuttle fish) and 03074220 (Squid).", "Heading 0307 — subheading 0307.43 represented by 6-digit row ''030743'' (Cuttle fish and squid : -- Frozen) with children 03074310 (Cuttle fish), 03074320 (Whole squids), 03074330 (Squid tubes), 03074390 (Other).", "Heading 0307 — subheading 0307.49 represented by 6-digit row ''030749'' (Cuttle fish and squid : -- Other) with children 03074910 (Cuttle fish), 03074920 (Whole squids), 03074930 (Squid tubes), 03074940 (Dried squids), 03074990 (Other).", "Heading 0308 — subheading 0308.30 represented by 6-digit row ''030830'' (Jellyfish (Rhopilema spp.)) with children 03083010 (Live, fresh or chilled), 03083020 (Dried, salted or frozen), 03083090 (Other). Subheading 0308.90 has the single 8-digit code 03089000 (Other).", "Heading 0309 — subheading 0309.10 represented by 6-digit row ''030910'' (Of fish:) with children 03091010 (Fresh or chilled), 03091020 (Frozen), 03091030 (Salted, in brine, dried or smoked), 03091090 (Other). Subheading 0309.90 represented by ''030990'' (Other:) with children 03099011–03099090 covering crustaceans (fresh/chilled, frozen, salted/brine/dried/smoked categories) and molluscs (fresh/chilled, frozen, salted/brine/dried/smoked).", "All tariff lines preserve their PDF descriptions verbatim, including the long Herrings/anchovies/sardines family lists for heading 0302 and 0303 lines and the long Tilapias/catfish/carp lists for tilapia-family lines. Many descriptions contain missing spaces between species names (e.g., ''anchoviespallasii'', ''ypophthalmichthys'', ''Katsuwonuspelamis'', ''Litopenaeusvannamei'', ''Fenneropenaeusindicus'', ''Penaeussemisulcatus'', ''Macrobachium'', ''INBRINE'', ''stripebellied'') — these are OCR/source artifacts and are preserved verbatim.", "Export Licensing Note 2 (''?as tail? means without head.'') uses ''?'' as placeholder for typographic quote marks. The note refers to terminology used in the policy conditions for crustacean exports (e.g., ''as tail'' weight specifications for lobsters/shrimps).", "Policy Condition for tariff lines 03028930 and 03038950 (Pomfret) is identical: ''However, Exports of Fresh or Chilled or Frozen silver pomfrets of weight less than 300 gms is permitted only under Restricted Export Authorization.'' Captured in policy_conditions.", "Codes 03029200 and 03039200 (Shark fins) have Export Policy ''Prohibited'' (not ''Free'') with Notification No ''110/2009-14''. Code 03057100 (Shark fins) also ''Prohibited'' (no notification number shown). Code 03061100 / 03063100 (Rock lobster and other sea crawfish) have complex policy conditions on minimum weight/preparation."]'::jsonb, '{}'::jsonb, 'Chapter 03 Fish And Crustaceans, Molluscs And Other Aquatic Invertebrates.pdf', ('2026-05-22')::timestamptz, NOW()),
  ('04', 'I', 'DAIRY PRODUCE; BIRDS'' EGGS; NATURAL HONEY; EDIBLE PRODUCTS OF ANIMAL ORIGIN, NOT ELSEWHERE SPECIFIED OR INCLUDED', '[{"number": "1", "text": "The expression milk means full cream milk or partially or completely skimmed milk"}, {"number": "2", "text": "For the purposes of heading 0403, yogurt may be concentrated or flavoured and may contain added sugar or other sweetening matter, fruit, nuts, cocoa, chocolate, spices, coffee or coffee extracts, plants, parts of plants, cereals or bakers wares, provided that any added substance is not used for the purpose of replacing, in whole or in part, any milk constituent, and the product retains the essential character of yogurt."}, {"number": "3", "text": "For the purposes of heading 0405 : (a) the term \"butter\" means natural butter, whey butter or recombined butter (fresh, salted or rancid, including canned butter) derived exclusively from milk, with a milkfat content of 80% or more but not more than 95% by weight, a maximum milk solids-not-fat content of 2% by weight and a maximum water content of 16% by weight. Butter does not contain added emulsifiers, but may contain sodium chloride, food colours, neutralising salts and cultures of harmless lacticacidproducing bacteria; (b) the expression \"dairy spreads\" means a spreadable emulsion of the water-in-oil type, containing milkfat as the only fat in the product, with a milkfat content of 39% or more but less than 80% by weight."}, {"number": "4", "text": "Products obtained by the concentration of whey and with the addition of milk or milkfat are to be classified as cheese in heading 0406 provided that they have the three following characteristics : (a) a milkfat content, by weight of the dry matter, of 5 % or more; (b) a dry matter content, by weight, of at least 70 % but not exceeding 85 %; and (c) they are moulded or capable of being moulded."}, {"number": "5", "text": "This Chapter does not cover: (a) non-living insects, unfit for human consumption (heading 0511); (b) products obtained from whey, containing by weight more than 95% lactose, expressed as anhydrous lactose, calculated on the dry matter (heading 1702); (c) products obtained from milk by replacing one or more of its natural constituents (for example, butyric fats) by another substance (for example, oleic fats) (heading 1901 or 2106); or (d) Albumins (including concentrates of two or more whey proteins, containing by weight more than 80% whey proteins, calculated on the dry matter) (heading 3502) or globulins (heading 3504)."}, {"number": "6", "text": "For the purposes of heading 0410, the term \"insects\" means edible non-living insects, whole or in parts, fresh, chilled, frozen, dried, smoked, salted or in brine, as well as flours and meals of insects, fit for human consumption. However, it does not cover edible non-living insects otherwise prepared or preserved (generally Section IV)."}]'::jsonb, '[{"number": "1", "text": "For the purposes of sub-heading 0404 10, the expression \"modified whey\" means products consisting of whey constituents, that is, whey from which all or part of the lactose, proteins or minerals have been removed, whey to which natural whey constituents have been added, and products obtained by mixing natural whey constituents."}, {"number": "2", "text": "For the purposes of sub-heading 0405 10, the term \"butter\" does not include dehydrated butter or ghee (sub-heading 0405 90)."}]'::jsonb, '[{"number": "1", "text": "In this Chapter, \"wild animal\" means wild animal as defined in the Wild Life (Protection) Act, 1972 (53 of 1972)."}]'::jsonb, '[{"number": "1", "text": "The expression ?milk? means full cream milk of partially or completely skimmed milk."}, {"number": "2", "text": "Export of 1,600 MTs of Milk Powder per annum to Bhutan (as per Calendar year i.e. 1st January to 31st December) will be exempted from any export ban."}]'::jsonb, '[]'::jsonb, '["PDF source uses 8-digit codes without dots (e.g., ''04011000''). Normalized to NNNN.NN.NN format (e.g., ''0401.10.00'') per project schema. Subheading numbers in PDF (e.g., ''040210'', ''040229'', ''040410'') normalized to NNNN.NN (e.g., ''0402.10'', ''0402.29'', ''0404.10'').", "PDF table-chrome headers (''Sl.No. Notes Notification No Notification Date'', ''Sl.No. Notes Notification Date Notification No'', ''Itc(hs) Code. Description Export Policy Policy Condition'', ''Main Notes'', ''Sub-Heading Notes'', ''Supplementary Notes'', ''Policy Condition'', ''Export Licensing Notes'', ''Product Description and Export Policy'') were recognized as table headers and EXCLUDED from the legal notes per extraction rules.", "PDF Chapter 04 Main Note 3 renders quote marks around ''butter'' and ''dairy spreads'' as quadruple-quote artifacts (''\"\"\"butter\"\"\"'', ''\"\"\"dairy spreads\"\"\"''). These are OCR/encoding artifacts from the source PDF — normalized to standard double-quoted form (''\"butter\"'', ''\"dairy spreads\"'') in the captured text for readability.", "Export Licensing Note 1 renders quote marks around ''milk'' as ''?milk?'' (OCR artifact, same pattern as Chapter 09). Preserved verbatim as it appears in the source PDF — intended text is ''milk'' in quotation marks.", "Export Licensing Note 1 text in Chapter 04 PDF reads ''full cream milk of partially or completely skimmed milk'' — preserved verbatim. Note that Chapter 04 Main Note 1 (the legal note) uses the canonical phrasing ''full cream milk or partially or completely skimmed milk'' (with ''or'' instead of ''of''); the Export Licensing Note retains the PDF''s typo verbatim.", "Heading 0403 description in PDF appears in ALL CAPS (''YOGURT; BUTTERMILK, CURDLED MILK AND CREAM, KEPHIR AND OTHER FERMENTED OR ACIDIFIED MILK AND CREAM, WHETHER OR NOT CONCENTRATED OR CONTAINING ADDED SUGAR OR OTHER SWEETENING MATTER OR FLAVOURED OR CONTAINING ADDED FRUIT, NUTS OR COCOA'') as does heading 0410 (''INSECTS AND OTHER EDIBLE PRODUCTS OF ANIMAL ORIGIN, NOT ELSEWHERE SPECIFIED OR INCLUDED''). Preserved as a Title-Case rendering for consistency with other headings; the original ALL-CAPS form is the canonical Schedule presentation.", "Section I (LIVE ANIMALS; ANIMAL PRODUCTS) Main Notes table on PDF page 1 contains two notes (Note 1: ''young of that genus or species''; Note 2: ''\"dried\" products also covers products which have been dehydrated, evaporated or freeze-dried.''). Both are captured in the section_notes array.", "Subheading 0406.10 appears duplicated in the source PDF (two rows for ''040610 Fresh (unripened or uncured) cheese, including whey cheese, and curd :'' followed by duplicate tariff lines ''04061010 Mozzarella cheese'' and ''04061090 Other''). Deduplicated to a single subheading entry with two unique tariff lines.", "Subheading 0410.10 (''Insects:'') and 0410.90 (''Other:'') are presented in the PDF under heading 0410 (INSECTS AND OTHER EDIBLE PRODUCTS OF ANIMAL ORIGIN, NOT ELSEWHERE SPECIFIED OR INCLUDED). Subheading codes are inferred from the 6-digit PDF rows ''041010'' and ''041090''.", "Tariff lines under headings 0407, 0408, 0409, 0410 display ''Subject to Policy Condition 1 of the Chapter'' in the Policy Condition column. Captured in the policy_conditions array. Tariff line 04090000 (Natural Honey) has additional product-specific export conditions (Minimum Export Price of US$ 1400/MT till 31.12.2025, and conditions for export to USA/EU per Notification No. 27/2025-26 dated 22/08/2025) — captured in policy_conditions with applies_to_tariff_lines scoped to ''0409.00.00''.", "Tariff lines under heading 0402 (''Skimmed Milk'', ''Milk food for babies'', ''Other'', etc.) show Notification No ''25(RE-2012)/2009-2014'' (and ''2(RE-2012)/2009-2014'' for 04021010) dated ''08.06.2012'' / ''22.11.2012''. These appear in the policy_conditions array as the historical notifications regulating Milk Powder export (per Export Licensing Note 2).", "Tariff line 04022990 description in the PDF reads ''Other Other:'' (with trailing colon) — preserved verbatim. Heading 0408 tariff line 04089900 description reads ''Other -- Other'' (double-dash, single space) — preserved verbatim.", "Heading 0409 has no subheading row in the PDF — tariff line 04090000 ''Natural Honey'' is attached directly. Modeled as subheading 0409.00 with single tariff line 0409.00.00, consistent with the canonical chapter-09 pattern for heading 0903 (''Maté'' / ''09030000'')."]'::jsonb, '{}'::jsonb, 'Chapter 04 Dairy Produce; Birds Eggs; Natural Honey; Edible Products Of Animal Origin, Not Elsewhere Specified Or Included.pdf', ('2026-05-22')::timestamptz, NOW()),
  ('05', 'I', 'PRODUCTS OF ANIMAL ORIGIN, NOT ELSEWHERE SPECIFIED OR INCLUDED', '[{"number": "1", "text": "This Chapter does not cover: (a) edible products(other than guts, bladders and stomachs of animals, whole and piecesthereof, and animal blood, liquid or dried); (b) hides or skins (including furskins) other than goods of heading 0505 and parings and similar waste of raw hides or skins of heading 0511 (Chapter 41 or 43); (c) animal textile materials, other than horsehair and horsehair waste (Section XI); or (d) prepared knots or tufts for broom or brush making (heading 9603)"}, {"number": "2", "text": "For the purposes of heading 0501, the sorting of hair by length (provided the root ends and tip ends respectively are not arranged together) shall be deemed not to constitute working."}, {"number": "3", "text": "Throughout this Schedule, elephant, hippopotamus, walrus, narwhal and wild boar tusks, rhinoceros horns and the teeth of all animals are regarded as \"ivory\"."}, {"number": "4", "text": "Throughout the Schedule, the expression \"horsehair\" means hair of the manes or tails of equine or bovine animals. Heading 0511 covers, inter alia, horsehair and horsehair waste, whether or not put up as a layer with or without supporting material."}]'::jsonb, '[]'::jsonb, '[{"number": "1", "text": "In thisChapter, the expressions \"wild animal\" and \"wild life\" have the meaningsrespectively assigned to them in clauses (36) and (37) of section 2 of the Wild Life (Protection) Act, 1972 (53 of 1972); and the expression \"wild bird\" means any bird specified in Schedules to that Act."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["PDF source uses 8-digit codes without dots (e.g., ''05010010'') and 6-digit subheading numbers without dots (e.g., ''050100''). Normalized to NNNN.NN.NN format for tariff lines (e.g., ''0501.00.10'') and NNNN.NN for subheadings (e.g., ''0501.00'') per project schema.", "PDF table-chrome headers (''Sl.No. Notes Notification No Notification Date'', ''Sl.No. Notes Notification Date Notification No'', ''Itc(hs) Code. Description Export Policy Policy Condition'', ''Main Notes'', ''Supplementary Notes'', ''Policy Condition'', ''Export Licensing Notes'', ''Product Description and Export Policy'') were recognized as table headers and EXCLUDED from the legal notes per extraction rules.", "Section I ''Main Notes'' (2 notes) are attributed to section_notes (Section I, LIVE ANIMALS; ANIMAL PRODUCTS), not chapter_notes. Chapter 05 ''Main Notes'' (4 notes) are attributed to chapter_notes.", "Heading 0503 and heading 0509 do not appear in the PDF — these heading numbers are reserved/deleted in the ITC(HS) schedule and have no tariff lines. Skipped in the headings array.", "Note 1 of Chapter 05 (the exclusion note) contains several OCR/spacing artifacts in the source PDF: ''edible products(other than guts, ...)'' (missing space after ''products''), ''piecesthereof'' (missing space), ''animal blood, liquid or dried'' (commas preserved verbatim). Preserved verbatim as they appear in the source.", "Supplementary Note 1 contains OCR spacing artifacts: ''In thisChapter'' (missing space), ''meaningsrespectively'' (missing space). Preserved verbatim.", "Policy Condition rows contain ''?'' characters in place of typographic quote marks (e.g., ''Shipment Clearance Certificate?'', ''Production Process Certificate?'', ''Health Certificate?''). These are OCR/encoding artifacts from the source PDF — preserved verbatim as they appear in the source. The intended text is the certificate names enclosed in quotation marks.", "Policy Condition 4 contains a repeated phrase due to source rendering: ''Export of Bone and bone products Bone and Bone Products, horn and horn products hooves and hoof products, Bile, ...''. The duplication of ''Bone and bone products'' is preserved verbatim as it appears in the source PDF.", "Tariff line 0511.99.91 description ''Other: ---- Frozen semen, other than bovine :bovine embryo:'' has an inline policy condition fragment in the source PDF Policy Condition column: ''Export of Gonads and other reproductive organs of buffaloes &Germplasm of Cattle and buffaloes is restricted.'' This is preserved as the description-level policy condition for that line.", "Tariff line 0511.99 has description ''other -- Other'' (lowercase ''other'') in the PDF. Preserved verbatim.", "Subheading 0511.91 description in PDF: ''Other : -- Products of fish or crustaceans, molluscs or other aquatic invertebrates; dead animals of Chapter 3'' — verbatim.", "Tariff line 0508.00.20 (Chanks), 0508.00.30 (Cowries), 0508.00.50 (Shells) have multi-sentence policy condition text in the Policy Condition column (e.g., references to Wild Life (Protection) Act, 1972 and CITES). Captured at tariff_line level.", "Tariff line 0506.10.49 (Bones, horn cones and parts thereof, not crushed: ---- Other) has a multi-clause policy condition: ''1. Export of Human Skeletons and Shavings of Shed Antlers of Chital and Sambhar is prohibited and not permitted to be exported 2. Subject to Policy Condition 1, 3 &4 of the Chapter''. Preserved verbatim.", "Tariff line 0511.99.99 (Other: ---- Other) has a multi-clause policy condition referencing ICMR No Objection Certificate for Human Embryos/Gametes/Gonad tissues, restriction on Germplasm of Cattle and buffaloes, and prohibition on Human Skeletons / shed antlers of chital/sambhar / peacock tail feathers handicrafts. Preserved verbatim.", "Export Licensing Notes section contains 2 notes (handicrafts of bone/horn; wild animals/CITES). Captured in export_licensing_notes scope of policy_conditions.", "Policy Condition 2 text references ''European Union'' — the PDF renders ''Pig Bristles and Hair'' policy as allowed freely except to EU, with detailed CAPEXIL certification conditions. Preserved verbatim including ''?'' OCR quote artifacts."]'::jsonb, '{}'::jsonb, 'Chapter 05 Products Of Animal Origin, Not Elsewhere Specified Or Included.pdf', ('2026-05-22')::timestamptz, NOW()),
  ('06', 'II', 'LIVE TREES AND OTHER PLANTS; BULBS, ROOTS AND THE LIKE; CUT FLOWERS AND ORNAMENTAL FOLIAGE', '[{"number": "1", "text": "Subject to the second part of heading 0601, this Chapter covers only live trees and goods (including seedling vegetables) of a kind commonly supplied by nursery gardeners or florists for planting or for ornamental use; nevertheless it does not include potatoes, onions,shallots, garlic or other products of Chapter 7."}, {"number": "2", "text": "Any reference in heading 0603 or 0604 to goods of any kind shall be construed as including a reference to bouquets, floral baskets, wreaths and similar articles made wholly or partly of goods of that kind, account not being taken of accessories of other materials. However, these headings do not include collages or similar decorative plaques of heading 9701."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["PDF source uses 8-digit codes without dots (e.g., ''06011000'') and 6-digit subheading numbers without dots (e.g., ''060120''). Normalized to NNNN.NN.NN and NNNN.NN format per project schema.", "PDF table-chrome headers (''Main Notes'', ''Policy Condition'', ''Export Licensing Notes'', ''Product Description and Export Policy'', ''Sl.No. Notes Notification Date Notification No'', ''Itc(hs) Code. Description Export Policy Policy Condition'') were recognized as table headers and EXCLUDED from the legal notes per extraction rules.", "Section II Main Note about ''pellets'' appears on PDF page 1 above the Chapter 06 title and is attributed to section_notes (Section II, Vegetable Products), not chapter_notes. Chapter 06 itself has 2 Main Notes.", "Chapter Note 1 in the source PDF reads: ''Subject to the second part of heading 0601, this Chapter covers only live trees and goods (including seedling vegetables) of a kind commonly supplied by nursery gardeners or florists for planting or for ornamental use; nevertheless it does not include potatoes, onions,shallots, garlic or other products of Chapter 7.'' — the spacing artefacts (''neverthelessit'', ''onions,shallots'') are preserved verbatim as they appear in the source.", "Source PDF spelling artifacts preserved verbatim: ''edible furit or nuts'' (heading 0602.20 title — should be ''fruit''); ''Poliocy Condition'' in column header for tariff line 0602.90.90 (should be ''Policy Condition''). These are typographical errors in the source ITC(HS) PDF.", "Tariff line 0602.20.10 (''Edible fruit or nut trees, grafted or not'') shows Export Policy ''Restricted'' with Policy Condition text ''Exports of Cashew seeds and plants is restricted.'' — captured in policy_conditions array. All other tariff lines in headings 0601–0602 show Export Policy ''Free'' with ''Subject to Policy Condition 1 of the Chapter''; tariff lines in 0603 and 0604 show ''Free'' with no Chapter policy condition. Tariff line 0602.90.90 references ''Policy Condition 2 of the Chapter''.", "Export Licensing Notes section (3 entries) uses ''??formulation?'' rendering where the source PDF substitutes typographic quote marks with ''?'' characters — preserved verbatim. Intended text is ''formulation'' enclosed in quotation marks.", "Subheading 0601.10 in the source appears only as the 8-digit tariff line ''06011000'' (no separate 6-digit subheading row); rendered as subheading ''0601.10'' with single tariff line ''0601.10.00''. Similarly for 0602.10 (''06021000''), 0602.30 (''06023000''), 0602.40 (''06024000''), 0604.20 (''06042000''), 0604.90 (''06049000''), and heading 0603 lines ''06031100'' through ''06039000'' which appear as 8-digit codes with no separate 6-digit subheading row — rendered as subheadings 0603.11, 0603.12, 0603.13, 0603.14, 0603.15, 0603.19, 0603.90 each with a single tariff line ending in ''.00''.", "Heading 0604 in the source PDF has only two tariff lines (0604.20.00 ''Fresh'' and 0604.90.00 ''Other''). The HS 2022 nomenclature subheadings 0604.20 ''Fresh'' and 0604.90 ''Other'' are represented at the 8-digit tariff line level only in the ITC(HS) Schedule 2 source — preserved as in source."]'::jsonb, '{}'::jsonb, 'Chapter 06 Live Trees And Other Plants; Bulbs, Roots And The Like; Cut Flowers And Ornamental Foliage.pdf', ('2026-05-22')::timestamptz, NOW()),
  ('07', 'II', 'EDIBLE VEGETABLES AND CERTAIN ROOTS AND TUBERS', '[{"number": "1", "text": "This Chapter does not cover forage products of heading 1214."}, {"number": "2", "text": "In headings 0709, 0710, 0711 and 0712, the word \"vegetables\" includes edible mushrooms, truffles, olives, capers, marrows, pumpkins, aubergines, sweet corn (Zea mays var. saccharata), fruits of the genus Capsicum or of the genus Pimenta, fennel, parsley, chervil, tarragon, cress and sweet marjoram (Majorana hortensis or Origanum majorana)."}, {"number": "3", "text": "Heading 0712 covers all dried vegetables of the kinds falling in headings 0701 to 0711, other than: (a) dried leguminous vegetables,shelled (heading 0713); (b) sweet corn in the forms specified in headings 1102 to 1104; (c) flour, meal, powder, flakes, granules and pellets of potatoes (heading 1105); (d) flour, meal and powder of the dried leguminous vegetables of heading 0713 (heading 1106)."}, {"number": "4", "text": "However, dried or crushed or ground fruits of the genus Capsicum or of the genus Pimenta are excluded from this Chapter (heading 0904)."}, {"number": "5", "text": "Heading 0711 applies to vegetables which have been treated solely to ensure their provisional preservation during transport or storage prior to use (for example, by sulphur dioxide gas, in brine, in sulphur water or in other preservative solutions), provided they remain unsuitable for immediate consumption in that state."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["PDF source uses 8-digit codes without dots (e.g., ''07011000''). Normalized to NNNN.NN.NN format (e.g., ''0701.10.00'') per project schema. Subheading numbers in PDF (e.g., ''070310'') normalized to NNNN.NN (e.g., ''0703.10'').", "PDF table-chrome headers (''Sl.No. Notes Notification Date Notification No'', ''Itc(hs) Code. Description Export Policy Policy Condition'', ''Main Notes'', ''Policy Condition'', ''Export Licensing Notes'', ''Product Description and Export Policy'') were recognized as table headers and EXCLUDED from the legal notes per extraction rules.", "Section II Main Note about ''pellets'' appears on PDF page 1 above the Chapter 07 title and is attributed to section_notes (Section II, Vegetable Products), not chapter_notes.", "Heading 0703 description in PDF reads ''Onions, shallots, garlic, leeks and other alliaceous vegetables, fresh or chilled.'' — verbatim including trailing period.", "Heading 0704 description in PDF reads ''Cabbages, cauliflowers, kohlrabi, kale and similar edible brassicas, fresh or chilled.'' — verbatim.", "Heading 0711 description in PDF (heading-level row) reads ''VEGETABLES PROVISIONALLY PRESERVED, BUT UNSUITABLE IN THAT STATE FOR IMMEDIATE CONSUMPTION'' — all-caps in source; preserved verbatim. The official ITC(HS) full title is ''Vegetables provisionally preserved (for example, by sulphur dioxide gas, in brine, in sulphur water or in other preservative solutions), but unsuitable in that state for immediate consumption.'' but only the abbreviated form appears in this PDF — preserved as printed.", "Tariff line code ''0712.31.00'' is rendered in the PDF as ''Mushrooms of the genus lgaricus'' with a lowercase ''l'' (likely OCR artifact for ''Agaricus''). Preserved verbatim from source.", "Tariff line ''0710.80.10'' is rendered in the PDF as ''Terragon'' (likely OCR artifact for ''Tarragon''). Preserved verbatim from source.", "Subheading 0713.20 description in PDF reads ''Chickpeas (garbanzos):'' (with trailing colon). Preserved verbatim.", "Tariff line ''0712.20.00'' (Onions) has Notification No ''49/2015-20'' dated ''02.03.2020'' shown in the PDF — captured as inline metadata; export policy ''Free''.", "Tariff line ''0703.10.19'' (Onions: Other) has Notification Date ''28/2024-25'' dated ''13.09.2024'' shown in the PDF — captured as inline metadata.", "Policy Condition column: all tariff lines under heading 0713 (Dried leguminous vegetables) display ''Subject to Policy Condition 1 of the Chapter'' with Notification No ''38/2015-20'' dated ''22.11.2017''. Captured in the policy_conditions array.", "Heading 0712 description in PDF reads ''Dried vegetables, whole, cut, sliced, broken or in powder, but not further prepared.'' — verbatim.", "Heading 0714 description in PDF reads ''Manioc, arrowroot, salep, Jerusalem artichokes, sweet potatoes and similar roots and tubers with high starch or inulin content, fresh, chilled, frozen or dried, whether or not sliced or in the form of pellets; sago pith.'' — verbatim.", "No ''Supplementary Notes'' section is present in the Chapter 07 PDF — only Main Notes, Policy Condition, and Export Licensing Notes are present.", "Subheading ''0703.10'' (Onions and shallots) covers tariff lines 0703.10.11, 0703.10.19, and 0703.10.20 in the PDF — ''0703.10.20 Shallots'' is grouped under the same subheading code ''070310'' per the source structure. Preserved as printed.", "Heading 0702 in PDF appears as a single 8-digit code ''07020000'' with no separate 4-digit heading row — represented as heading 0702 with subheading 0702.00 containing tariff line 0702.00.00. Same pattern for 0707 (single tariff line 0707.00.00)."]'::jsonb, '{}'::jsonb, 'Chapter 07 Edible Vegetables And Certain Roots And Tubers.pdf', ('2026-05-22')::timestamptz, NOW()),
  ('08', 'II', 'EDIBLE FRUIT AND NUTS; PEEL OF CITRUS FRUIT OR MELONS', '[{"number": "1", "text": "This Chapter does not cover inedible nuts or fruits."}, {"number": "2", "text": "Chilled fruits and nuts are to be classified in the same headings as the correspon-ding fresh fruits and nuts."}, {"number": "3", "text": "Dried fruit or dried nuts of this Chapter may be partially rehydrated, or treated for the following purposes: (a) for additional preservation orstabilisation (for example, bymoderate heat treatment, sulphuring, the addition of sorbic acid or potassium sorbate); (b) to improve or maintain their appearance (for example, by the addition of vegetable oil or small quantities of glucose syrup), provided that they retain the character of dried fruit or dried nuts."}, {"number": "4", "text": "Heading 0812 applies to fruit and nuts which have been treated solely to ensure their provisional preservation during transport or storage prior to use (for example, by sulphur dioxide gas, in brine, in sulphur water or in other preservative solutions), provided they remain unsuitable for immediate consumption in that state."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["PDF source uses 8-digit codes without dots (e.g., ''08011100''). Normalized to NNNN.NN.NN format (e.g., ''0801.11.00'') per project schema. 6-digit subheading codes in PDF (e.g., ''080112'') normalized to NNNN.NN (e.g., ''0801.12'').", "Chapter 08 Note 3 contains an OCR artifact: the phrase ''additional preservation orstabilisation'' appears with a missing space between ''or'' and ''stabilisation''. Preserved verbatim from the source PDF. The intended reading is ''additional preservation or stabilisation''.", "Chapter 08 Note 3 contains a second OCR/typographic artifact: ''bymoderate heat treatment'' appears with a missing space between ''by'' and ''moderate''. Preserved verbatim from the source PDF. The intended reading is ''by moderate heat treatment''.", "Chapter 08 Note 2 contains a hyphenation artifact: ''correspon-ding'' is broken across lines with a hyphen in the source PDF. Preserved verbatim. The intended reading is ''corresponding''.", "Heading 0812 description in the PDF tariff table is written in ALL CAPS as ''FRUIT AND NUTS PROVISIONALLY PRESERVED, BUT UNSUITABLE IN THAT STATE FOR IMMEDIATE CONSUMPTION''. Other heading descriptions in the same table use Title Case. Preserved verbatim from source.", "PDF table-chrome headers (''Sl.No. Notes Notification No Notification Date'', ''Itc(hs) Code. Description Export Policy Policy Condition'', ''Main Notes'', ''Product Description and Export Policy'') were recognized as table headers and EXCLUDED from the legal notes per extraction rules.", "The Section II ''Main Note'' about ''pellets'' appears on PDF page 1 above the Chapter 08 title and is attributed to section_notes (Section II, Vegetable Products), not chapter_notes.", "Heading 0803 has subheading ''080310'' (Plantains) with two tariff lines (Curry plantain, Other), then a heading-level catch-all subheading ''080390'' (Other) with tariff lines ''Bananas, fresh'' and ''Other''. Note the asymmetry: 0803.10 is a plantain-specific bucket while 0803.90 is the fresh-banana bucket; this matches the WCO 6-digit single-dash structure where 0803 is split into plantains (-) and other (-).", "Heading 0804 subheading ''080450'' (Guavas, mangoes and mangosteens) contains 12 named tariff lines including a unique Indian elaboration: tariff lines 0804.50.21 through 0804.50.28 enumerate Indian mango cultivars (Alphonso/Hapus, Banganapalli, Chausa, Dasheri, Langda, Kesar, Totapuri, Mallika). This level of cultivar-specific national tariff detail is rare and reflects mango export priority.", "Heading 0807 subheading 080719 has tariff lines 0807.19.10 (Musk melons) and 0807.19.90 (Other). No subheading is shown for 0807.20; 0807.20.00 (Papaws) appears as a standalone 8-digit code in the source. Reconstructed: 0807.20 is treated as a single-tariff-line subheading.", "Heading 0808 (Apples, pears and quinces, fresh.) has only three tariff lines in the source (0808.10.00 Apples, 0808.30.00 Pears, 0808.40.00 Quinces). No subheadings 0808.20 are shown — this is consistent with the WCO 2017 amendment that split former 0808.20 (pears and quinces) into 0808.30 (pears) and 0808.40 (quinces).", "Heading 0809 covers ''Apricots, cherries, peaches (including nectarines), plums and sloes, fresh.'' Subheading 0809.10.00 (Apricots), 0809.30.00 (Peaches, including nectarines), 0809.40.00 (Plums and sloes) appear as standalone 8-digit codes; only Cherries has the 0809.21 / 0809.29 sub-split (Sour cherries vs Other). Reconstructed accordingly.", "Heading 0810 (Other fruit, fresh.) subheading ''081090'' (Other) contains a notable Indian elaboration with named tariff lines for Pomegranates (0810.90.10), Tamarind, fresh (0810.90.20), Sapota/chico (0810.90.30), Custard-apple/Ata (0810.90.40), Bore (0810.90.50), Lichi (0810.90.60), and Other (0810.90.90). ''Lichi'' is preserved verbatim (the more common spelling is ''Lychee'').", "Heading 0811 covers frozen fruit and nuts. The PDF lists subheading 081110 (Strawberries) with tariff lines 0811.10.10 (Containing added sugar), 0811.10.20 (Not containing added sugar), and 0811.10.90 (Other). The ''Other'' line at the .90 suffix is unusual because the named binary split (with/without added sugar) typically exhausts the subheading; preserved verbatim.", "Heading 0812 description in PDF is ''FRUIT AND NUTS PROVISIONALLY PRESERVED, BUT UNSUITABLE IN THAT STATE FOR IMMEDIATE CONSUMPTION'' (all caps, no trailing period). Verbatim preservation.", "Heading 0813 subheading 081350 is described as ''Mixtures of nuts or dried fruits of this Chapter'' with tariff lines 0813.50.10 (Mixtures of nuts) and 0813.50.20 (Mixtures of dried fruits). Note: the PDF does not include an 0813.50.90 line.", "Heading 0814 has only one tariff line (0814.00.00 — Peel of citrus fruit or melons...). No subheadings present. The full description spans multiple lines in the PDF: ''Peel of citrus fruit or melons (including watermelons), fresh, frozen, dried or provisionally preserved in brine, in sulphur water or in other preservative solutions''. Preserved verbatim.", "Chapter 08 contains NO entries in the Policy Condition column for any tariff line EXCEPT 0806.10.00 (Grapes, Fresh) which has Policy Condition: ''Exports of Grapes, Fresh to European Union is permitted subject to registration with APEDA.'' (Notification 28 (RE ? 2012)/2009-2014 dated 03.01.2013). The ''?'' in the notification number is an OCR artifact from the source PDF; the intended character is likely a hyphen ''-'' (i.e., ''28 (RE - 2012)/2009-2014'').", "All 84 tariff lines in Chapter 08 have Export Policy = ''Free'' except heading-level and subheading-level rows which have no policy column populated (these are container rows, not classifiable codes). No tariff line is Prohibited or Restricted.", "PDF page count: 13 pages total. Pages 1-2 contain section + chapter notes. Pages 3-13 contain the tariff schedule."]'::jsonb, '{}'::jsonb, 'Chapter 08 Edible Fruit And Nuts; Peel Of Citrus Fruit Or Melons.pdf', ('2026-05-21')::timestamptz, NOW()),
  ('09', 'II', 'COFFEE, TEA, MATÉ AND SPICES', '[{"number": "1", "text": "Mixtures of the products of headings 0904 to 0910 are to be classified as follows: (a) mixtures of two or more of the products of the same heading are to be classified in that heading; (b) mixtures of two or more of the products of different headings are to be classified in heading 0910. The addition of other substances to the products of headings 0904 to 0910 [or to the mixtures referred to in paragraph (a) or (b) above] shall not affect their classification provided the resulting mixtures retain the essential character of the goods of those heading. Otherwise such mixtures are not classified in this Chapter; those constituting mixed condiments or mixed seasonings are classified in heading 2103."}, {"number": "2", "text": "This Chapter does not cover Cubeb pepper (Piper cubeba) or other products of heading 1211."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["PDF source uses 8-digit codes without dots (e.g., ''09011111''). Normalized to NNNN.NN.NN format (e.g., ''0901.11.11'') per project schema. Subheading numbers in PDF (e.g., ''090111'') normalized to NNNN.NN (e.g., ''0901.11'').", "PDF contains ''?'' characters in place of typographic quote marks in the Export Licensing Notes (e.g., ''?Spice?'' and ''?masalas?''). These are OCR/encoding artifacts from the source PDF — preserved verbatim as they appear in the source. The intended text is ''Spice'' and ''masalas'' enclosed in quotation marks.", "The chapter title on PDF page 1 is rendered as ''Chapter 09 Coffee, Tea, Mat And Spices.'' — the official ITC(HS) chapter title is ''COFFEE, TEA, MATÉ AND SPICES'' (heading 0903 in the chapter is ''Maté''). Title field uses the canonical form with diacritic; source_pdf field preserves the abbreviated filename form.", "PDF table-chrome headers (''Sl.No. Notes Notification No Notification Date'', ''Itc(hs) Code. Description Export Policy Policy Condition'', ''Main Notes'', ''Policy Condition'', ''Export Licensing Notes'', ''Product Description and Export Policy'') were recognized as table headers and EXCLUDED from the legal notes per extraction rules.", "Heading 0903 (''Maté'') is represented in the PDF as the single tariff line ''09030000'' with description ''Mate''. No subheading row appears in the source; tariff line is attached directly under the heading. The accented spelling ''Maté'' is reflected in the chapter title; the heading description in the PDF reads ''Mate'' (without accent) and is preserved verbatim.", "Heading 0904 description in PDF reads ''Pepper of the genus Piper; dried or crushed or ground fruits of the genus Capsicum or of the genus Pimenta.'' — verbatim, including the trailing period.", "Section II Main Note about ''pellets'' appears on PDF page 1 above the Chapter 09 title and is attributed to section_notes (Section II, Vegetable Products), not chapter_notes.", "Tariff line code ''09092200'' represents subheading 0909.22 with tariff suffix ''00'' — preserved as the 8-digit form ''0909.22.00'' under subheading ''0909.22''. Similar pattern for ''09030000'', ''09011200'', ''09081200'', ''09082100'', ''09082200'', ''09051000'', ''09052000'', ''09062000'', ''09072000'', ''09093200'' — all are 8-digit codes where the subheading has only one tariff line (the ''00'' line).", "Policy Condition: tariff lines from heading 0904 onwards display ''Subject to Policy Condition 1 of the Chapter'' with Notification No ''32/2015-20'' dated ''04.10.2017''. This is captured in the policy_conditions array."]'::jsonb, '{}'::jsonb, 'Chapter 09 Coffee, Tea, Mat And Spices.pdf', ('2026-05-21')::timestamptz, NOW()),
  ('10', 'II', 'Cereals', '[{"number": "1", "text": "(a) The products specified in the headings of this Chapter are to be classified in those headings onlyif grains are present, whether or not in the ear or on the stalk. (b) This Chapter does not cover grains which have been hulled or otherwise worked. However, rice, husked, milled, polished, glazed, parboiled or broken remains classified in heading 1006. Similarly, quinoa from which the pericarp has been wholly or partly removed in order to separate thesaponin, but which has not undergone any other processes, remains classified in heading 1008."}, {"number": "2", "text": "Heading 1005 does not cover sweet corn (Chapter 7)."}]'::jsonb, '[{"number": "1", "text": "The term \"Durum wheat\" means wheat of the Triticum durum species and the hybrids derived from the inter-specific crossing of Triticum durum which have the same number (28) of chromosomes as that species."}]'::jsonb, '[]'::jsonb, '[{"number": "1", "text": "Export of wild variety of wheat and paddy seed is restricted."}, {"number": "2", "text": "The above conditions in respect of export of Non Basmati Rice will not be applicable to exports undertaken as under: Export of non-Basmati rice (i) under Food Aid Programme and (ii) under bi-lateral trade agreement between Government of India and Government of Maldives shall be permitted. Export of 21,200 MTs per annum to Bhutan (as per Calender year i.e. from 1st January to 31st December) of non-Basmati rice will be exempted from any export ban."}, {"number": "3", "text": "Export of Organic non-Basmati Rice (excluding rice in husk paddy or rough) from Custom EDI ports have been exempted from all quantitative ceilings irrespective of any existing or future restriction/ prohibition on export of their basic product (non-organic), with due certification by APEDA as organic under the NPOP.", "notification_date": "19.04.2017", "notification_no": "03/2015-2020"}, {"number": "4", "text": "Export of organic wheat from Custom EDI ports have been exempted from all quantitative ceilings irrespective of any existing or future restriction/ prohibition on export of their basic product (non-organic), with due certification by APEDA as organic under the NPOP.", "notification_date": "19.04.2017", "notification_no": "03/2015-2020"}, {"number": "5", "text": "Export of wheat per annum to Bhutan (as per Calendar year i.e. 1st January to 31st December) shall be exempted from any export ban."}, {"number": "6", "text": "Export of Organic Non-Basmati Rice, including Organic Non-basmati broken Rice, will be governed as per provisions under Notification No. 03/2015-20 dated 19th April, 2017.", "notification_date": "19.04.2017", "notification_no": "03/2015-2020"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, 'Chapter 10 Cereals.pdf', NULL, NOW()),
  ('11', 'II', 'PRODUCTS OF THE MILLING INDUSTRY; MALT; STARCHES; INULIN; WHEAT GLUTEN', '[{"number": "1", "text": "This Chapter does not cover : (a) roasted malt put up as coffee substitutes (heading 0901 or 2101); (b) prepared flours, groats, meals or starches of heading 1901; (c) corn flakes or other products of heading 1904; (d) vegetables, prepared or preserved, of heading 2001, 2004 or 2005; (e) pharmaceutical products (Chapter 30); or (f) starches having the character of perfumery, cosmetic or toilet preparations (Chapter 33)."}, {"number": "2", "text": "(A) Productsfrom the milling of the cerealslisted in the table below fall in this Chapter if they have, by weight on the dry product : (a) a starch content(determined by themodified Ewers polarimetric method) exceeding that indicated in column (2); and (b) an ash content (after deduction of any added minerals) not exceeding that indicated in column (3). Otherwise, they fall in heading 2302. However, germ of cereals, whole, rolled, flaked or ground, is always classified in heading 1104. (B) Products falling in this Chapter under the above provisions shall be classified in heading 1101 or 1102 if the percentage passing through a woven metal wire cloth sieve with the aperture indicated in column (4) or (5) is not less, by weight, than that shown against the cereal concerned. Otherwise, they fall in heading 1103 or 1104. Cereal Starch content Ash content Rate of passage through a sieve with an aperture of 315 micrometres (microns) 500 micrometres (microns) (1) (2) (3) (4) (5) Wheat and rye 45% 2.5% 80% - Barley 45% 3% 80% - Oats 45% 5% 8 0% - Maize (corn) and 45% 2% - 90% grain soghum Rice 45% 1.6% 80% - Buckwheat 45% 4% 80% -"}, {"number": "3", "text": "For the purposes of heading 1103, the terms \"\"groats\"\" and \"\"meal\"\" mean products obtained by the fragmentation of cereal grains, of which : (a) in the case of maize (corn) products, at least 95% by weight passes through a woven metal wire cloth sieve with an aperture of 2 mm; (b) in the case of other cereal products, at least 95% by weight passes through a woven metal wire cloth sieve with an aperture of 1.25 mm."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["PDF source uses 8-digit codes without dots (e.g., ''11010000'') and 6-digit subheading codes without dots (e.g., ''110290''). Normalized to NNNN.NN.NN format (e.g., ''1101.00.00'') and NNNN.NN format (e.g., ''1102.90'') per project schema.", "PDF table-chrome headers (''Main Notes'', ''Sl.No. Notes Notification No Notification Date'', ''Sl.No. Notes Notification Date Notification No'', ''Product Description and Export Policy'', ''Itc(hs) Code. Description Export Policy Policy Condition'') were recognized as table chrome and EXCLUDED from the legal notes per extraction rules.", "Chapter title on PDF page 1 (above the chapter Main Notes table) reads ''Chapter 11 Products Of The Milling Industry; Malt; Starches; Inulin; Wheat Gluten.'' The canonical ITC(HS) chapter title ''PRODUCTS OF THE MILLING INDUSTRY; MALT; STARCHES; INULIN; WHEAT GLUTEN'' is used in the title field; source_pdf preserves the PDF filename.", "Section II ''Main Notes'' (1 note on pellets) appears above the Chapter 11 title and is attributed to section_notes (Section II, Vegetable Products), not chapter_notes.", "Chapter 11 Main Note 2 spans the PDF page break between page 1 and page 2 and contains an inline tabular description of cereal Starch content / Ash content / Rate of passage (sieve apertures 315 microns and 500 microns) for Wheat and rye, Barley, Oats, Maize (corn) and grain sorghum, Rice, Buckwheat. The five tabular columns (1)-(5) are rendered as inline text in the PDF and preserved verbatim. The Maize (corn) / grain sorghum row has an empty (5) column (preserved as ''-'').", "Chapter 11 Main Note 3 PDF text contains ''\"\"groats\"\"'' and ''\"\"meal\"\"'' (double double-quotes) as OCR artifacts of typographic quotes. Preserved verbatim from source.", "Heading 1101 in the PDF is represented only by the 8-digit tariff line ''11010000'' (''Wheat or meslin flour.'') with no separate 4-digit heading row above it. Heading title is inferred from the tariff line description (''Wheat or meslin flour.'') per WCO HS nomenclature. Subheading ''1101.00'' synthesized as the parent of ''1101.00.00'' (single-line heading).", "Heading 1102 in the PDF reads ''CEREAL FLOURS OTHER THAN THAT OF WHEAT OR MESLIN'' in ALL CAPS. Preserved verbatim.", "Subheading 1102.90 ''Other'' contains tariff lines 1102.90.10 (Rye flour), 1102.90.21 (Rice flour: ---- Brown rice flour), 1102.90.22 (Rice flour: ---- White rice flour), 1102.90.29 (Rice flour: ---- Other), 1102.90.90 (Other). The ''Rice flour'' group (.21/.22/.29) is a sub-group under 1102.90 — descriptions preserved verbatim including the '': ---- '' indicator.", "Subheading 1103.11 ''Groats and meal : -- Of wheat'' contains two tariff lines: 1103.11.10 (Groat) and 1103.11.20 (Meal). Tariff line description ''Groat'' (singular) is preserved verbatim from the PDF, even though the parent subheading uses plural ''Groats and meal''.", "Heading 1104 description in the PDF spans multiple lines: ''Cereal grains otherwise worked (for example, hulled, rolled, flaked, pearled, sliced or kibbled), except rice of heading 10.06; germ of cereals, whole, rolled, flaked or ground.'' — preserved verbatim including the heading reference ''10.06'' with internal dot.", "Subheadings 1104.12, 1104.19 (''Rolled or flaked grains''), 1104.22, 1104.23, 1104.29 (''Other worked grains''), and 1104.30 (''Germ of cereals'') in the PDF have descriptions repeated on each tariff line (no separate 6-digit subheading row). Subheadings synthesized as parents of the respective 8-digit tariff lines. Each tariff-line description in the PDF includes the sub-grouping prefix verbatim (e.g., ''Rolled or flaked grains : -- Of oats'').", "Heading 1106 description: ''Flour, meal and powder of the dried leguminous vegetables of heading 07.13, of sago or of roots or tubers of heading 07.14 or of the products of Chapter 8.'' — preserved verbatim including the trailing period and the embedded heading references ''07.13'' and ''07.14''.", "Subheading 1106.10 ''Of the dried leguminous vegetables of heading 0713'' has only one tariff line in the PDF: 1106.10.10 (Guar Meal). The ''90'' / ''Other'' tariff line is not present in the source — preserved verbatim.", "Subheading 1106.30 ''Of the products of Chapter 8'' tariff line 1106.30.30 description in the PDF is ''Mango flour'' (no sub-grouping '': ----'' indicator) — preserved verbatim.", "Subheading 1108.19 ''Starches : -- Other'' contains two tariff lines: 1108.19.10 (Sago) and 1108.19.90 (Other). Subheading description preserved verbatim.", "Heading 1109 in the PDF is represented only by the 8-digit tariff line ''11090000'' (''Wheat gluten, whether or not dried'') with no separate 4-digit heading row above it. Heading title is inferred from the tariff line description (''Wheat gluten, whether or not dried'') per WCO HS nomenclature. Subheading ''1109.00'' synthesized as the parent of ''1109.00.00'' (single-line heading).", "The ''Export Policy'' column values (''Free'', ''Prohibited'') and ''Policy Condition'' column values are not part of the tariff line description field; they are captured separately. The ''Unit'' column (kg/u/etc) is NOT shown in this chapter''s PDF — unit field set to null for all tariff lines.", "Tariff line 1101.00.00 (''Wheat or meslin flour.'') has Export Policy ''Prohibited'' with an extensive Policy Condition citing Notification No 39/2015-20 dated 14.10.2022 — captured in the policy_conditions array. All other tariff lines in Chapter 11 have Export Policy ''Free'' with no Policy Condition."]'::jsonb, '{}'::jsonb, 'Chapter 11 Products Of The Milling Industry; Malt; Starches; Inulin; Wheat Gluten.pdf', ('2026-05-22')::timestamptz, NOW()),
  ('12', 'II', 'OIL SEEDS AND OLEAGINOUS FRUITS; MISCELLANEOUS GRAINS, SEEDS AND FRUIT; INDUSTRIAL OR MEDICINAL PLANTS; STRAW AND FODDER', '[{"number": "1", "text": "Heading 1207 applies, inter alia, to palm nuts and kernels, cotton seeds, castor oil seeds, sesamum seeds, mustard seeds, safflower seeds, poppy seeds and shea nuts (karite nuts). It does not apply to products of heading 0801 or 0802 or to olives (Chapter 7 or Chapter 20)."}, {"number": "2", "text": "Heading 1208 applies not only to non-defatted flours and meals but also to flours and meals which have been partially defatted or defatted and wholly or partially refatted with their original oils. It does not, however, apply to residues of headings 2304 to 2306."}, {"number": "3", "text": "For the purposes of heading 1209, beet seeds, grass and other herbage seeds, seeds of ornamental flowers, vegetable seeds, seeds of forest trees, seeds of fruit trees, seeds of vetches (other than those of the species Vicia faba) or of lupines are to be regarded as \"\"seeds of a kind used for sowing\"\". Heading 1209 does not, however, apply to the following even if for sowing : (a) leguminous vegetables or sweet corn (Chapter 7); (b) spices or other products of Chapter 9; (c) cereals (Chapter 10); or (d) products of headings 1201 to 1207 or 1211."}, {"number": "4", "text": "Heading 1211 applies, inter alia, to the following plants or parts thereof: basil, borage, ginseng, hyssop, liquorice, all species of mint, rosemary, rue, sage and wormwood. Heading 1211 does not, however, apply to : (a) medicaments of Chapter 30; (b) perfumery, cosmetic or toilet preparations of Chapter 33; or (c) insecticides, fungicides, herbicides, disinfectants or similar products of heading 3808."}, {"number": "5", "text": "For the purposes of heading 1212, the term \"\"seaweeds and other algae\"\" does not include : (a) dead single-cell micro-organisms of heading 2102; (b) cultures of micro-organisms of heading 3002; or (c) fertilizers of heading 3101 or 3105."}]'::jsonb, '[{"number": "1", "text": "For the purposes of sub-heading 1205 10, the expression \"low erucic acid rape or colza seeds\" means rape or colza seeds yielding a fixed oil which has an erucic acid content of less than 2% by weight and yielding a solid component which contains less than 30 micromoles of glucosinolates per gram."}]'::jsonb, '[]'::jsonb, '[{"number": "1", "text": "Seeds of all forestry species including Nux Vomica, Red Sanders, Rubber, Russa Grass and tufts, Sandalwood and seeds of tufts, Sandalwood and seeds of ornamental wild variety plants stand restricted for export and shall be allowed under licence and also shall be regulated according to the rules notified under Biological ( Diversity) Act, 2002"}, {"number": "2", "text": "1. Baddomes cycad (Cycas beddomei). 2. Blue vanda (Vanda coerulea). 3. Saussurea costus. 4. Ladies slipper orcid (Paphiopedilium species). 5. Pitcher plant (Nepenthes Khasiana). 6. Red vanda (Renanthera imschootiana). 7. Rauvolifia serpentina (Sarpagandha). 8. Ceropegia species. 9. Frerea indica (Shindal Mankundi). 10. Podophyllum hexandurm (emodi) (Indian Podophyllum.) 11. Cyatheaceae species (Tree Ferns). 12. Cycadacea species (Cycads). 13. Dioscorea deltoidea (Elephant?s foot). 14. Euphorbia species (Euphorbias). 15. Orchidaceae species (Orchids). 16. Pterocarpus santalinus (Redsanders). 17. Taxus Wallichiana (Common Yew or irmi Leaves). 18. Aquilaria malaccensis (Agarwood). 19. Aconitum species. 20. Coptis teeta. 21. Coscinium fenestrum (Calumba wood). 22. Dactylorhiza hatagirea. 23. Gentiana Kurroo (Kuru , Kutki). 24. Gnetum species. 25. Kampheria Galenga. 26. Nardostachys grandiflora. 27. Panax pseudoginseng. 28. Picrorhiza kurrooa. 29. Swertia chirata (Charayatah)."}, {"number": "3", "text": "(i) However, in respect of CITES species, a CITES permit of export shall be required. (ii) Exports allowed only through the Ports of Mumbai, Nhava Sheva, Kolkata, Cochin, Delhi, Chennai, Tuticorin, Amritsar, Calicut, Thiruvananthapuram, Kandla and Mundra. (iii) Except for the documents prescribed above, no additional informations/ NOC/ documents shall be required to be furnished by the Exporter to any authority of State or Central Government."}, {"number": "4", "text": "The term ?formulation? used here may include products, which may contain portions / extracts of plants on the prohibited list. Further the term ?formulation? shall also include value added formulations as well as herbal ayurvedic, and exports subject to the provisions of CITES or Wild Life (protection) Act, 1972 in case where the formulation contains species listed therein."}]'::jsonb, '[]'::jsonb, '["PDF source uses 8-digit codes without dots (e.g., ''12011000''). Normalized to NNNN.NN.NN format (e.g., ''1201.10.00'') per project schema. Six-digit subheading numbers in PDF (e.g., ''120230'', ''120241'') normalized to NNNN.NN form (e.g., ''1202.30'', ''1202.41'').", "PDF table-chrome headers (''SI.No. Notes Notification No Notification Date'', ''Itc(hs) Code. Description Export Policy Policy Condition'', ''Main Notes'', ''Sub-Heading Notes'', ''Policy Condition'', ''Export Licensing Notes'', ''Product Description and Export Policy'') were recognized as table headers and EXCLUDED from the legal notes per extraction rules.", "Section II Main Note about ''pellets'' appears on PDF page 1 above the Chapter 12 title and is attributed to section_notes (Section II, Vegetable Products), not chapter_notes.", "PDF preserves doubled quotation marks (e.g., ''\"\"seeds of a kind used for sowing\"\"'', ''\"\"seaweeds and other algae\"\"'') in Main Notes 3 and 5 — these appear to be OCR/encoding artifacts where single typographic quotes were rendered as paired straight quotes; preserved verbatim from source.", "Export Licensing Notes and certain Policy Condition cells contain ''?'' characters in place of typographic quote marks (e.g., ''?formulation?'', ''?Certificate of Analysis?'', ''?Procedure for Control of Contamination of Salmonella in Sesame Seeds for Export to EU?'', ''?Spice?'', ''Elephant?s foot''). These are OCR/encoding artifacts from the source PDF — preserved verbatim. The intended text uses quotation marks or an apostrophe.", "Tariff line code 8-digit codes ending in ''00'' (e.g., ''12011000'' → ''1201.10.00'', ''12030000'' → ''1203.00.00'', ''12081000'' → ''1208.10.00'') represent subheadings where only the single ''00'' tariff line exists. Captured as one tariff line under the corresponding 6-digit subheading.", "Heading 1203 (''Copra.'') is represented in the PDF as the single tariff line ''12030000'' with description ''Copra.'' — no separate subheading row appears in the source; tariff line is grouped under subheading ''1203.00'' for schema consistency.", "Heading 1204 has a single subheading ''120400'' (Linseed, whether or not broken) with two tariff lines ''12040010'' and ''12040090''.", "Heading 1206 has a single subheading ''120600'' (Sunflower seeds, whether or not broken) with two tariff lines ''12060010'' and ''12060090''.", "Heading 1213 (''Cereal straw and husks'') is a single tariff line ''12130000'' (no separate subheading row); represented under subheading ''1213.00'' for schema consistency.", "Subheading 1207.40 (Sesamum seeds) tariff lines ''1207.40.10'' and ''1207.40.90'' carry extensive Policy Condition text covering exports to Russian Federation, European Union, and the United States (IOPEPC certification, NABL accredited laboratories, EU Salmonella procedure). Captured verbatim with ''?'' artifacts preserved.", "Subheading 1211.90 contains a large block of 8-digit tariff lines (1211.90.11 through 1211.90.90) with sub-grouping labels in the PDF: ''Seeds, Kernel, Aril, Fruit, Pericarp, Fruit rind, Endosperm, Mesocarp, Endocarp'', ''Leaves, Leaf bud, Galls, flowers, Inflorescence, Spadix, Flower bud, Style and Stigma, Stamen and pods'', ''Bark, husk, and rind'', ''Roots, Root stalk, Bulb, Corn,Tuber, Stolon and rhizome'', ''Roots and Rhizomes'', ''Whole Plant, Aerial Part, Stem, Shoot and Wood''. Each group descriptor is prefixed to the tariff line description verbatim.", "Policy Condition cell for tariff lines 1207.40.10 and 1207.40.90 contained extensive multi-page text — captured verbatim into policy_conditions array entries; ''?'' OCR artifacts preserved.", "Tariff line 1211.90.51 (Sandalwood chips and dust) carries a multi-page Policy Condition text with detailed sandalwood export rules covering (a)-(f) sub-clauses, captured verbatim into the policy_conditions array.", "Tariff line 1211.90.54 (Agarwood) carries a multi-page Policy Condition with quantitative annual export limits for Agarwood (Aquilaria Malaccensis) chips and powder and detailed permit conditions, captured verbatim. Cell uses ''?'' for typographic quote marks (preserved).", "Tariff line 1212.29.90 (Other algae) Policy Condition contains export rules for sea weeds of Tamil Nadu Coast origin; captured verbatim.", "Tariff line 1209.29.90 Policy Condition relates to Egyptian clover (Barseem) Trifolium alaxtum seeds and Saffron seeds or corms; captured verbatim.", "Tariff line 1213.00.00 Policy Condition relates to fodder including wheat and rice straw; captured verbatim with notification 58/2015-20 dated 14.02.2023.", "Subheading 1207.99 contains a ''Other : -- Other'' descriptor followed by named tariff lines: 1207.99.10 (Ajams), 1207.99.20 (Mango kernel), 1207.99.30 (Niger seed), 1207.99.40 (Kokam), 1207.99.90 (Other) — verified verbatim from PDF.", "Subheading 1211 has no subheading-level prefix codes; PDF lists heading 1211 directly with tariff lines 1211.20.00 (Ginseng roots), 1211.30.00 (Coca leaf), 1211.40.00 (Poppy straw), 1211.60.00 (Bark of African cherry), and subheading 1211.90 (Other). These tariff lines are placed under synthetic 6-digit subheadings ''1211.20'', ''1211.30'', ''1211.40'', ''1211.60'' for schema consistency, each containing a single ''.00'' tariff line.", "Subheading 1209.99 ''Other : -- Other'' contains tariff lines 1209.99.10 (Fruit seeds for planting or sowings) and 1209.99.90 (Other) — both carry policy condition text re: affidavit for seed exports and seeds of all forestry species & Cashew seeds restriction (captured verbatim).", "Tariff line 1209.29.90 description in PDF is ''Other'' under subheading ''120929'' (Seeds of forage plants : -- Other). Captured with subheading group descriptor included for searchability.", "Heading 1211 description (verbatim): ''Plants and parts of plants (including seeds and fruits), of a kind used primarily in perfumery, in pharmacy or for insecticidal, fungicidal or similar purposes, fresh, chilled, frozen or dried, whether or not cut, crushed or powdered.'' — preserved with trailing period.", "Heading 1212 description (verbatim): ''Locust beans, seaweeds and other algae, sugar beet and sugar cane, fresh, chilled, frozen or dried, whether or not ground; stones and kernels and other vegetable products (including unroasted chicory roots of the variety Cichorium intybus sativum) of a kind used primarily for human consumption, not elsewhere specified or included.'' — preserved with trailing period."]'::jsonb, '{}'::jsonb, 'Chapter 12 Oil Seeds And Oleaginous Fruits; Miscellaneous Grains, Seeds And Fruit; Industrial Or Medicinal Plants; Straw and Fodder..pdf', ('2026-05-22')::timestamptz, NOW()),
  ('13', 'II', 'LAC; GUMS, RESINS AND OTHER VEGETABLE SAPS AND EXTRACTS', '[{"number": "1", "text": "Heading 1302 applies, inter alia, to liquorice extract and extract of pyrethrum, extract of hops, extract of aloes and opium. The heading does not apply to: (a) liquorice extract containing more than 10% by weight of sucrose or put up as confectionery (heading 1704); (b) malt extract (heading 1901); (c) extracts of coffee, tea or mate (heading 2101); (d) vegetable saps or extracts constituting alcoholic beverages (Chapter 22); (e) camphor, glycyrrhizin or other products of heading 2914 or 2938; (f) concentrates of poppy straw containing not less than 50% by weight of alkaloids (heading 2939); (g) medicaments of heading 3003 or 3004 or blood - grouping reagents (heading 3882); (h) tanning or dyeing extracts (heading 3201 or 3203); (i) essential oils, concretes, absolutes,resinoids, extracted oleoresins, aqueous distillates or aqueous solutions of essential oils or preparations based on odoriferous substances of a kind used for the manufacture of beverages (Chapter 33); or (j) natural rubber, balata, gutta-percha, guayule, chicle or similar natural gums (heading 4001)."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["PDF source uses 8-digit codes without dots (e.g., ''13012000'', ''13019011''). Normalized to NNNN.NN.NN format (e.g., ''1301.20.00'', ''1301.90.11'') per project schema. 6-digit subheading numbers in PDF (e.g., ''130190'', ''130219'', ''130232'', ''130239'') normalized to NNNN.NN (e.g., ''1301.90'', ''1302.19'', ''1302.32'', ''1302.39'').", "PDF table-chrome headers (''SI.No. Notes Notification No Notification Date'', ''SI.No. Notes Notification Date Notification No'', ''Itc(hs) Code. Description Export Policy Policy Condition'', ''Main Notes'', ''Policy Condition'', ''Export Licensing Notes'', ''Product Description and Export Policy'') were recognized as table chrome and EXCLUDED from the legal notes per extraction rules.", "Section II Main Note about ''pellets'' appears on PDF page 1 above the Chapter 13 title and is attributed to section_notes (Section II, Vegetable Products), not chapter_notes.", "Chapter 13 has only one chapter note (Note 1), which is a long compound exclusion clause spanning sub-items (a)-(j). Each excluded product class was split into a separate exclusion_clauses entry while preserving the source_note_text verbatim.", "Policy Condition 3 in the source PDF begins with a ''?'' character (rendered before ''The export of Food Supplements...'') and contains a second ''?'' character mid-text before ''The export of Food Supplements containing botanicals to European Union (EU) and United Kingdom (UK) originating in or consigned from India and intended for human or animal consumption, also allowed...''. These ''?'' characters appear to be OCR/encoding artifacts (likely intended as bullet markers or quote characters) and are preserved verbatim as they appear in the source.", "Tariff line 1301.90.16 description ''Natural gums: ---- Karaya gum (Indian tragacanth) hastab'' — ''hastab'' appears as truncated text in the source PDF (no further continuation visible). Preserved verbatim.", "Tariff line 1301.90.17 description in PDF wraps across two rows: ''Natural gums: ---- Tragacanth (adraganth)''. The continuation ''(adraganth)'' appears in a separate cell on page 4. Reconstructed as a single description.", "Subheading 1302.32 description in PDF reads ''Mucilages and thickeners, whether or not modified, derived from vegetable products : -- Mucilages and thickeners, whether or not modified, derived from locust beans, locust bean seeds or guar seeds'' — the word ''seeds'' appears on the next page as a continuation. Reconstructed verbatim.", "Policy Condition column shows ''Subject to Policy Condition 1 of the Chapter'' for heading 1301 tariff lines, ''Subject to Policy Condition 2 &3 of the Chapter'' for most heading 1302 tariff lines, and ''Subject to Policy Condition 2 of the Chapter'' for subheading 1302.31 onwards (mucilages/thickeners). Notification details (''31/2015-20'', ''53/2023'', dated ''29.09.2017'', ''15.12.2023'') captured in policy_conditions.", "Export Licensing Notes section for Chapter 13 contains a single row stating: ''Export of quantities of wheat flour to Maldives shall be permitted through the PSUs indicated.'' with Notification Date ''27.06.2017'' and Notification No ''12/2015-20''. This note is unrelated to Chapter 13 product scope (wheat flour falls under Chapter 11) and appears to be a misplaced or template entry in the source PDF — preserved verbatim as it appears in the Chapter 13 PDF.", "Several tariff lines under heading 1301 have empty Export Policy and Policy Condition cells in the source PDF for the parent subheading rows (''130190'' / 1301.90 ''Other''). These rows are subheading-level rows, not tariff lines, and are represented as subheadings in the structure."]'::jsonb, '{}'::jsonb, 'Chapter 13 Lac; Gums, Resins And Other Vegetable Saps And Extracts.pdf', ('2026-05-22')::timestamptz, NOW()),
  ('14', 'II', 'VEGETABLE PLAITING MATERIALS; VEGETABLE PRODUCTS NOT ELSEWHERE SPECIFIED OR INCLUDED', '[{"number": "1", "text": "This Chapter does not cover the following products which are to be classified in Section XI: vegetable materials or fibres of vegetable materials of a kind used primarily in the manufacture of textiles, however prepared, or other vegetable materials which have undergone treatment so as to render them suitable for use only as textile materials."}, {"number": "2", "text": "Heading 1401 applies, inter alia, to bamboos (whether or not split, sawn lengthwise, cut to length, rounded at the ends, bleached, rendered non-inflammable, polished or dyed), split osier, reeds and the like, to rattan cores and to drawn or split rattans. The heading does not apply to chipwood (heading 4404)."}, {"number": "3", "text": "Heading 1404 does not apply to wood wool (heading 4405) and prepared knots or tufts for broom or brush making (heading 9603)."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["PDF source uses codes without dots: 8-digit tariff lines (e.g., ''14011000'') and 6-digit subheading rows (e.g., ''140190'', ''140490''). Normalized to NNNN.NN.NN format (e.g., ''1401.10.00'') and NNNN.NN format (e.g., ''1401.90'', ''1404.90'') per project schema.", "Headings 1402 and 1403 are not present in the source PDF — they were deleted from the HS nomenclature. Only headings 1401 and 1404 appear in Chapter 14.", "Subheadings 1401.10 (Bamboos) and 1401.20 (Rattans) and 1404.20 (Cotton linters) are presented in the PDF only as 8-digit tariff line rows (''14011000'', ''14012000'', ''14042000'') without a separate 6-digit subheading header row. Each is captured as a subheading containing a single tariff line ending in ''.00''.", "Subheadings 1401.90 (Other, under 1401) and 1404.90 (Other, under 1404) appear in the PDF as 6-digit rows ''140190'' and ''140490'' with description ''Other'' and no export-policy column value — captured as subheadings with their nested 8-digit tariff lines.", "Section II Main Note (about ''pellets'') appears on PDF page 1 above the Chapter 14 title and is attributed to section_notes (Section II, Vegetable Products), not chapter_notes.", "Export Licensing Notes table contains one row about ''Export of quantities of wheat flour to Maldives'' (Notification 12/2015-20, 27.06.2017). Wheat flour is classified under Chapter 11, not Chapter 14 — this note appears under Chapter 14 in the source PDF but its subject matter is unrelated to Chapter 14 products. Preserved verbatim in policy_conditions per source.", "Tariff line 1401.10.00 (Bamboos) carries Export Policy ''Prohibited'' with a detailed Policy Condition (Notification 11/2015-20 dated 23.06.2017 and 08/2015-20 dated 19.05.2022). Captured in policy_conditions array.", "Tariff line 1404.90.40 (Betel leaves) carries an export condition (registration with SHEFEXIL for EU exports, Notification 30/2015-20 dated 23.09.2021). Captured in policy_conditions array.", "PDF table-chrome headers (''Sl.No. Notes Notification No Notification Date'', ''Itc(hs) Code. Description Export Policy Policy Condition'', ''Main Notes'', ''Export Licensing Notes'', ''Product Description and Export Policy'') were recognized as table headers and EXCLUDED from the legal notes per extraction rules.", "Chapter 14 Main Notes table presents column order ''Sl.No. | Notes | Notification Date | Notification No'' (with Date before No) whereas Section II Main Notes table presents ''Sl.No. | Notes | Notification No. | Notification Date'' (with No before Date). Both Main Notes rows in this chapter have empty Notification fields — no impact on captured data."]'::jsonb, '{}'::jsonb, 'Chapter 14 Vegetable Plaiting Materials; Vegetable Products Not Elsewhere Specified Or Included.pdf', ('2026-05-22')::timestamptz, NOW()),
  ('15', 'III', 'ANIMAL OR VEGETABLE FATS AND OILS AND THEIR CLEAVAGE PRODUCTS; PREPARED EDIBLE FATS; ANIMAL OR VEGETABLE WAXES', '[{"number": "1", "text": "This Chapter does not cover : (a) pig fat or poultry fat of heading 0209; (b) cocoa butter, fat or oil (heading 1804); (c) edible preparations containing by weight more than 15% of the products of heading 0405 (generally Chapter 21); (d) greaves (heading 2301) or residues of headings 2304 to 2306; (e) fatty acids, prepared waxes, medicaments, paints, varnishes, soap, perfumery, cosmetic or toilet preparations, sulphonated oils or other goods of Section VI; or (f) factice derived from oils (heading 4002)."}, {"number": "2", "text": "Heading 1509 does not apply to oils obtained from olives by solvent extraction (heading 1510)."}, {"number": "3", "text": "Heading 1518 does not cover fats or oils or their fractions, merely denatured, which are to be classified in the heading appropriate to the corresponding undenatured fats and oils and their fractions."}, {"number": "4", "text": "Soap-stocks, oil foots and dregs,stearin pitch, glycerol pitch and wool grease residuesfall in heading 1522."}]'::jsonb, '[{"number": "1", "text": "For the purposes of sub-heading 1509 30, virgin olive oil has a free acidity expressed as oleic acid not exceeding 2.0 g/ 100 g and can be distinguished from the other virgin olive oil categories according to the characteristics indicated in the Codex Alimentarius Standard 33-1981."}, {"number": "2", "text": "For the purposes of sub-headings 1514 11 and 1514 19, the expression \"low erucic acid rape or colza oil\" means the fixed oil which has an erucic acid content of less than 2% by weight."}]'::jsonb, '[]'::jsonb, '[{"number": "1", "text": "(i) Export of oils produced out of minor forest produce, as per table given below, even if edible; IT HS Code Item Description 15159010 Fixed Vegetable oils viz. Neutralised and Bleached Morwah Oil/fat, 15159020 Fixed vegetable oils viz. Dhup oil, Neemseed oil 15159030 Fixed vegetable oils viz. Nigerseed oil. 15159040 Fixed vegetable oils viz. Neutralised and Bleached Mango kernel 15179010 Sal Fat (Processed or Refined). 15219020 Shellac wax, whether or not coloured. 15219010 Beewax (ii) Export of organic edible oils from Custom EDI ports have been exempted from all quantitative ceilings irrespective of any existing or future restriction/ prohibition on export of their basic product (non-organic), with due certification as Organic? under the NPOP by Agricultural &Processed Food Products Export Development Authority (APEDA), New Delhi. [Notification No. 03/2015-2020 dated 19.04.2017] (iii) Export of edible oils (other than those mentioned in Note 1 above, is permitted in branded consumer packs of upto 5 Kgs, subject to a Minimum Export Price of USD 900 per MT."}]'::jsonb, '[]'::jsonb, '["PDF source uses 8-digit codes without dots (e.g., ''15011000''). Normalized to NNNN.NN.NN format (e.g., ''1501.10.00'') per project schema. Subheading numbers in PDF (e.g., ''150210'') normalized to NNNN.NN (e.g., ''1502.10'').", "PDF table-chrome headers (''Sl.No. Notes Notification Date Notification No'', ''Main Notes'', ''Sub-Heading Notes'', ''Policy Condition'', ''Export Licensing Notes'', ''Itc(hs) Code. Description Export Policy Policy Condition'', ''Product Description and Export Policy'') were recognized as table headers and EXCLUDED from the legal notes per extraction rules.", "Section III (''ANIMAL, VEGETABLE OR MICROBIAL FATS AND OILS AND THEIR CLEAVAGE PRODUCTS; PREPARED EDIBLE FATS; ANIMAL OR VEGETABLE WAXES'') appears as a section header above the Chapter 15 title; no separate Section Notes table is printed in the PDF (Section III contains only Chapter 15). section_notes captured as empty array.", "PDF contains ''?'' characters in place of typographic quote marks in the Export Licensing Notes and tariff line 1505.00.90 policy condition (e.g., ''?Shipment Clearance Certificate?'', ''?Health Certificate?'', ''as Organic?''). These are OCR/encoding artifacts from the source PDF — preserved verbatim as they appear in the source.", "Chapter Note 1 lists exclusions as inline sub-items (a) through (f). Each is captured as a separate exclusion_clause entry in exclusion_clauses array.", "Heading 1505 in PDF is rendered as a single line containing both the heading row and an additional subheading row ''150500'' with description identical to heading title. Subheading ''1505.00'' captured with the printed title ''Wool grease and fatty substances derived therefrom (including lanolin)''.", "Tariff line 1502.10.90 policy condition spans multiple sub-clauses including ''(i) Export permitted only from APEDA registered integrated meat plants...'' — captured verbatim, including the sentence about Buffalo Tallow being free.", "Tariff line 1505.00.90 has TWO Notification Nos listed (''104(RE-2013)/2009-2014'' and ''37/2015-20'') with TWO Notification Dates (''31.12.2014'' and ''25.10.2017''). Both pairs preserved in the policy_conditions array.", "Heading 1511 (''Palm oil...'') has no ''151110'' subheading printed in the PDF — code ''15111000'' (Crude oil) appears directly under heading 1511. Tariff line 1511.10.00 reconstructed under subheading 1511.10 per HS structural convention.", "Heading 1512 — subheading ''151220'' is missing in PDF; only ''151221'' and ''151229'' appear under heading 1512. Per HS structure, 1512.21 falls under the parent ''1512.2x Cotton-seed oil and its fractions'' grouping but printed PDF goes directly from ''151219'' to ''15122100'' (1512.21.00) — preserved as-is.", "Heading 1515 — no subheading line printed for ''151510'' (Linseed oil), ''151520'' (Olive residue oil — not present in this chapter), ''151540'' (Castor oil and its fractions), ''151550'' (Sesame), ''151560'' (Microbial), ''151590'' (Other). Subheadings reconstructed where parent codes appear (1515.11/1515.19 under Linseed parent; 1515.21/1515.29 under Maize parent; 1515.30 Castor; 1515.50 Sesame; 1515.60 Microbial; 1515.90 Other) using the codes printed in the PDF.", "Heading 1518 — PDF does not print a ''151800'' subheading line. Tariff lines ''15180011'' through ''15180040'' belong logically to subheading ''1518.00''. Reconstructed under subheading ''1518.00'' with the heading title.", "Heading 1520 — only single tariff line ''15200000'' printed (Glycerol, crude). Captured under reconstructed subheading ''1520.00'' with heading title.", "Heading 1522 — subheading ''152200'' printed with description ''Degras: residues resulting from the treatment of fatty substances or animal or vegetable waxes :'' — title preserved verbatim including trailing colon.", "Tariff line 1515.90.20 description in PDF ends with trailing comma (''neem seed oil, karanj oil, silk cotton seed oil,'') — preserved verbatim.", "Heading 1517 in PDF reads ''MARGARINE; EDIBLE MIXTURES OR PREPARATIONS OF ANIMAL, VEGETABLE OR MICROBIAL FATS OR OILS OR OF FRACTIONS OF DIFFERENT FATS OR OILS OF THIS CHAPTER, OTHER THAN EDIBLE FATS AND OILS OR THEIR FRACTIONS OF HEADING 1516'' — note ''OTHER THAN EDIBLE'' is correct per HS 2022 (heading 1516 covers hydrogenated; 1517 covers mixtures/margarine).", "Heading 1517, subheading ''151710'' (Margarine, excluding liquid margarine) — note that tariff line 1517.10.20 (''Of vegetable origin'') is not separately listed; instead three sub-codes 1517.10.21/22/29 appear directly. Preserved as printed.", "Subheading 1517.90 — PDF skips intermediate ''1517.90.20'' line; tariff lines jump from 1517.90.10 (Sal fat) to 1517.90.30 (Imitation lard of animal origin). Preserved as printed.", "No ''unit'' column appears in the source PDF (Indian ITC-HS Schedule 2 Export Policy format only has Code/Description/Export Policy/Policy Condition columns). All unit fields set to null.", "Export Policy and Notification details preserved in policy_conditions array (one entry per tariff line with a policy condition) and export_licensing_notes array."]'::jsonb, '{}'::jsonb, 'Chapter 15 Animal Or Vegetable Fats And Oils And Their Cleavage Products; Prepared Edible Fats; Animal Or Vegetable Waxes.pdf', ('2026-05-22')::timestamptz, NOW()),
  ('16', 'IV', 'PREPARATIONS OF MEAT, OF FISH, OF CRUSTACEANS, MOLLUSCS OR OTHER AQUATIC INVERTEBRATES OR OF INSECTS', '[{"number": "1", "text": "This Chapter does not cover meat, meat offal, fish, crustaceans, molluscs or other aquatic invertebrates, as well as insects, prepared or preserved by the processes specified in Chapter 2 or 3, Note 6 to Chapter 4 or in heading 0504."}, {"number": "2", "text": "Food preparations fall in this Chapter provided that they contain more than 20% by weight of sausage, meat, meat offal, blood, insect, fish, crustaceans, molluscs or other aquatic invertebrates, or any combinationthereof. In cases where the preparation containstwo or more of the products mentioned above, it is classified in the heading of Chapter 16 corresponding to the component or components which predominate by weight.These provisions do not apply to the stuffed products of heading 1902 or to the preparations of heading 2103or 2104."}]'::jsonb, '[{"number": "1", "text": "For the purposes of sub-heading 1602 10, the expression \"homogenised preparations\" means preparations of meat, meat offal, blood or insects, finely homogenised, put up for retail sale as food suitable for infantsor young children or for dietetic purposes, in containers of net weight content not exceeding 250 g. For theapplication of this definition no account is to be taken of small quantities of any ingredients which may havebeen added to the preparation for seasoning, preservation or other purposes. These preparations may contain a small quantity of visible pieces of meat or meat offal or insects. This sub-heading takes precedence over all other sub-headings of heading 1602."}, {"number": "2", "text": "The fish, crustaceans molluscs and other aquatic invertebrates specified in the sub-headings of heading 1604 or 1605 under their common names only, are of the same species as those mentioned in Chapter 3 under the same name."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["PDF filename contains a typo ''Molluscsor'' (missing space between ''Molluscs'' and ''or''). Preserved verbatim in source_pdf as instructed.", "PDF source uses 8-digit codes without dots (e.g., ''16021000''). Normalized to NNNN.NN.NN format (e.g., ''1602.10.00'') per project schema. Subheading numbers in PDF (e.g., ''160300'') normalized to NNNN.NN (e.g., ''1603.00'').", "PDF table-chrome headers (''Sl.No. Notes Notification Date Notification No'', ''Itc(hs) Code. Description Export Policy Policy Condition'', ''Main Notes'', ''Sub-Heading Notes'', ''Policy Condition'', ''Product Description and Export Policy'') were recognized as table headers and EXCLUDED from the legal notes per extraction rules.", "Chapter Note 2 in the source PDF contains run-together words: ''any combinationthereof'' (missing space between ''combination'' and ''thereof''), ''preparation containstwo'' (missing space between ''contains'' and ''two''), and ''heading 2103or 2104'' (missing space between ''2103'' and ''or''). Preserved verbatim as they appear in the PDF.", "Sub-Heading Note 1 in the source PDF contains run-together words: ''food suitable for infantsor young children'' (missing space between ''infants'' and ''or''), ''For theapplication'' (missing space between ''the'' and ''application''), and ''may havebeen added'' (missing space between ''have'' and ''been''). Preserved verbatim as they appear in the PDF.", "Policy Condition 2 (Halal certification) in the source PDF contains ''?'' characters in place of typographic quote marks (e.g., ''?India Conformity Assessment Scheme(I-CAS)- Halal?'', ''importing country?s requirements'', ''Halal Meat &Meat products'', ''mandated is as follows ?''). These are OCR/encoding artifacts from the source PDF — preserved verbatim as they appear in the source.", "Policy Condition 2 text spans two PDF pages. The continuation text (beginning ''producer/supplier/exporter shall also meet...'') was joined into a single note in the policy_conditions array.", "Tariff line 1603.00.10 ''Extracts and juices of meat'' has Policy Condition text ''Export allowed freely but export to European Union allowed subject to the following conditions...'' (Notification 34/2015-20 dated 13.01.2017). This is captured in policy_conditions. The continuation across pages includes references to CAPEXIL, Health Certificate, IEC No., etc., and uses ''?'' characters in place of typographic quote marks (e.g., ''?Shipment Clearance Certificate?'', ''?Health Certificate?'') — preserved verbatim.", "Section IV title is ''PREPARED FOODSTUFFS; BEVERAGES, SPIRITS AND VINEGAR; TOBACCO AND MANUFACTURED TOBACCO SUBSTITUTES; PRODUCTS, WHETHER OR NOT CONTAINING NICOTINE, INTENDED FOR INHALATION WITHOUT COMBUSTION; OTHER NICOTINE CONTAINING PRODUCTS INTENDED FOR THE INTAKE OF NICOTINE INTO THE HUMAN BODY''. The section_notes capture the single Main Note of Section IV (definition of ''pellets'').", "Heading 1601 has a single 8-digit code ''16010000'' in the PDF without an intervening subheading row — represented as subheading ''1601.00'' with tariff line ''1601.00.00''. Similar pattern at heading 1603 where subheading ''160300'' is present in the PDF.", "Subheading 1602.30 (''Of poultry of heading 01.05'') is not present as a top-level subheading row in the PDF — instead, the PDF lists three sibling subheadings 1602.31 (turkeys), 1602.32 (fowls of Gallus domesticus), and 1602.39 (Other) directly. The description ''Of poultry of heading 01.05 : -- <species>'' is preserved verbatim on each tariff line.", "Subheading 1602.40 (''Of swine'') is similarly not present as a top-level row; siblings 1602.41 (Hams), 1602.42 (Shoulders), and 1602.49 (Other, including mixtures) appear directly with description prefix ''Of swine : -- <part>''.", "Heading 1604: Subheading rows for 1604.10 (not present), 1604.11 (Salmon), 1604.12 (Herrings), 1604.13 (Sardines), 1604.14 (Tunas), 1604.15 (Mackerel), 1604.16 (Anchovies), 1604.17 (Eels), 1604.18 (Shark fins), 1604.19 (Other), 1604.20 (Other prepared/preserved fish), 1604.31 (Caviar), 1604.32 (Caviar substitutes). Subheadings 1604.12, 1604.13, 1604.14 have intermediate sub-subheading rows (no dotted code) in the PDF that expand into multiple 8-digit tariff lines; these intermediate rows are NOT separate subheadings and were not duplicated.", "Heading 1605: tariff lines appear directly at 8-digit level under the heading without all intermediate subheading rows being displayed in the PDF. Subheadings reconstructed from the first 6 digits of each tariff code: 1605.10, 1605.21, 1605.29, 1605.30, 1605.40, 1605.51, 1605.52, 1605.53, 1605.54, 1605.55, 1605.56, 1605.57, 1605.58, 1605.59, 1605.61, 1605.62, 1605.63, 1605.69.", "Tariff line 1604.18.00 (Shark fins) has Export Policy ''Prohibited'' — the only non-Free tariff line in Chapter 16."]'::jsonb, '{}'::jsonb, 'Chapter 16 Preparations of Meat, of Fish, of Crustaceans, Molluscsor other Aquatic Invertebrates or of Insects.pdf', ('2026-05-22')::timestamptz, NOW()),
  ('17', 'IV', 'SUGARS AND SUGAR CONFECTIONERY', '[{"number": "1", "text": "This Chapter does not cover: (a) Sugar confectionery containing cocoa (heading 1806); (b) Chemically pure sugars (other than sucrose, lactose, maltose, glucose and fructose) or other products of heading 2940; or (c) Medicaments or other products of Chapter 30."}]'::jsonb, '[{"number": "1", "text": "For the purposes of sub-headings 1701 12, 1701 13 and 1701 14 \"raw sugar\" means sugar whose content of sucrose by weight, in the dry state, corresponds to a polarimeter reading of less than 99.5 degree."}, {"number": "2", "text": "Sub-heading 1701 13 covers only cane sugar obtained without centrifugation, whose content of sucrose by weight, in the dry state, corresponds to a polarimeter reading of 69 degree or more but less than 93 degree. The product contains only natural anhedral microcrystals, of irregular shape, not visible to the naked eye, which are surrounded by residues of molasses and other constituents of sugar cane."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["PDF source uses 8-digit codes without dots (e.g., ''17011200''). Normalized to NNNN.NN.NN format (e.g., ''1701.12.00'') per project schema. Subheading numbers in PDF (e.g., ''170113'') normalized to NNNN.NN (e.g., ''1701.13'').", "PDF table-chrome headers (''Sl.No. Notes Notification No Notification Date'', ''Sl.No. Notes Notification Date Notification No'', ''Itc(hs) Code. Description Export Policy Policy Condition'', ''Main Notes'', ''Sub-Heading Notes'', ''Export Licensing Notes'', ''Product Description and Export Policy'') were recognized as table headers and EXCLUDED from the legal notes per extraction rules.", "Subheading 1701.12 (Beet sugar) has a single tariff line 1701.12.00 directly in the PDF without an intermediate subheading row — captured as one tariff line under subheading 1701.12 with the same description.", "Subheading 1701.11 (Raw sugar — cane sugar of standard polarimeter reading) does NOT appear in this Indian ITC(HS) Schedule 2 PDF for Chapter 17. The schedule jumps from heading 1701 directly to subheading 1701.12 (Beet sugar), then 1701.13 (Cane sugar specified in Subheading Note 2), then 1701.14 (Other cane sugar), then 1701.91 and 1701.99. This reflects the HS 2022 structure as adopted in the Indian schedule.", "Section IV Main Note about ''pellets'' appears on PDF page 1 above the Chapter 17 title and is attributed to section_notes (Section IV), not chapter_notes.", "The Notification Date / Notification No columns for tariff line 1701.14.90 contain a run-on block of values ''10/2015-20 20/2015-20 36/2023'' and ''24.05.2022 07.09.2015 18.10.2023'' embedded inside the Policy Condition cell text rather than placed in the right-hand columns. These appear to be notification references for the constituent policy conditions (1, 2, 3) and are preserved verbatim in the policy condition text. The right-hand columns for 1701.14.90 show ''17/2025-26'' and ''17-06-2025'' — captured as the primary notification reference.", "The same Policy Condition text and run-on notification block (with values ''10/2015-20 20/2015-20 36/2023 24.05.2022 07.09.2015 18.10.2023'') repeats verbatim for tariff line 1701.99.90 with primary notification 17/2025-26 dated 17-06-2025 — captured as a separate policy_conditions entry.", "Sugar export quotas captured verbatim: CXL Quota (EU), TRQ (USA), TRQ (UK), and Pharma Grade Sugar Restricted Export Authorization with 25,000 MT annual cap. All preserved in policy_conditions.", "All other tariff lines in Chapter 17 (1701.12.00, 1701.13.10, 1701.13.20, 1701.13.90, 1701.14.10, 1701.14.20, 1701.91.00, 1701.99.10, headings 1702/1703/1704 tariff lines) show export policy ''Free'' with no Policy Condition.", "Heading 1704 description in PDF reads ''Sugar confectionery (including white chocolate), not containing cocoa.'' — verbatim, including the trailing period."]'::jsonb, '{}'::jsonb, 'Chapter 17 Sugars And Sugar Confectionery.pdf', ('2026-05-22')::timestamptz, NOW()),
  ('18', 'IV', 'COCOA AND COCOA PREPARATIONS', '[{"number": "1", "text": "This Chapter does not cover: (a) food preparations containing more than 20 % by weight of sausage, meat, meat offal, blood, insects, fish or crustaceans, molluscs or other aquatic invertebrates, or any combination thereof (Chapter 16); (b) preparations of headings 0403, 1901, 1902, 1904, 1905, 2105, 2202, 2208, 3003 or 3004."}, {"number": "2", "text": "Heading 1806 includes sugar confectionery containing cocoa and, subject to Note 1 to this Chapter, other food preparations containing cocoa."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["PDF source uses 8-digit codes without dots (e.g., ''18010000''). Normalized to NNNN.NN.NN format (e.g., ''1801.00.00'') per project schema. Subheading numbers in PDF (e.g., ''180690'') normalized to NNNN.NN (e.g., ''1806.90'').", "PDF table-chrome headers (''Sl.No. Notes Notification No Notification Date'', ''Itc(hs) Code. Description Export Policy Policy Condition'', ''Main Notes'', ''Product Description and Export Policy'') were recognized as table headers and EXCLUDED from the legal notes per extraction rules.", "Section IV Main Note about ''pellets'' appears on PDF page 1 above the Chapter 18 title. It is attributed to section_notes (Section IV, Prepared Foodstuffs; Beverages, Spirits and Vinegar; Tobacco and Manufactured Tobacco Substitutes; Products, whether or not containing Nicotine, intended for Inhalation without Combustion; Other Nicotine Containing Products intended for the Intake of Nicotine into the Human Body), not chapter_notes.", "Headings 1801, 1802, 1804, 1805 in the PDF appear only as 8-digit tariff lines (18010000, 18020000, 18040000, 18050000) without an explicit heading or subheading row. Each is represented as heading NNNN with a single subheading ''NNNN.00'' carrying one tariff line ''NNNN.00.00''.", "Heading 1803 appears with two 8-digit codes (18031000 ''Not defatted'', 18032000 ''Wholly or partly defatted''). These are preserved as subheadings 1803.10 and 1803.20, each with a single tariff line ''1803.10.00'' and ''1803.20.00'' respectively (PDF shows the 8-digit form only).", "Subheadings 1806.20, 1806.31, 1806.32 in the PDF appear only as 8-digit tariff lines (18062000, 18063100, 18063200) without an explicit 6-digit subheading row. Each is represented as a subheading with a single tariff line ending in ''.00''. Subheading 1806.20 description ''Other preparations in blocks, slabs or bars weighing more than 2 Kg. or in liquid, paste, powder, granular or other bulk form in containers or immediate packings, of a content exceeding 2 Kg. Other, in blocks, slabs or bars:'' is preserved verbatim including the trailing ''Other, in blocks, slabs or bars:'' fragment which serves as the parent descriptor for 1806.31 and 1806.32 in the HS nomenclature.", "All tariff lines in Chapter 18 have Export Policy = ''Free'' with no Policy Condition entries. No policy_conditions or export_licensing_notes are present in the source PDF for this chapter.", "Unit column is not present in the Schedule 2 Export Policy PDF for this chapter; ''unit'' is set to null for all tariff lines."]'::jsonb, '{}'::jsonb, 'Chapter 18 Cocoa And Cocoa Preparations.pdf', ('2026-05-22')::timestamptz, NOW()),
  ('19', 'IV', 'PREPARATIONS OF CEREALS, FLOUR, STARCH OR MILK; PASTRYCOOKS'' PRODUCTS', '[{"number": "1", "text": "This Chapter does not cover : (a) except in the case of stuffed products of heading 1902, food preparations containing more than 20% by weight of sausage, meat, meat offal, blood, insect, fish or crustaceans, molluscs or other aquaticinvertebrates, or any combination thereof (Chapter 16); (b) biscuits or other articles made from flour or from starch, specially prepared for use in animal feeding (heading 2309); or (c) medicaments or other products of Chapter 30."}, {"number": "2", "text": "For the purposes of heading 1901: (a) the term \"\"groats\"\" means cereal groats of Chapter 11; (b) the terms \"\"flour\"\" and \"\"meal\"\" means : (1) cereal flour and meal of Chapter 11, and (2) flour, meal and powder of vegetable origin of any Chapter, other than flour, meal or powder of dried vegetables (heading 0712), of potatoes (heading 1105) or of dried leguminous vegetables (heading 1106)."}, {"number": "3", "text": "Heading 1904 does not cover preparations containing more than 6% by weight of cocoa calculated on a totally defatted basis or completely coated with chocolate or other food preparations containing cocoa of heading 1806 (heading 1806)."}, {"number": "4", "text": "For the purposes of heading 1904, the expression \"otherwise prepared\" means prepared or processed to an extent beyond that provided for in the headings of, or Notes to, Chapter 10 or 11."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["PDF source uses 8-digit codes without dots (e.g., ''19011010'') and 6-digit subheading codes without dots (e.g., ''190110''). Normalized to NNNN.NN.NN format (e.g., ''1901.10.10'') and NNNN.NN format (e.g., ''1901.10'') per project schema.", "PDF table-chrome headers (''Main Notes'', ''Sl.No. Notes Notification Date Notification No'', ''Product Description and Export Policy'', ''Itc(hs) Code. Description Export Policy Policy Condition'') were recognized as table chrome and EXCLUDED from the legal notes per extraction rules.", "Audit note specifies ''Main Notes (3 notes)'' for Chapter 19, but the source PDF shows 4 notes in the Chapter 19 Main Notes table (Notes 1-4). All 4 notes are preserved verbatim as they appear in the PDF. Note 2 spans across a page break (ends with ''(heading 1106).'' on page 2).", "Section IV Main Notes contains 1 note (definition of ''pellets''). Captured under section_notes. Section IV title in source PDF: ''PREPARED FOODSTUFFS; BEVERAGES, SPIRITS AND VINEGAR; TOBACCO AND MANUFACTURED TOBACCO SUBSTITUTES; PRODUCTS, WHETHER OR NOT CONTAINING NICOTINE, INTENDED FOR INHALATION WITHOUT COMBUSTION; OTHER NICOTINE CONTAINING PRODUCTS INTENDED FOR THE INTAKE OF NICOTINE INTO THE HUMAN BODY''.", "PDF Notification No. and Notification Date columns are blank for all notes — all chapter and section notes have no notification metadata.", "Note 2 contains escaped double quotes around ''groats'', ''flour'' and ''meal'' rendered in the PDF as doubled quotation marks (e.g., ''\"\"groats\"\"''). Preserved verbatim as they appear.", "Tariff line 1905.32.11 in the source PDF describes ''Communion wafers: ---- Coated with chocolate or containing chocolate'' under subheading 1905.32 (''--Waffles and wafers''). This pairing appears anomalous (communion wafers typically classify under 1905.90), but is preserved verbatim from the source PDF.", "Subheading 1905.32 in the PDF shows only tariff lines 1905.32.11 and 1905.32.90 (no 1905.32.19 or other intermediate codes). Preserved verbatim.", "Subheading 1902.11 description in PDF: ''Uncooked pasta, not stuffed or otherwise prepared : --Containing eggs'' (with HS nomenclature ''--'' dash prefix). Subheading 1902.19: ''Uncooked pasta, not stuffed or otherwise prepared : -- Other''. Preserved verbatim.", "Export Policy column shows ''Free'' for all tariff lines in this chapter. Policy Condition column is blank for all tariff lines. No policy conditions, export licensing notes, or notification metadata appear in this chapter — policy_conditions array is empty.", "Unit-of-measure column is NOT shown in this chapter''s PDF table — unit field set to null for all tariff lines.", "Heading 1903 has no subheading-level 6-digit code in the PDF table; only the 8-digit tariff line 1903.00.00 is shown directly under the heading row. Captured under synthetic subheading ''1903.00'' to preserve schema consistency.", "Heading 1904 description in PDF reads ''Prepared foods obtained by the swelling or roasting of cereals or cereal products (for example, corn flakes); cereals (other than maize (corn)) in grain form or in the form of flakes or other worked grains (except flour, groats and meal), pre-cooked, or otherwise prepared, not elsewhere specified or included.'' — preserved verbatim including spelling.", "Tariff line 1904.10.20 description ''Paws, Mudi and the like'' uses Indian regional cereal preparation terms (Paws = poha/flattened rice; Mudi = puffed rice) — preserved verbatim.", "Subheading 1904.20 description in PDF ends with a semicolon: ''Prepared foods obtained from unroasted cereal flakes or from mixtures of unroasted cereal flakes and roasted cereal flakes or swelled cereals;'' — preserved verbatim."]'::jsonb, '{}'::jsonb, 'Chapter 19 Preparations Of Cereals, Flour, Starch Or Milk; Pastrycooks Products.pdf', ('2026-05-22')::timestamptz, NOW()),
  ('20', 'IV', 'Preparations Of Vegetables, Fruit, Nuts Or Other Parts Of Plants', '[{"number": "1", "text": "This Chapter does not cover : (a) vegetables, fruit or nuts, prepared or preserved by the processes specified in Chapter 7, 8 or 11; (b) vegetable fats and oils (Chapter 15); (c) food preparations containing more than 20% by weight of sausage, meat, meat offal, blood, insect, fish or crustaceans, molluscs or other aquatic invertebrates, or any combination thereof (Chapter 16); (d) bakers wares and other products of heading 1905; or (e) homogenised composite food preparations of heading 2104."}, {"number": "2", "text": "Headings 2007 and 2008 do not apply to fruit jellies, fruit pastes, sugar-coated almonds or the like in the form of sugar confectionery (heading 1704) or chocolate confectionery (heading 1806)."}, {"number": "3", "text": "Headings 2001, 2004 and 2005 cover, as the case may be, only those products of Chapter 7 or of heading 1105 or 1106 (other than flour, meal and powder of the products of Chapter 8) which have been prepared or preserved by processes other than those referred to in Note 1(a)."}, {"number": "4", "text": "Tomato juice, the dry weight content of which is 7% or more is to be classified in heading 2002."}, {"number": "5", "text": "For the purposes of heading 2007, the expression \"obtained by cooking\" means obtained by heat treatment at atmospheric pressure or under reduced pressure to increase the viscosity of a product through reduction of water content or other means."}, {"number": "6", "text": "For the purposes of heading 2009, the expression \"juices, unfermented and not containing added spirit\" means juices of an alcoholic strength by volume (see Note 2 to Chapter 22) not exceeding 0.5% volume."}]'::jsonb, '[{"number": "1", "text": "For the purposes of sub-heading 2005 10, the expression \"homogenised vegetables\" means preparations of vegetables, finely homogenised, put up for retail sale as food suitable for infants or young children or for dietetic purposes, in containers of a net weight content not exceeding 250 g. For the application of this definition no account isto be taken of small quantities of any ingredients which may have been added to the preparation for seasoning, preservation or other purposes. These preparations may contain a small quantity of visible pieces of vegetables. Subheading 2005 10 takes precedence over all other sub-headings of heading 2005."}, {"number": "2", "text": "For the purposes of sub-heading 2007 10, the expression \"homogenised preparations\" means preparations of fruit,finely homogenised, put up for retailsale asfood suitable for infants or young children or for dietetic purposes, in containers of a net weight content not exceeding 250 g. For the application of this definition no account is to be taken ofsmall quantities of any ingredients which may have been added to the preparation for seasoning, preservation or other purposes. These preparations may contain a small quantity of visible pieces of fruit. Sub-heading 2007 10 takes precedence over all other Sub-headings of heading 2007."}, {"number": "3", "text": "For the purposes of sub-headings 2009 12, 2009 21, 2009 31, 2009 41, 2009 61 and 2009 71, the expression \"Brix value\" means the direct reading of degrees Brix obtained from a Brix hydrometer or of refractive index expressed in terms of percentage sucrose content obtained from a refractometer, at a temperature of 20C or corrected for 20C if the reading is made at a different temperature."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["Task audit hint stated ''Main Notes (3 notes)'' for Chapter 20, but the source PDF contains 6 Main Notes (numbered 1 through 6) plus 3 Sub-Heading Notes. All 6 chapter notes and 3 sub-heading notes have been extracted verbatim. The audit count appears incorrect.", "Tariff codes in the source PDF use no-dot 8-digit format (NNNNNNNN, e.g., ''20011000''). All codes normalized to NNNN.NN.NN format (e.g., ''2001.10.00'') per project schema. 6-digit subheading codes (e.g., ''200390'') normalized to NNNN.NN (e.g., ''2003.90'').", "Section IV Main Note about ''pellets'' appears on PDF page 1 above the Chapter 20 title and is attributed to section_notes (Section IV), not chapter_notes.", "Note 1 of Chapter 20 is the primary exclusion note with sub-clauses (a) through (e). Each sub-clause has been extracted as a separate entry in exclusion_clauses while the full note text is preserved verbatim in chapter_notes.", "Heading 2008 description in the PDF ends with the word ''other'' concatenated onto the heading description (''not elsewhere specified or included.other''). Preserved verbatim as it appears in source.", "Heading 2003 description in the PDF reads ''Mushrooms and truffles, prepared or preserved otherwise than by vinegar or acetic acid.'' — verbatim including trailing period.", "Heading 2006 in the source PDF has the description ''Vegetables, fruit, nuts, fruit-peel and other parts of plants, preserved by sugar (drained, glac or crystallised).'' — the word ''glac'' appears to be an OCR artifact for ''glacé''; preserved verbatim as in source PDF.", "Several tariff line descriptions use ''sub-heading'' prefix labels (e.g., ''Beans (Vigna spp., Phaseolus spp.) : --Beans, shelled'', ''Other vegetables and mixtures of vegetables : -- Bamboo shoots''). These are preserved verbatim from the source PDF and follow the ITC(HS) convention of repeating the parent subheading text before the dash-prefixed tariff-line text.", "Heading 2008 sub-heading 2008.11 (Ground-nuts) carries a Policy Condition with Notification No ''28(RE-2012)/2009-2014'' dated ''03.01.2013'' specifying APEDA registration and Aflatoxin certification requirements (sub-clauses (a) and (b)). This is captured verbatim in the policy_conditions array.", "Heading 2009 description rendered in PDF in ALL CAPS (''FRUIT OR NUT JUICES (INCLUDING GRAPE MUST AND COCONUT WATER) AND VEGETABLE JUICES...''). Normalized to Title Case form following ITC(HS) standard while preserving content verbatim. The original casing is preserved in extraction_warnings record.", "Tariff line code ''2006.00.00'' represents heading 2006 which is a ''one-line heading'' — the heading itself has only a single 8-digit tariff line with the same descriptive text. Captured as subheading 2006.00 with one tariff line 2006.00.00.", "Tariff line code ''2009.50.00'' (Tomato juice) sits under heading 2009 directly — there is no ''20095X'' family of subheadings in the source PDF; this single tariff line forms its own subheading bucket 2009.50.", "PDF table-chrome headers (''Sl.No. Notes Notification Date Notification No'', ''Itc(hs) Code. Description Export Policy Policy Condition'', ''Main Notes'', ''Sub-Heading Notes'', ''Product Description and Export Policy'') were recognized as table headers and EXCLUDED from the legal notes per extraction rules.", "Sub-heading note 3 spans two PDF rows (continues from page 2 to page 3 with the Brix value definition). Reassembled into a single verbatim note covering sub-headings 2009 12, 2009 21, 2009 31, 2009 41, 2009 61 and 2009 71."]'::jsonb, '{}'::jsonb, 'Chapter 20 Preparations Of Vegetables, Fruit, Nuts Or Other Parts Of Plants.pdf', ('2026-05-22')::timestamptz, NOW()),
  ('21', 'IV', 'Miscellaneous Edible Preparations', '[{"number": "1", "text": "This Chapter does not cover: (a) mixed vegetables of heading 0712; (b) roasted coffee substitutes containing coffee in any proportion (heading 0901); (c) flavoured tea (heading 0902); (d) spices or other products of headings 0904 to 0910; (e) food preparations, other than the products described in heading 2103 or 2104, containing more than 20 % by weight of sausage, meat, meat offal, blood, insects, fish or crustaceans, molluscs or other aquatic invertebrates, or any combination thereof (Chapter 16); (f) products of heading 2404; (g) yeast put up as a medicament or other products of heading 3003 or 3004; or (h) prepared enzymes of heading 3507."}, {"number": "2", "text": "Extracts of the substitutes referred to in Note 1 (b) above are to be classified in heading 2101."}, {"number": "3", "text": "For the purposes of heading 2104, the expression \"homogenised composite food preparations\" means preparations consisting of a finely homogenised mixture of two or more basic ingredients such as meat, fish, vegetables, fruit or nuts, put up for retail sale as food suitable for infants or young children or for dietetic purposes, in containers of a net weight content not exceeding 250g. For the application of this definition, no account is to be taken of small quantities of any ingredients which may be added to the mixture for seasoning, preservation or other purposes. Such preparations may contain a small quantity of visible pieces of ingredients."}]'::jsonb, '[]'::jsonb, '[{"number": "1", "text": "In this Chapter, \"Pan masala\" means any preparation containing betel nuts and any one or more of the following ingredients, namely: lime, katha (catechu) and tobacco whether or not containing any other ingredient, such as cardamom, copra or menthol."}, {"number": "2", "text": "In this Chapter \"betel nut product known as Supari\" means any preparation containing betel nuts, but not containing any one or more of the following ingredients, namely: lime, katha (catechu) and tobacco whether or not containing any other ingredients, such as cardamom, copra or menthol."}, {"number": "3", "text": "For the purposes of tariff item 2106 90 11, the expression \"Sharbat\" means any non-alcoholic sweetened beverage or syrup containing not less than 10% fruit juice or flavoured with non-fruit flavours, such as rose, Khus, Kevara, but not including aerated preperations."}, {"number": "4", "text": "Tariff item 2106 90 50, inter alia, includes preparations for lemonades or other beverages, consisting, for example, of flavoured or coloured syrup, syrup flavoured with an added concentrated extract, syrup flavoured with fruit juice and intended for use in the manufacture of aerated water, such as in automatic vending machines."}, {"number": "5", "text": "Heading 2106 (except tariff items 2106 90 20 and 2106 90 30), inter alia, includes: (a) protein concentrates and textured protein substances; (b) preparations for use, either directly or after processing (such as cooking, dissolving or boiling in water, milk or other liquids), for human consumption; (c) preparations consisting wholly or partly of foodstuffs, used in the making of beverages of food preparations for human consumption; (d) powders for table creams, jellies, ice-creams and similar preparations, whether or not sweetened; (e) flavouring powders for making beverages, whether or not sweetened; (f) preparations consisting of tea or coffee and milk powder, sugar and any other added ingredients; (g) preparations (for example, tablets) consisting of saccharin and foodstuff, such as lactose, used for sweetening purposes; (h) pre-cooked rice, cooked either fully or partially and their dehydrates; and (i) preparations for lemonades or other beverages, consisting, for example, of flavoured or coloured syrups, syrup flavoured with an added concentrated extract, syrup flavoured with fruit juices and concentrated fruit juice with added ingredients."}, {"number": "6", "text": "Tariff item 2106 90 99 includes sweet meats commonly known as \"Misthans\" or \"Mithai\" or called by any other name. They also include products commonly known as \"Namkeens\", \"mixtures\", \"Bhujia\", \"Chabena\" or called by any other name. Such products remain classified in these subheadings irrespective of the nature of their ingredients."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{}'::jsonb, 'Chapter 21 Miscellaneous Edible Preparations.pdf', NULL, NOW()),
  ('22', 'IV', 'BEVERAGES, SPIRITS AND VINEGAR', '[{"number": "1", "text": "This Chapter does not cover: (a) products of this Chapter (other than those of heading 2209) prepared for culinary purposes and thereby rendered unsuitable for consumption as beverages (generally heading 2103); (b) sea water (heading 2501); (c) distilled or conductivity water or water of similar purity (heading 2853); (d) acetic acid of concentration exceeding 10 % by weight of acetic acid (heading 2915); (e) medicaments of heading 3003 or 3004; or (f) perfumery or toilet preparations (Chapter 33)."}, {"number": "2", "text": "For the purposes of this Chapter and of Chapters 20 and 21, the \"alcoholic strength by volume\" shall be determined at a temperature of 20 C."}, {"number": "3", "text": "For the purposes of heading 2202, the term \"non-alcoholic beverages\" means beverages of an alcoholic strength by volume not exceeding 0.5 % vol. Alcoholic beverages are classified in headings 2203 to 2206 or heading 2208 as appropriate."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["PDF source uses 8-digit codes without dots (e.g., ''22011010''). Normalized to NNNN.NN.NN format (e.g., ''2201.10.10'') per project schema. Subheading numbers in PDF (e.g., ''220110'') normalized to NNNN.NN (e.g., ''2201.10'').", "PDF table-chrome headers (''Sl.No. Notes Notification Date Notification No'', ''Main Notes'', ''Sub-Heading Notes'', ''Product Description and Export Policy'', ''Itc(hs) Code. Description Export Policy Policy Condition'') were recognized as table headers and EXCLUDED from the legal notes per extraction rules.", "Source PDF has no separate ''Export Licensing Notes'' table for Chapter 22. The export_licensing_notes field is therefore an empty array. The chapter-level note about ''alcoholic strength by volume'' (Chapter Note 2) is preserved verbatim in chapter_notes; the sub-heading definitional note about ''sparkling wine'' (Sub-Heading Note 1) is preserved verbatim in the heading_notes of heading 2204 (where the rule applies to subheading 2204.10).", "Section IV Main Note about ''pellets'' appears on PDF page 1 above the Chapter 22 title and is attributed to section_notes (Section IV, Prepared Foodstuffs; Beverages, Spirits and Vinegar; Tobacco and Manufactured Tobacco Substitutes; Products, Whether or Not Containing Nicotine, Intended for Inhalation without Combustion; Other Nicotine Containing Products Intended for the Intake of Nicotine into the Human Body), not chapter_notes.", "Heading 2202 description in PDF is rendered in ALL CAPS (''WATERS, INCLUDING MINERAL WATERS AND AERATED WATERS, CONTAINING ADDED SUGAR OR OTHER SWEETENING MATTER OR FLAVOURED, AND OTHER NON-ALCOHOLIC BEVERAGES, NOT INCLUDING FRUIT, NUT OR VEGETABLE JUICES OF HEADING 2009''). Preserved verbatim in ALL CAPS as it appears in the source.", "Tariff line code ''22030000'' (Beer made from malt) represents subheading 2203 (single-dash heading with one 8-digit code, no 6-digit subheading row in the PDF). Recorded under a synthetic subheading ''2203.00'' to preserve the 7-node schema; subheading title matches the heading title.", "Tariff line code ''22041000'' represents subheading 2204.10 (Sparkling wine) with tariff suffix ''00'' — preserved as the 8-digit form ''2204.10.00'' under subheading ''2204.10''. The PDF presents this as a single-tariff-line subheading.", "Tariff line code ''22043000'' represents subheading 2204.30 (Other grape must) with tariff suffix ''00'' — preserved as ''2204.30.00'' under subheading ''2204.30''.", "Tariff line codes ''22051000'', ''22059000'', ''22060000'', ''22072000'', ''22086000'', ''22090010'', ''22090020'', ''22090090'' similarly represent single-tariff-line subheadings or direct 8-digit subheadings — preserved in NNNN.NN.NN format under their corresponding subheadings.", "Subheading 2206 has no 6-digit subheading row in the PDF; the only tariff line is ''22060000'' (Other fermented beverages...). Recorded under a synthetic subheading ''2206.00'' to preserve the 7-node schema; subheading title matches the heading title.", "Subheading 2209 has no 6-digit subheading row in the PDF beyond the prefix row ''220900'' (Vinegar and substitutes for vinegar obtained from acetic acid:). Recorded under subheading ''2209.00'' containing the three tariff lines ''2209.00.10'', ''2209.00.20'', ''2209.00.90''.", "Tariff line 2207.20.00 (Ethyl alcohol and other spirits, denatured, of any strength) carries an Export Policy of ''Restricted'' with a specific Policy Condition. Captured verbatim in the policy_conditions array with notification 62/2015-20 dated 22.03.2023.", "Tariff line 2208.40.92 description is rendered in PDF as ''Other: ---- other'' (lowercase ''o'' in ''other''). Preserved verbatim with lowercase ''other'' to match the source.", "Tariff line 2208.90.12 description in PDF reads ''Indenatured ethyl alcohol'' — likely a typographical error for ''Undenatured ethyl alcohol'' but preserved verbatim as it appears in the source. The ''Other'' tier (2208.90.92) similarly reads ''Indenatured ethyl alcohol''.", "Heading 2204 description in PDF reads ''Wine of fresh grapes, including fortified wines; grape must other than that of heading 20.09.'' The reference ''20.09'' uses dot notation; preserved verbatim from source."]'::jsonb, '{}'::jsonb, 'Chapter 22 Beverages, Spirits And Vinegar.pdf', ('2026-05-22')::timestamptz, NOW()),
  ('23', 'IV', 'RESIDUES AND WASTE FROM THE FOOD INDUSTRIES; PREPARED ANIMAL FODDER', '[{"number": "1", "text": "Heading 2309 includes products of a kind used in animal feeding, not elsewhere specified or included, obtained by processing vegetable or animal materials to such an extent that they have lost the essential characteristics of the original material, other than vegetable waste, vegetable residues and by-products of such processing."}]'::jsonb, '[{"number": "1", "text": "For the purposes of sub-heading 2306 41, the expression \"low erucic acid rape or colza seeds\" means seeds as defined in sub-heading Note 1 to Chapter 12."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["PDF source uses codes without dots (e.g., ''23011010'' for tariff lines, ''230110'' for subheadings, ''2301'' for headings). Normalized to NNNN.NN.NN format (e.g., ''2301.10.10'') and NNNN.NN (e.g., ''2301.10'') per project schema.", "PDF table-chrome headers (''Main Notes'', ''Sub-Heading Notes'', ''Policy Condition'', ''Product Description and Export Policy'', ''SI.No. Notes Notification No Notification Date'', ''Itc(hs) Code. Description Export Policy Policy Condition'') were recognized as table headers and EXCLUDED from the legal notes per extraction rules.", "Section IV Main Note about ''pellets'' appears on PDF page 1 above the Chapter 23 title and is attributed to section_notes (Section IV, Prepared Foodstuffs etc.), not chapter_notes. Together with the Chapter 23 main note this gives the expected ''Main Notes (2 notes)'' audit count.", "Chapter title on PDF page 1 is rendered as ''Chapter 23 Residues And Waste From The Food Industries; Prepared Animal Fodder.'' (with trailing period). The ''title'' field uses the canonical UPPERCASE form ''RESIDUES AND WASTE FROM THE FOOD INDUSTRIES; PREPARED ANIMAL FODDER''; source_pdf preserves the title-cased filename form.", "The Section IV header reads in full: ''Section IV, PREPARED FOODSTUFFS; BEVERAGES, SPIRITS AND VINEGAR; TOBACCO AND MANUFACTURED TOBACCO SUBSTITUTES; PRODUCTS, WHETHER OR NOT CONTAINING NICOTINE, INTENDED FOR INHALATION WITHOUT COMBUSTION; OTHER NICOTINE CONTAINING PRODUCTS INTENDED FOR THE INTAKE OF NICOTINE INTO THE HUMAN BODY'' — preserved verbatim in the section header but not duplicated as a section_note (only the numbered ''pellets'' definition is a section_note).", "Policy Condition text in the source PDF contains ''?'' characters in place of typographic quote marks (e.g., ''?Shipment Clearance Certificate?'', ''?Health Certificate?''). These are OCR/encoding artifacts from the source PDF — preserved verbatim. The intended text is ''Shipment Clearance Certificate'' and ''Health Certificate'' enclosed in quotation marks.", "Tariff line code 23061010 (''Oil-cake and oil-cake meal, decorticated, expeller variety'') appears TWICE in the source PDF: once with Notification No 23/2024-25 dated 16.08.2024 (with Policy Condition ''Export of De-oiled Rice Bran is Prohibited.'') and once with Notification No 37/2025-26 dated 03/10/2025 (no policy condition text). This is an inconsistency in the source — the newer 37/2025-26 notification likely supersedes/amends the earlier one. Both notification records are preserved in policy_conditions for completeness; the tariff line itself is listed once in the tariff_lines array.", "Heading 2302 description in the PDF is entirely uppercase (''BRAN, SHARPS AND OTHER RESIDUES...''). Heading 2306 description is also uppercase (''OIL-CAKE AND OTHER SOLID RESIDUES...''). These have been preserved verbatim in the heading title field as they appear in the source.", "Heading 2308 and 2307 in the PDF are represented directly by 8-digit tariff lines 23080000 and 23070000 (no separate heading row showing only ''2307'' or ''2308'' before the tariff line). The heading title for 2307 (''Wine lees; Argol'') and 2308 (vegetable materials text) is taken from the corresponding 8-digit tariff line description.", "Subheading ''2306.41'' is represented in the PDF only as 8-digit tariff line 23064100 (''Of rape or colza seeds : --Of low erucic acid rape or colza seeds''). Per WCO HS structure, 23064900 (''Of rape or colza seeds : -- Other'') is the sibling under the same ''-Of rape or colza seeds'' subheading family. The subheading note explicitly references ''sub-heading 2306 41'' confirming this code level. Subheadings 2306.41 and 2306.49 are presented as flat 8-digit entries; in the JSON they are grouped under subheadings ''2306.41'' and ''2306.49'' respectively for schema consistency.", "Tariff line description prefixes like ''----'' (four hyphens) and ''--'' (two hyphens) indicate the dash-level depth of the item within its subheading. These are preserved verbatim in description text per extraction rules.", "Policy Condition column entries reading ''Subject to Policy Condition 01 of the Chapter'' on Heading 2309 tariff lines are recorded against the corresponding tariff lines via the chapter-wide policy_condition entry (Notification 34/2015-20, 13.01.2017). The full text of Policy Condition 1 is captured in policy_conditions and applies to all items under Heading 2309."]'::jsonb, '{}'::jsonb, 'Chapter 23 Residues And Waste From The Food Industries; Prepared Animal Fodder.pdf', ('2026-05-22')::timestamptz, NOW()),
  ('24', 'IV', 'TOBACCO AND MANUFACTURED TOBACCO SUBSTITUTES; PRODUCTS, WHETHER OR NOT CONTAINING NICOTINE, INTENDED FOR INHALATION WITHOUT COMBUSTION; OTHER NICOTINE CONTAINING PRODUCTS INTENDED FOR THE INTAKE OF NICOTINE INTO THE HUMAN BODY', '[{"number": "1", "text": "This Chapter does not cover medicinal cigarettes (Chapter 30)."}, {"number": "2", "text": "Any products classifiable in heading 2404 and any other heading of the Chapter are to be classified in heading 2404."}, {"number": "3", "text": "For the purposes of heading 2404, the expression \"inhalation without combustion\" means inhalation through heated delivery or other means, without combustion."}]'::jsonb, '[{"number": "1", "text": "For the purposes of sub-heading 2403 11, the expression \"water pipe tobacco\" means tobacco intended for smoking in a water pipe and which consists of a mixture of tobacco and glycerol, whether or not contain-ing aromatic oils and extracts, molasses or sugar, and whether or not flavoured with fruit. However, tobacco-free products intended for smoking in a water pipe are excluded from this sub-heading."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["PDF source uses 8-digit codes without dots (e.g., ''24011010'') and 6-digit subheading codes without dots (e.g., ''240110''). Normalized to NNNN.NN.NN (e.g., ''2401.10.10'') and NNNN.NN (e.g., ''2401.10'') per project schema. 4-digit headings (e.g., ''2401'') left as-is.", "PDF tariff line code ''24022050'' description is split across two table rows: ''Filter cigarettes of length (including the length of the filter, the length of filter being 11 millimetres or its actual length, whichever is more) exceeding 75 millimetres but not'' continues on next row as ''exceeding 85 millimetres''. Recombined verbatim as a single description.", "PDF table-chrome headers (''Sl.No. Notes Notification No Notification Date'', ''Sl.No. Notes Notification Date Notification No'', ''Itc(hs) Code. Description Export Policy Policy Condition'', ''Main Notes'', ''Sub-Heading Notes'', ''Product Description and Export Policy'') were recognized as table headers and EXCLUDED from the legal notes per extraction rules.", "The Section IV Main Note about ''pellets'' appears on PDF page 1 above the Chapter 24 title. This is the standard Section IV note (Section IV covers prepared foodstuffs, beverages, spirits, vinegar, tobacco, and nicotine products) and is attributed to section_notes.", "The Notification Date and Notification No columns are EMPTY for all rows in the Main Notes and Sub-Heading Notes tables of this chapter. Captured as null.", "All tariff lines in the chapter show Export Policy ''Free'' with EMPTY Policy Condition column. No policy_conditions or export_licensing_notes apply to this chapter — both arrays are present but empty.", "Subheading 2403.11 description in PDF reads ''Smoking tobacco, whether or not containing tobacco substitutes in any proporation -- Water pipe tobacco specified in Subheading Note 1 to this chapter'' — note the PDF typo ''proporation'' (instead of ''proportion''); preserved verbatim. Same typo appears for subheading 2403.19.", "Subheading 2403.91 in PDF is represented as the single 8-digit tariff line ''24039100'' (''Other : -- Homogenised or reconstituted tobacco'') with no separate subheading row in the source — the subheading-level entry is implied. Encoded as subheading ''2403.91'' with one tariff line ''2403.91.00''.", "Heading 2404 title in PDF is rendered in ALL CAPS (''PRODUCTS CONTAINING TOBACCO, RECONSTITUTED TOBACCO, NICOTINE, OR TOBACCO OR NICOTINE SUBSTITUTES, INTENDED FOR INHALATION WITHOUT COMBUSTION; OTHER NICOTINE CONTAINING PRODUCTS INTENDED FOR THE INTAKE OF NICOTINE INTO THE HUMAN BODY'') unlike other headings in this chapter. Preserved verbatim in uppercase as in the source.", "Heading 2404 has no separate subheading rows in the PDF (only 6 tariff lines: 24041100, 24041200, 24041900, 24049100, 24049200, 24049900). Encoded as four subheadings (2404.11, 2404.12, 2404.19, 2404.91, 2404.92, 2404.99) each with a single tariff line at the .00 suffix, inferred from the 8-digit code structure.", "Heading 2403 has 8-digit codes ''24031921'' (''Biris:---- Other than paper rolled biris, manufactured without the aid of machine'') and ''24031929'' (''Biris:---- Other'') which both belong to subheading 2403.19. Grouped under subheading 2403.19 along with 24031910 and 24031990.", "Tariff line code ''24013000'' (Tobacco refuse) is encoded as subheading ''2401.30'' with single tariff line ''2401.30.00'' since the source PDF lacks a separate 6-digit subheading row for 240130."]'::jsonb, '{}'::jsonb, 'Chapter 24 Tobacco And Manufactured Tobacco Substitutes.pdf', ('2026-05-22')::timestamptz, NOW()),
  ('25', 'V', 'SALT; SULPHUR; EARTHS AND STONE; PLASTERING MATERIALS, LIME AND CEMENT', '[{"number": "1", "text": "Except where their context or Note 4 to this Chapter otherwise requires, the headings of this Chapter cover only products which are in the crude state or which have been washed (even with chemical substances eliminating the impurities without changing the structure ofthe product), crushed, ground, powdered, levigated, sifted, screened, concentrated by flotation, magnetic separation or other mechanical or physical processes (except crystallization), but not products that have been roasted, calcined, obtained by mixing or subjected to processing beyond that mentioned in each heading. The products of this Chapter may contain an added anti-dusting agent, provided that such addition does not render the product particularly suitable for specific use rather than for general use."}, {"number": "2", "text": "This Chapter does not cover : (a) sublimed sulphur, precipitated sulphur and colloidal sulphur (heading 2802); (b) earth colours containing 70% or more by weight of combined iron evaluated as Fe2O3 (heading 2821); (c) medicaments and other products of Chapter 30; (d) perfumery, cosmetic or toilet preparations (Chapter 33); (e) dolomite ramming mix (heading 3816); (f) setts, curbstones and flagstones (heading 6801); mosaic cubes or the like (heading 6802); roofing, facing or damp course slates (heading 6803); (g) precious or semi-precious stones (heading 7102 or 7103); (h) cultured crystals (other than optical elements) weighing not less than 2.5g each, of sodium chloride or of magnesiumoxide, of heading 3824; optical elements ofsodiumchloride or of magnesium oxide (heading 9001); (ij) billiard chalks (heading 9504); or (k) writing or drawing chalks and tailors? chalks (heading 9609)."}, {"number": "3", "text": "Any products classifiable in heading 2517 and any other heading of this Chapter are to be classified in heading 2517."}, {"number": "4", "text": "Heading 2530 applies, inter alia, to : vermiculite, perlite and chlorites, unexpanded; earth colours, whether or not calcined or mixed together; natural micaceous iron oxides; meerschaum (whether or not in polished pieces); amber; agglomerated meerschaumand agglomerated amber, in plates, rods,sticks orsimilar forms, not worked after moulding; jet; strontianite (whether or not calcined), other than strontium oxide; broken pieces of pottery, brick or concrete."}]'::jsonb, '[]'::jsonb, '[{"number": "1", "text": "In heading 2523, \"sagol\" means cement obtained by heating limestone and burnt coal in a kiln; and \"ashmoh\" means cement obtained by fine grinding of paddy husk, ash and hydrated lime with an additive."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["Source PDF tariff codes use no-dot 8-digit format (NNNNNNNN). All codes normalized to NNNN.NN.NN per project schema by inserting dots after positions 4 and 6. Subheading codes (e.g. ''250100'') normalized to NNNN.NN (e.g. ''2501.00''); heading codes (e.g. ''2501'') preserved as 4 digits.", "Chapter 25 opens Section V (Mineral Products). PDF page 1 carries the subtitle ''Section V, MINERAL PRODUCTS'' but contains NO separate Section V Main Notes table — only Chapter 25 Main Notes (4 notes) and a Chapter 25 Supplementary Notes table (1 note). Therefore section_notes is empty for this chapter; Section V notes (if any exist at Schedule level) must be captured from the Section V cover page if/when extracted separately.", "Supplementary Notes captured in top-level ''supplementary_notes'' array (convention chosen for this chapter; not merged into chapter_notes).", "Note 2 (the main exclusion note) lists sub-clauses (a) through (k) as a single verbatim block. Each sub-clause is extracted as a separate exclusion_clauses entry.", "Note 2 sub-clause (h) contains OCR/spacing artifacts in the source PDF: ''magnesiumoxide'' (magnesium oxide), ''ofsodiumchloride'' (of sodium chloride). Preserved verbatim in source_note_text; normalized in excluded_product_text where needed for readability.", "Note 2 sub-clause (k) contains an OCR artifact ''tailors? chalks'' where ''?'' is a typographic apostrophe (intended: \"tailors'' chalks\"). Preserved verbatim.", "Note 4 contains OCR/spacing artifacts: ''meerschaumand'' (meerschaum and), ''rods,sticks'' (rods, sticks), ''orsimilar'' (or similar). Preserved verbatim.", "PDF table-chrome rows (''Main Notes'', ''Supplementary Notes'', ''Sl.No. Notes Notification Date Notification No'', ''Product Description and Export Policy'', ''Itc(hs) Code. Description Export Policy Policy Condition'') were recognized as table headers and EXCLUDED from the legal notes per extraction rules.", "Several headings in the PDF show a heading-level description row (4-digit code) followed by a subheading-level description row (6-digit code, e.g. ''250100'') that repeats/rephrases the heading description verbatim. The 6-digit row is the WCO international subheading description; preserved as the subheading title where present.", "Heading 2527 is absent from the source PDF (the heading sequence jumps from 2526 to 2528). 2527 is reserved internationally (Natural cryolite; natural chiolite) but carries no tariff lines in the Indian Schedule 2 PDF for this chapter. Not included in headings array.", "Subheading 2515.11 appears in the source as code ''251511'' but the PDF shows only the 8-digit tariff line ''25151100'' (Marble and travertine -- Crude or roughly trimmed) with no separate 6-digit subheading row. Subheading constructed from the 8-digit code; subheading title taken verbatim from the tariff line description. Same pattern for 2515.20 (split label row ''251520'' provides ''Ecaussine and other calcareous monumental or building stone;''), 2516.11, 2516.12, 2516.20, 2516.90 (label row ''251690'' present), 2517.10, 2517.20, 2517.30, 2517.41, 2517.49, 2518.10, 2518.20, 2519.10, 2519.90, 2520.10, 2520.20, 2521.00, 2522.10, 2522.20, 2522.30, 2523.10, 2523.21, 2523.29, 2523.30, 2523.90, 2524.10, 2524.90, 2525.10, 2525.20, 2525.30, 2526.10, 2526.20, 2528.00, 2529.10, 2529.21, 2529.22, 2529.30, 2530.10, 2530.20, 2530.90.", "Heading 2502 has a single tariff line ''25020000'' (UNROASTED IRON PYRITES) with no separate 6-digit subheading row in the PDF. Modelled as subheading ''2502.00'' with title ''Unroasted iron pyrites.'' (heading-level description, verbatim from heading row), with the single tariff line attached.", "Heading 2509 has a single tariff line ''25090000'' (Chalk) with no separate 6-digit subheading row. Modelled as subheading ''2509.00'' with title ''Chalk''.", "Heading 2514 has a single tariff line ''25140000'' (Slate, ...) with no separate 6-digit subheading row. Modelled as subheading ''2514.00''.", "Numeric inline expressions in the PDF render with no space: ''85percent'' (Note 4 / heading 2528), ''97 percent'' (heading 2529 fluorspar — space preserved in source), ''1percent SiO2'' (tariff 25210010), ''2.5g each'' (Note 2 (h)). Preserved verbatim.", "Some heading titles in the PDF are rendered in ALL CAPS (e.g. headings 2503, 2507, 2512, 2518, 2521, 2528) while others are sentence case. Preserved verbatim per source.", "Heading 2503 title in PDF reads ''SULPHUR OF ALL KINDS, OTHER THAN SUBLIMED SULPHUR, PRECIPITATED SULPHUR AND COLLODIAL SULPHUR''. The 6-digit row ''250300'' provides the sentence-case form ''Sulphur of all kinds, other than sublimed sulphur, precipitated sulphur and colloidal sulphur.'' — note that the heading-level uppercase form has ''COLLODIAL'' (likely typo) while the subheading form has ''colloidal''. Both preserved verbatim in their respective fields.", "Tariff 25241010 (Crocidolite) carries Export Policy ''Free'' with Policy Condition ''Export of Crocidolite is free subject to No Objection Certificate from the Department of Chemicals and Petro-Chemicals, Ministry of Chemicals and Fertilizers, New Delhi''. Captured in policy_conditions array.", "Tariff lines 25085031, 25085032, 25085039 (Sillimanite) and 25132030 (Natural garnet) carry Export Policy ''STE (State Trading Enterprise)'' with Policy Condition ''Export is allowed through Indian Rare Earths Limited (IREL) only.'' Captured in policy_conditions array.", "Tariff lines under subheading 2505.10 (Silica sands and quartz sands: 25051011, 25051012, 25051019, 25051020) and 2505.90 (25059000 Other) carry Export Policy ''Restricted''. Tariff 25309099 (Other: ---- Other under heading 2530) also ''Restricted''. Captured in policy_conditions array.", "No ''unit'' column appears in the source PDF for Chapter 25 tariff lines — units set to null throughout."]'::jsonb, '{}'::jsonb, 'Chapter 25 Salt; Sulphur; Earths And Stone; Plastering Materials, Lime And Cement.pdf', ('2026-05-22')::timestamptz, NOW()),
  ('26', 'V', 'ORES, SLAG AND ASH', '[{"number": "1", "text": "This Chapter does not cover: (a) slag or similar industrial waste prepared as macadam (heading 2517); (b) natural magnesium carbonate (magnesite), whether or not calcined (heading 2519); (c) sludges from the storage tanks of petroleum oils, consisting mainly of such oils (2710); (d) basic slag of Chapter 31; (e) slag wool, rock wool or similar mineral wools (heading 6806); (f) waste or scrap of precious metal or of metal clad with precious metal; other waste or scrap containing precious metal or precious metal compounds, of a kind used principally for the recovery of precious metal (heading 7112 or 8549); or (g) copper, nickel or cobalt mattes produced by any process of smelting (Section XV)."}, {"number": "2", "text": "For the purposes of headings 2601 to 2617, the term \"ores\" means minerals of mineralogical species actually used in the metallurgical industry for the extraction of mercury, of the metals of heading 2844 or of the metals of Section XIV or XV, even if they are intended for nonmetallurgical purposes. Headings 2601 to 2617 do not, however, include minerals which have been submitted to processes not normal to the metallurgical industry"}, {"number": "3", "text": "Heading 2620 applies only to: (a) slag, ash and residues of a kind used in industry either for the extraction of metals or as a basisforthe manucture of chemical compounds ofmetals, excluding ash and residuesfromthe incineration of municipal waste (heading 2621); and (b) slag, ash and residues containing arsenic, whether or not containing metals, of a kind used either for the extraction of arsenic or metals or for the manufacture of their chemical compounds."}]'::jsonb, '[{"number": "1", "text": "For the purposes of sub-heading 2620 21, \"leaded gasoline sludges and leaded anti- knock compound sludges\" mean sludges obtained from storage tanks of leaded gasoline and leaded anti-knock compounds (for example, tetraethyl lead), and consisting essentially of lead, lead compounds and iron oxide."}, {"number": "2", "text": "Slag, ash and residues containing arsenic, mercury, thallium or their mixtures, of a kind used for the extraction of arsenic or those metals or for the manufacture of their chemical compounds, are to be classified in sub-heading 2620 60."}]'::jsonb, '[{"number": "1", "text": "For the products of heading 2601, the percentage of Fe content, wherever specified, shall be calculated on the Dry Weight or Dry Metric Tonne (DMT) basis."}]'::jsonb, '[{"number": "1", "text": "Rare Earth compounds are freely exportable, but rare earth phosphates, which contain uranium and thorium are prescribed substances and are controlled as per provisions of Atomic Energy Act, 1962 ."}, {"number": "2", "text": "Other minerals under code 2617 are freely exportable, except those which have been notified as prescribed substances and controlled under Atomic Energy Act, 1962."}]'::jsonb, '[]'::jsonb, '["PDF source uses codes without dots — 8-digit (e.g., ''26011111''), 6-digit subheading (e.g., ''260111''), and 4-digit heading (e.g., ''2601''). Normalized to NNNN.NN.NN, NNNN.NN, and NNNN format per project schema.", "PDF table-chrome headers (''Main Notes'', ''Sl.No. Notes Notification Date Notification No'', ''Sub-Heading Notes'', ''Supplementary Notes'', ''Policy Condition'', ''Export Licensing Notes'', ''Product Description and Export Policy'', ''Itc(hs) Code. Description Export Policy Policy Condition'') were recognized as table chrome and EXCLUDED from the legal notes per extraction rules.", "Section V chapter header reads ''Section V, MINERAL PRODUCTS''. The ''Main Notes'' table in this chapter PDF lists 3 notes that are chapter-specific (Note 1 exclusions from this Chapter; Note 2 defining ''ores'' for headings 2601-2617; Note 3 scope of heading 2620). These are attributed to chapter_notes (Chapter 26), not section_notes — the source PDF does not include Section V section-level notes in this file.", "PDF source contains spacing artifacts in several notes (e.g., ''manucture'' for ''manufacture'', ''compoundsofmetals'' for ''compounds of metals'', ''residuesfromthe'' for ''residues from the'', ''20percentor'' for ''20 percent or''). Preserved verbatim as they appear in the source.", "Tariff line descriptions use ''percent'' instead of ''%'' symbol verbatim (e.g., ''60percent Fe or more but below 62percent Fe''). Preserved verbatim.", "Subheading 2602.00 has 9 tariff lines (2602.00.10 through 2602.00.90) under it. The Export Policy column shows ''Restricted'' for 2602.00.10 and ''STE (State Trading Enterprise)'' for 2602.00.20 through 2602.00.90 with policy condition ''Export is allowed through Manganese Ore India Limited (MOIL) only.'' for the STE entries.", "Heading 2610 (CHROMIUM ORES AND CONCENTRATES) has all 5 tariff lines marked ''Restricted'' with Notification No ''13/2023'' and Date ''22.06.2023'' — captured verbatim in policy_conditions metadata on each tariff line.", "Tariff line 2601.12.10 (Iron ore pellets) has Notification No ''92(RE-2013)'' and Date ''26.09.2014'' for the export policy/policy condition note about KIOCL.", "Tariff line 2601.11.50 (Iron ore concentrates) Policy Condition column contains long verbatim text about Kudremukh Iron Ore Company Limited exemption — preserved verbatim across page break (pages 5-6).", "Tariff line 2601.12.90 (Other) Policy Condition column contains verbatim text about Rejects of iron ore chips with 10% quantity limit and 6mm size limit — preserved verbatim.", "Subheadings 2601.11, 2601.12, 2606.00, 2610.00, 2614.00, 2615.90, 2616.90, 2619.00, 2620.19, 2620.29, 2620.30, 2620.40, 2620.90 are explicit in the PDF and captured as subheadings. Single-tariff-line subheadings such as 2601.20, 2603.00, 2604.00, 2605.00, 2607.00, 2608.00, 2609.00, 2611.00, 2612.10, 2612.20, 2613.10, 2613.90, 2615.10, 2616.10, 2617.10, 2617.90, 2618.00, 2620.11, 2620.60, 2620.91, 2620.99, 2621.10, 2621.90 are inferred from the 8-digit codes where the PDF does not show an explicit 6-digit row.", "Tariff line 2620.11.00 in PDF appears as code ''26201100'' under heading 2620 — normalized to 2620.11.00 (subheading 2620.11). Similarly 2620.60.00, 2620.91.00, 2620.99.00.", "Heading 2602 PDF description appears in ALL CAPS with text wrapping: ''MANGANESE ORES AND CONCENTRATES, INCLUDING FERRUGINOUS MANGANESE ORES AND CONCENTRATES WITH A MANGANESE CONTENT OF 20% OR MORE, CALCULATED ON THE DRY WEIGHT''. The lower-case subheading 2602.00 description is also present in the PDF — both preserved verbatim.", "Heading 2610 PDF description appears in ALL CAPS: ''CHROMIUM ORES AND CONCENTRATES''. Subheading 2610.00 description is ''Chromium ores and concentrates.'' — both preserved verbatim.", "PDF heading 2615 contains subheading 2615.90 ''Other'' which contains tariff lines 2615.90.10 (Vanadium) and 2615.90.20 (Niobium tantalum). Tantalum and vanadium ores from the heading title are covered under 2615.90.", "Policy Condition row 1 references ''Iron ore of Goa origin'', ''Iron ore of Redi origin'', and ''STE'' (State Trading Enterprise) — preserved verbatim.", "Export Licensing Note 1 references ''Atomic Energy Act, 1962'' for rare earth phosphates containing uranium/thorium. Export Licensing Note 2 references ''code 2617'' (Other ores and concentrates).", "Tariff line 2601.11.29 PDF description is ''Iron ore lumps (below 60percent Fe, including black iron ore containing up to 10percent Mn) ---- 58 percent Fe or more but below 60 percent Fe'' — note the page-break in the PDF separates ''but below 60 percent Fe'' onto the next page. Concatenated verbatim.", "Unit-of-measure column is NOT shown in this chapter''s PDF — unit field set to null for all tariff lines."]'::jsonb, '{}'::jsonb, 'Chapter 26 Ores, Slag And Ash.pdf', ('2026-05-22')::timestamptz, NOW()),
  ('27', 'V', 'MINERAL FUELS, MINERAL OILS AND PRODUCTS OF THEIR DISTILLATION; BITUMINOUS SUBSTANCES; MINERAL WAXES', '[{"number": "1", "text": "This Chapter does not cover: (a) separate chemically defined organic compounds other than pure methane and propane which are to be classified in heading 2711; (b) medicaments of heading 3003 or 3004; or (c) mixed unsaturated hydrocarbons of heading 3301, 3302 or 3805."}, {"number": "2", "text": "Referencesin heading 2710 to \"petroleumoils and oils obtained from bituminous minerals\" include not only petroleumoils and oils obtained from bituminous minerals but also similar oils, as well asthose consisting mainly of mixed unsaturated hydrocarbons, obtained by any process, provided that theweight ofthe non-aromatic constituents exceedsthat of the aromatic constituents. However, the references do not include liquid synthetic polyolefins of which less than 60% by volume distils at 3000C, after conversion to 1,013 millibars when a reduced-pressure distillationmethod is used (Chapter 39)."}, {"number": "3", "text": "For the purposes of heading 2710, \"\"\"waste oils\"\"\" means waste containing mainly petroleum oils and oils obtained from bituminous minerals (as described in Note 2 to this Chapter), whether or not mixed with water. These include: (a) such oils no longer fitfor use as primary products(for example, used lubricating oils, used hydraulic oils and used transformer oils); (b)sludge oils from the storage tanks of petroleum oils, mainly containing such oils and high concentration of additives (for example, chemicals) used in the manufacture of the primary products; and (c) such oils in the form of emulsions in water or mixtures with water, such as those resulting from oil spills,storage tankwashings, orfromthe use of cutting oilsfor machining operations."}]'::jsonb, '[{"number": "1", "text": "For the purposes of sub-heading 2701 11 \"anthracite\" means coal having a volatile matter limit (on a dry, mineral-matter-free basis) not exceeding 14%."}, {"number": "2", "text": "For the purposes of sub-heading 2701 12, \"bituminous coal\" means coal havinga volatile matter limit (on a dry, mineral-matter-free basis) exceeding 14% and a calorific value limit (on amoist, mineral-matter-free basis) equal to or greater than 5,833 kcal/kg."}, {"number": "3", "text": "For the purposes of tariff items 2707 10 00, 2707 20 00, 2707 30 00 and 2707 40 00, the terms \"benzol\", \"(benzene)\", \"toluol\" (toluene)\", \"xylol\" (xylenes)\" and \"naphthalene\" apply to products which contain more than 50% by weight of benzene, toluene, xylenes or naphthalene, respectively."}, {"number": "4", "text": "For the purposes of sub-heading 2710 12, \"light oils and preparations\"are those of which 90 % or more by volume (including losses) distil at 210 Caccording to the ISO 3405 method (equivalent to theASTM D 86 method)."}, {"number": "5", "text": "For the purposes of the sub-headings of heading 2710, the term \"biodiesel\" means mono-alkyl esters of fatty acids of a kind used as a fuel, derived from animal, vegetable or microbial fats and oils whether or not used."}]'::jsonb, '[{"number": "1", "text": "In this Chapter, reference to any standard of the Bureau of Indian Standards refers to the last published version of that standard. Illustration : IS 1459 refers to IS 1459: 2018 and not to IS 1459: 1974 (a) \"\"\"motor spirit\"\"\" means any hydrocarbon oil (excluding crude mineral oil) which has its flash point below 250C and which either by itself or in admixture with any other substance, is suitable for use as fuel in spark ignition engines. \"\"\"Special boiling point spirits (tariff item Nos. 2710 12 11, 2710 12 12 and 2710 12 13)\"\"\" means light oils, as defined in Sub-heading Note 4, not containing any anti-knock preparations , and with a difference of not more than 600C between the temperatures at which 5% and 90% by volume ( including losses) distil; (b) \"\"\"natural gasoline liquid (NGL)\"\"\" is a low?boiling liquid petroleum product extracted from Natural Gas; (c) \"\"\"superior kerosine oil (SKO)\"\"\" means any hydrocarbon oil conforming to the Indian Standards Specification of Bureau of Indian Standards IS : 1459-1974 (Reaffirmed in the year 1996); (d) \"\"\"aviation turbine fuel (ATF)\"\"\" means any hydrocarbon oil conforming to the Indian Standards Specification of Bureau of Indian Standards IS : 1571:1992:2000; (e) \"\"\"high speed diesel (HSD)\"\"\" means any hydrocarbon oil conforming to the Indian Standards Specification of Bureau of Indian Standards IS: 1460:2005; (f) \"\"\"light diesel oil (LDO)\"\"\" means any hydrocarbon oil conforming to the Indian Standards Specification of Bureau of Indian Standards IS: 15770:2008; (g) \"\"\"fuel oil\"\"\" means any hydrocarbon oil conforming to the Indian Standards Specification of Bureau of Indian Standards IS:1593:1982 (Reaffirmed in the year 1997); (h) \"\"\"lubricating oil\"\"\" means any oil, which is ordinarily used, for lubrication, excluding any hydrocarbon oil, which has its flash point below 93.30 Centigrade; (i) \"\"\"jute batching oil\"\"\" and \"\"\"textile oil\"\"\" are hydrocarbon oils which have their flash point at or above 93.30C, and is ordinarily used for the batching of jute or other textile fibres; (j) the expression \"\"\"petroleum jelly crude\"\"\" (tariff item Nos. 2712 10 10) shall be taken to apply to petroleum jelly of a natural colour higher than 4.5 by the ASTM D 1500 method; (k) for the purposes of these additional notes, the tests prescribed have the meaning hereby assigned to them: (1) \"\"\"Flash Point\"\"\" shall be determined in accordance with the test prescribed in this behalf in the rules made under the Petroleum Act, 1934 (30 of 1934); (2) \"\"\"Smoke Point\"\"\" shall be determined in the apparatus known as the Smoke Point Lamp in the manner indicated in the Indian Standards Institution specification IS:1448 (p. 31)-1967 as for the time being in force; (3) \"\"\"Final Boiling Point\"\"\" shall be determined in the manner indicated in the Indian Standards Institution specification IS:1448 (p.18)-1967 as for the time being in force; (4) \"\"\"Carbon Residue\"\"\" shall be determined in the apparatus known as Ramsbottom Carbon Residue Apparatus in the manner indicated in the Indian Standards Institution specification IS:1448 (p.8)-1967 as for the time being in force; (5) \"\"\"Colour Comparision Test\"\"\" shall be done in the following manner, namely : (i) first prepare a five per cent. weight by volume solution of Potassium Iodine (analytical reagent quality) in distilled water; (ii) to this, add Iodine (analytical reagent quality) in requisite amount to prepare exactly 0.04 normal Iodine solution; (iii) thereafter, compare the colour of the mineral oil under test with the Iodine solution so prepared. (l) for the purposes of tariff item 2710 19 33, the term ?Blended Aviation turbine fuel? means any Aviation turbine fuel containing by weight 70% or more of Petroleum Oils or Oils obtained from Bituminous Minerals, blended with Synthesized Hydrocarbons conforming to Indian Standards Specification of Bureau of Indian Standards IS 17081:2019."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["Source PDF uses no-dot tariff code format (NNNNNNNN). All codes have been normalized to NNNN.NN.NN by inserting dots after positions 4 and 6.", "Source PDF contains OCR/typographic artifacts where some words run together (e.g. ''havinga'' for ''having a'', ''amoist'' for ''a moist'', ''preparations\"are'' for ''preparations\" are'', ''theASTM'' for ''the ASTM''). Preserved verbatim.", "Source PDF wraps quoted terms with multiple stray double-quote characters (e.g. ''\"\"\"motor spirit\"\"\"'', ''\"\"\"waste oils\"\"\"''). These quote-cluster artifacts are preserved verbatim in chapter_notes / subheading_notes / supplementary_notes.", "Source PDF contains ''?'' character substitutions where the original had hyphens or special characters (e.g. ''low?boiling'' for ''low-boiling'', ''?Blended Aviation turbine fuel?'' for ''-Blended Aviation turbine fuel-''). Preserved verbatim.", "Subheading 2710.91 Waste oils is not labelled with an explicit subheading-level row in the PDF; tariff items 2710.91.10, 2710.91.20, 2710.91.90 appear after subheading 2710.20 with descriptions starting ''--- Containing polychlorinated biphenyls...'' indicating the parent subheading 2710.91 Waste oils. Reconstructed accordingly.", "Tariff item 2710.99.00 in PDF reads ''Waste oils : -- Other'' which is the description for subheading 2710.99 (Other waste oils). Preserved verbatim as the description of the 8-digit tariff line 2710.99.00.", "Heading 2701 in source PDF jumps from 2701.11.00 (Anthracite Coal) directly to subheading 2701.12 (Bituminous coal); there is no implied 2701.11 subheading row (8-digit code 2701.11.00 stands alone). Preserved as captured.", "Heading 2709 has the row ''Petroleum oils and oils obtained from bituminous minerals, crude'' repeated three times in PDF (heading 2709, subheading 270900, and a second 270900 row with Notification No 50/2015-2020 dated 11.11.2013). Captured as one heading + one subheading; the duplicate 270900 row is reflected in policy_conditions / tariff-line notification metadata on 2709.00.10 and 2709.00.90.", "Tariff line 2710.12.31 description is split across two rows in the PDF; reassembled verbatim (''Solvent 60/80, solvent 50/120 and solvent 145/205 (petroleum hydrocarbon solvents) as specified under standard IS 1745: ---- Solvent 60/80'').", "Tariff line 2710.19.77 description is split across two rows in the PDF; reassembled verbatim (''Base oil and lubricating oil: ---- Turbine lubricating oil conforming to standard IS 1012'').", "Tariff line 2710.19.89 description is split across two rows in the PDF; reassembled verbatim (''Cutting oil, hydraulic oil, industrial white oil, jute batching oil, mineral oil for cosmetic industry, transformer oil: --- Other cutting oil, hydraulic oil, industrial white oil, jute batching oil, mineral oil for cosmetic industry, transformer oil, not conforming to any BIS standard'').", "Policy Condition reference markers in the PDF cite ''Policy Condition 1 of the Chapter'' and ''Policy Condition 2 of the Chapter'' with notification 44958 dated 01.04.2023. The serial number 44958 is preserved verbatim from the PDF (no notification-number format adjustment).", "The PDF presents no Unit column. All tariff_lines have unit set to null.", "Section V (MINERAL PRODUCTS) has no Section Notes printed in this chapter PDF; section_notes is an empty array.", "Chapter 27 has no Chapter Heading Notes (heading_notes is empty for every heading); only Main Notes (chapter_notes), Sub-Heading Notes (subheading_notes) and Supplementary Notes are provided.", "Supplementary Note 1 of the chapter is a long BIS-standards definition note covering multiple terms (''motor spirit'', ''Special boiling point spirits'', ''natural gasoline liquid (NGL)'', ''superior kerosine oil (SKO)'', ''aviation turbine fuel (ATF)'', ''high speed diesel (HSD)'', ''light diesel oil (LDO)'', ''fuel oil'', ''lubricating oil'', ''jute batching oil'', ''textile oil'', ''petroleum jelly crude'', and test definitions for Flash Point, Smoke Point, Final Boiling Point, Carbon Residue, Colour Comparision Test, and Blended Aviation turbine fuel). Captured as a single supplementary_note (number ''1'') with the full verbatim text spanning the multi-page note.", "Tariff item 2712.90.10 description in PDF reads ''Micro-CrystallinePetroleum wax'' (no space). Preserved verbatim.", "Heading 2716 has only one 8-digit tariff line (2716.00.00 Electrical Energy); no subheading-level row is present in the PDF. Reconstructed with an implied subheading ''2716.00'' wrapping the single tariff line, with subheading description identical to the heading."]'::jsonb, '{}'::jsonb, 'Chapter 27 Mineral Fuels, Mineral Oils And Products Of Their Distillation; Bituminous Substances; Mineral Waxes.pdf', ('2026-05-22')::timestamptz, NOW()),
  ('28', 'VI', 'INORGANIC CHEMICALS; ORGANIC OR INORGANIC COMPOUNDS OF PRECIOUS METALS, OF RARE-EARTH METALS, OF RADIOACTIVE ELEMENTS OR OF ISOTOPES', '[{"number": "1", "text": "Except where the context otherwise requires, the headings of this Chapter apply only to: (a) separate chemical elements and separate chemically defined compounds, whether or not containing impurities; (b) the products mentioned in (a) above dissolved in water; (c) the products mentioned in (a) above dissolved in other solvents provided that the solution constitutes a normal and necessary method of putting up these products adopted solely for reasons of safety or for transport and that the solvent does not render the product particularly suitable for specific use rather than for general use; (d) the products mentioned in (a), (b) or (c) above with an added stabiliser (including an anticaking agent) necessary for their preservation or transport; (e) the products mentioned in (a), (b), (c) or (d) above with an added anti-dusting agent or a colouring substance added to facilitate their identification or for safety reasons, provided that the additions do not render the product particularly suitable for specific use rather than for general use."}, {"number": "2", "text": "In addition to dithionites and sulphoxylates, stabilised with organic substances (heading 2831), carbonates and peroxocarbonates of inorganic bases (heading 2836), cyanides, cyanide oxides and complex cyanides ofinorganic bases(heading 2837),fulminates, cyanates and thiocyanates, of inorganic bases(heading 2842), organic products included in headings 2843 to 2846 and 2852 carbides (heading 2849), only the following compounds of carbon are to be classified in this Chapter: (a) oxides of carbon, hydrogen cyanide and fulminic, isocyanic, thiocyanic and other simple or complex cyanogen acids (heading 2811); (b) halide oxides of carbon (heading 2812); (c) carbon disulphide (heading 2813); (d) thiocarbonates, selenocarbonates, tellurocarbonates, selenocyanates, tellurocyanates, tetrathiocyanatodiamminochromates (reineckates) and other complex cyanates, of inorganic bases (heading 2842); (e) hydrogen peroxide, solidified with urea (heading 2847), carbon oxysulphide, thiocarbonyl halides, cyanogen, cyanogen halides and cyanamide and its metal derivatives (heading 2853) other than calcium cyanamide, whether or not pure (Chapter 31)."}, {"number": "3", "text": "Subject to the provisions of Note 1 to Section VI, this Chapter does not cover: (a) sodium chloride or magnesium oxide, whether or not pure, or other products of Section V; (b) organo-inorganic compounds other than mentioned in Note 2 above; (c) products mentioned in Note 2, 3 , 4 or 5 to Chapter 31; (d) inorganic products of a kind used as luminophores, of heading 3206; glass frit and other glass in the form of powder, granules or flakes, of heading 3207; (e) artificial graphite (heading 3801); products put up as charges for fire extinguishers or put up in fire-extinguishing grenades, of heading 3813; ink removers put up in packings for retail sale, of heading 3824; cultured crystals (other than optical elements) weighing not less than 2.5 g each, of the halides of the alkali or alkaline-earth metals, of heading 3824; (f) precious or semi-precious stones (natural, synthetic or reconstructed) or dust or powder of such stones (headings 7102 to 7105), or precious metals or precious metal alloys of Chapter 71; (g) the metals, whether or not pure, metal alloys or cermets, including sintered metal carbides (metal carbides sintered with a metal), of Section XV; or (h) optical elements, for example, of the halides of the alkali or alkaline-earth metals (heading 9001)."}, {"number": "4", "text": "Chemically defined complex acids consisting of a non-metal acid of Sub-Chapter II and a metal acid of Sub-Chapter IV are to be classified in heading 2811."}, {"number": "5", "text": "Headings 2826 to 2842 apply only to metal or ammonium salts or peroxysalts. Except where the context otherwise requires, double or complex salts are to be classified in heading 2842."}, {"number": "6", "text": "Heading 2844 applies only to: (a) technetium (atomic No. 43), promethium (atomic No. 61), Polonium (atomic No. 84) and all elements with an atomic number greater than 84; (b) natural or artificial radioactive isotopes (including those of the precious metals or of the base metals of Sections XIV and XV), whether or not mixed together; (c) compounds, inorganic or organic, of these elements or isotopes, whether or not chemically defined, whether or not mixed together; (d) alloys, dispersions (including cermets), ceramic products and mixtures containing these elements or isotopes or inorganic or organic compounds thereof and having a specific radioactivity exceeding 74 Bq/g (0.002 micro ci/g); (e) spent (irradiated) fuel elements (cartridges) of nuclear reactors; (f) radioactive residues whether or not usable. The term \"\"\"isotopes\"\"\", for the purposes of this Note and of the wording of headings 2844 and 2845, refers to: (i) individual nuclides, excluding, however, those existing in nature in the monoisotopic (ii) mixtures of isotopes of one and the same element, enriched in one or several of the said isotopes, that is, elements of which the natural isotopic composition has been artiticially modified."}, {"number": "7", "text": "Heading 2853 includes copper phosphide (phosphor copper) containing more than 15 % by weight of phosphorus."}, {"number": "8", "text": "Chemical elements(for example,silicon and selenium) doped for use in electronics are to be classified in this Chapter, provided that they are in forms unworked as drawn, or in the form of cylinders or rods. When cut in the forms of discs, wafers or similar forms, they fall in heading 3818."}]'::jsonb, '[{"number": "1", "text": "For the purposes of sub-heading 2852 10, the expression \"chemically defined\" means all organic or inorganic compounds of mercury meeting the requirements of clauses (a) to (e) of Note 1 to Chapter 28 or clauses ( a) to (h) of Note 1 to Chapter 29."}]'::jsonb, '[{"number": "1", "text": "Sub-heading 2804 40 includes, liquefied or solidified gas."}, {"number": "2", "text": "In this Chapter, reference to any standard of the Bureau of Indian Standards refers to the last published version of that standard."}]'::jsonb, '[{"number": "1", "text": "Export of Potassium Permanganate is freely allowed subject to No Objection Certificate from Narcotics Commissioner, Gwalior."}]'::jsonb, '[]'::jsonb, '["PDF source uses 8-digit codes without dots (e.g., ''28011000'') and 6-digit subheading codes without dots (e.g., ''280130''). Normalized to NNNN.NN.NN format (e.g., ''2801.10.00'') and NNNN.NN format (e.g., ''2801.30'') per project schema.", "PDF table-chrome headers (''Main Notes'', ''Sub-Heading Notes'', ''Supplementary Notes'', ''Policy Condition'', ''Export Licensing Notes'', ''Sl.No. Notes Notification Date Notification No'', ''Product Description and Export Policy'', ''Itc(hs) Code. Description Export Policy Policy Condition'') were recognized as table chrome and EXCLUDED from the legal notes per extraction rules.", "Section VI ''Main Notes'' (4 notes) printed at the top of the Chapter 28 PDF are attributed to section_notes (Section VI, Products of the Chemical or Allied Industries), not chapter_notes.", "Chapter title on PDF page 1 reads ''Chapter 28 Inorganic Chemicals; Organic Or Inorganic Compounds Of Precious Metals, Of Rare-Earth Metals, Of Radioactive Elements Or Of Isotopes.'' — uppercased to ITC(HS) canonical form in the title field; source_pdf preserves the original filename.", "Chapter 28 Note 6 contains OCR artifact: the word ''isotopes'' appears wrapped in triple-double-quote characters as ''\"\"\"isotopes\"\"\"'' — preserved verbatim. Also contains spelling ''artiticially'' (sic) instead of ''artificially'' — preserved verbatim from source.", "PDF subheading 2842.90 has ''----'' (4-dash) and ''--'' indents which were used to infer the subheading parent. The tariff lines 2842.90.10 (Arsenites and arsenates), 2842.90.20 (Bichromates and dichromates), 2842.90.90 (Other) are grouped under the implicit subheading 2842.90 (''Other'').", "Subheading 2843.10 ''Colloidal precious metals'' appears as a 6-digit grouping (PDF code ''284310'') with three 8-digit tariff lines (2843.10.10/20/90). Preserved as a subheading-with-tariff-lines pattern.", "Subheading 2844.30 PDF description has subitem indents (Compounds of thorium or of uranium depleted in U235:) inside tariff line 2844.30.10 — preserved verbatim including the trailing colon, since the PDF treats it as a compound description.", "Heading 2844 tariff line 2844.43.00 description in the PDF spans across page break and includes the leading word ''headings'' which is a wrapped continuation of ''2844 10, 2844 20 or 2844 30'' from the previous page. Concatenated verbatim into a single description.", "Heading 2844 tariff line 2844.44.00 description in the PDF begins with a literal opening double-quote (''\"Radioactive elements...''). This appears to be an OCR artifact from a quoted phrase in the source; preserved verbatim.", "Heading 2848 (''Phosphides...'') is not present in this PDF — heading 2847 (Hydrogen peroxide) is followed directly by heading 2849 (Carbides). Heading 2848 was deleted in HS 2017 (phosphides moved to 2853). Preserved as listed in PDF.", "Heading 2851 is not present in the PDF (deleted in HS 2017 — contents moved to 2853 and 2852). Heading 2850 (Hydrides etc.) is followed by 2852 (Inorganic or organic compounds of mercury). Preserved as listed in PDF.", "Subheading 2850.00 contains tariff line code 2850.00.41 (Silicides: ---- Of calcium) and 2850.00.49 (Silicides: ---- Other) — these are 4-dash sub-classifications under an implicit sub-grouping ''Silicides''. Preserved verbatim with the leading ''Silicides:'' prefix.", "Subheading 2841.30 ''Sodium dichromate'' has no sub-subheading code printed in the PDF (no ''284130'' 6-digit code shown explicitly); the 8-digit tariff line 2841.30.00 is shown directly. Inferred subheading 2841.30 from the code structure.", "Subheadings 2841.50, 2841.61, 2841.69, 2841.70, 2841.80, 2841.90: 2841.61 and 2841.69 are shown as 8-digit codes (2841.61.00, 2841.69.00) without explicit 6-digit subheading rows in the PDF. Inferred subheadings from code structure.", "Subheading 2843.21 (Silver compounds: -- Silver nitrate) and 2843.29 (Silver compounds: -- Other) are shown directly as 8-digit codes (2843.21.00, 2843.29.00) without an explicit 6-digit subheading row ''284321''/''284329'' in the PDF. Inferred subheadings from code structure.", "Subheading 2849.10 ''Of calcium'' (2849.10.00) is shown directly without an explicit 6-digit row. Inferred.", "Subheadings 2842.10 (Double or complex silicates), 2840.30 (Peroxoborates), 2843.30 (Gold compounds), 2833.21/24/25/27 (Other sulphates: of various metals), 2834.21 (Nitrates: Of potassium), 2835.22/24/25 (Phosphates: Of various), 2835.31/39 (Polyphosphates), 2836.30/40/50/60 (various carbonates), 2836.91/92 (Other Lithium/Strontium carbonates), 2837.11 (Cyanides of sodium), 2839.11 (Sodium metasilicates), 2839.19 (Of sodium: Other), 2840.11/19 (Disodium tetraborate variants), 2818.10 (Artificial corundum), 2818.30 (Aluminium hydroxide), 2819.10 (Chromium trioxide), 2819.90 (Other), 2820.10/90 (Manganese dioxide / Other), 2822.00 has no explicit subheading row but contains tariff lines, etc. — these are subheading-with-direct-tariff-line patterns where the PDF prints the 8-digit code directly under the heading without an intermediate 6-digit subheading row. Inferred subheadings from code structure throughout.", "Tariff line 2807.00.10 description in the PDF reads ''Sulphurc acid'' (sic) — likely typo for ''Sulphuric acid''. Preserved verbatim.", "Tariff line 2812.19.90 description reads ''other'' (lowercase) in the PDF — preserved verbatim (other tariff lines use ''Other'' with capital O).", "Tariff line 2813.90.30 (Lime Sulphur) has Policy Condition column showing a literal ''-'' character. Captured as null since ''-'' indicates ''no policy condition'' in this PDF context.", "Tariff line 2826.11.00 (''-- Of hydrogen fluoride (hydrofluoric acid)'') is not present in the PDF. The heading 2826 lists 2826.12.00 (Of aluminium), 2826.19 (Other) with 2826.19.10 (Magnesium fluoride) and 2826.19.90 (Other), 2826.30.00 (Sodium hexafluoroaluminate), 2826.90.00 (Other). The omission of 2826.11.00 is preserved verbatim from the PDF.", "Tariff line 2853.90.50 ''Magnesium phosphide plates, zinc phosphide'' Policy Condition column shows a literal ''-'' — captured as null.", "Sub-heading note 1 references ''sub-heading 2852 10'' (with space) — verbatim preservation of PDF''s spacing inconsistency. The corresponding code is 2852.10.", "Supplementary Note 1 (''Sub-heading 2804 40 includes, liquefied or solidified gas.'') refers to subheading 2804.40 (Oxygen). Supplementary Note 2 is a general reference to the Bureau of Indian Standards. Both captured under chapter_notes as supplementary notes.", "Tariff line 2843.90.12 description contains ''kg. 10%'' — likely a wrapped-from-PDF artifact referring to the weight/percentage of rhodium and palladium in a noble metal solution. Preserved verbatim.", "Subheading 2842.10 ''Double or complex silicates, including aluminosilicates whether or not chemically defined'' has a direct 8-digit code (2842.10.00) without an explicit 6-digit row. Inferred.", "The ''Export Policy'' and ''Policy Condition'' columns are not part of the tariff line description field; they are captured separately. Unit-of-measure column is NOT shown in this chapter''s PDF — unit field set to null for all tariff lines.", "Heading 2842 only shows 2842.10.00 and the 2842.90 sub-grouping. There are no 2842.20/2842.30/etc. subheadings in this PDF. Preserved verbatim.", "Subheading 2843.10 (Colloidal precious metals) has 3 tariff lines (2843.10.10, 2843.10.20, 2843.10.90) while 2843.21, 2843.29, 2843.30 are 8-digit codes directly under heading 2843. Subheading 2843.90 (Other compounds; amalgams) has 4 tariff lines (2843.90.11, 2843.90.12, 2843.90.19, 2843.90.20).", "Subheading 2844.30 has 7 tariff lines (2844.30.10, 2844.30.21, 2844.30.22, 2844.30.23, 2844.30.29, 2844.30.30, 2844.30.90). Subheading 2845.90 has 2 tariff lines (2845.90.10, 2845.90.90).", "Subheading 2846.10 (Cerium compounds) has 2 tariff lines (2846.10.10, 2846.10.90); 2846.90 (Other) has 4 tariff lines (2846.90.10/20/30/90). 2847 is a single tariff line 2847.00.00 (Hydrogen peroxide).", "Subheading 2853.90 has 6 tariff lines (2853.90.10/20/30/40/50/90). Subheading 2853.10 is a single 8-digit code (2853.10.00).", "Policy Condition 1 of the Chapter (''Export authorization from Department of Atomic Energy would be required for export of items in Category-0 (Nuclear materials, nuclear-related other materials, equipment and technology) of SCOMET.'') is referenced by multiple tariff lines: 2825.20.00 (Lithium oxide and hydroxide), 2836.91.00 (Lithium carbonates), and all of heading 2844 and most of heading 2845. Captured in policy_conditions metadata and on each affected tariff line via tariff_line.policy_condition field.", "Export Licensing Note 1 covers Potassium Permanganate (2841.61.00) which has a policy condition note: ''Export of Potassium Permanganate is free subject to No Objection Certificate from Narcotics Commissioner of India, Gwalior''."]'::jsonb, '{}'::jsonb, 'Chapter 28 Inorganic Chemicals; Organic Or Inorganic Compounds Of Precious Metals, Of Rare-Earth Metals, Of Radioactive Elements or of Isotopes.pdf', ('2026-05-22')::timestamptz, NOW()),
  ('29', 'VI', 'ORGANIC CHEMICALS', '[{"number": "1", "text": "Except where the context otherwise requires, the headings of this Chapter apply only to : (a) separate chemically defined organic compounds, whether or not containing impurities; (b) mixtures of two or more isomers of the same organic compound (whether or not containing impurities), except mixtures of acyclic hydrocarbon isomers (other than stereoisomers), whether or not saturated (Chapter 27); (c) the products of headings 2936 to 2939 or the sugar ethers, sugar acetals and sugar esters, and their salts, of heading 2940, or the products of heading 2941, whether or not chemically defined; (d) the products mentioned in (a), (b) or (c) above dissolved in water; (e) the products mentioned in (a), (b) or (c) above dissolved in other solvents provided that the solution constitutes a normal and necessary method of putting up these products adopted solely for reasons of safety or for transport and that the solvent does not render the product particularly suitable for specific use rather than for general use; (f) the products mentioned in (a), (b), (c), (d) or (e) above with an added stabiliser (including an anti-caking agent) necessary for their preservation or transport; (g) the products mentioned in (a), (b), (c), (d), (e) or (f) above with an added anti-dusting agent or a colouring or odoriferous substance or an emetic added to facilitate their identification or for safety reasons, provided that the additions do not render the product particularly suitable for specific use rather than forgeneral use; (h) the following products, diluted to standard strengths, for the production of azo dye: diazonium salts, couplers used for these salts and diazotisable amines and their salts."}, {"number": "2", "text": "This Chapter does not cover : (a) goods of heading 1504 or crude glycerol of heading 1520; (b) ethyl alcohol (heading 2207 or 2208); (c) methane or propane (heading 2711); (d) the compounds of carbon mentioned in Note 2 to Chapter 28; (e) Immunological products of heading 3002; (f) urea (heading 3102 or 3105); (g) colouring matter of vegetable or animal origin (heading 3203), synthetic organic colouring matter, synthetic organic products of a kind used as fluorescent brightening agents or as luminophores (heading 3204) or dyes or other colouring matter put up in forms or packings for retail sale (heading 3212); (h) enzymes (heading 3507); (ij) metaldehyde, hexamethylenetetramine or similar substances, put up in forms (for example, tablets, sticks or similar forms) for use as fuels or liquid or liquefied-gas fuels in containers of a kind used for filling or refilling cigarette or similar lighters and of a capacity not exceeding 300 cm3 (heading 3606); (k) products put up as charges for fire-extinguishers or put up in fire-extinguishing grenades, of heading 3813; ink removers put up in packing for retailsale, of heading 3824; or (l) optical elements, for example, of ethylenediamine tartrate (heading 9001)."}, {"number": "3", "text": "Goods which could be included in two or more of the headings of this Chapter are to be classified in that one of those headings which occurs last in numerical order."}, {"number": "4", "text": "In headings 2904 to 2906, 2908 to 2911 and 2913 to 2920, any reference to halogenated,sulphonated, nitrated or nitrosated derivatives includes a reference to compound derivatives, such as sulphohalogenated, nitrohalogenated, nitrosulphonated or nitrosulphohalogenated derivatives. Nitro or nitroso groups are not to be taken as \"nitrogenfunctions\" for the purposes of heading 2929. For the purposes of headings 2911, 2912, 2914, 2918 and 2922, \"oxygen function\", the characteristic organic oxygen-containing group of those respective headings, is restricted to the oxygen-functions referred to in headings 2905 to 2920."}, {"number": "5", "text": "(A) The esters of acid-function organic compounds of Sub-Chapters Ito VII with organic compounds of these Sub-Chapters are to be classified with that compound which is classified in the heading which occurs last in numerical order in these Sub-Chapters. (B) Esters of ethyl alcohol with acid-function organic compounds of Sub-Chapters I to VII are to be classified in the same heading as the corresponding acid-function compounds. (C) Subject to Note 1 to Section VI and Note 2 to Chapter 28 : (1) inorganic salts of organic compounds such as acid-, phenol-or enol-function compounds or organic bases, of Sub-Chapters I to X or heading 2942, are to be classified in the heading appropriate to the organic compound; (2) salts formed between organic compounds of Sub-Chapters I to X or heading 2942 are to be classified in the heading appropriate to the base or to the acid (including phenol- or enol- function compounds) from which they are formed, whichever occurs last in numerical order in the Chapter. (3) co-ordination compounds, other than products classifiable in Sub-Chapter XI or heading 2941, are to be classified in the heading which occurs last in numerical order in Chapter 29, among those appropriate to the fragments formed by \"\"cleaving\"\" of all metal bonds, other than metalcarbon bonds. (D) Metal alcoholates are to be classified in the same heading as the corresponding alcohols except in the case of ethanol (heading 2905). (E) Halides of carboxylic acids are to be classified in the same heading as the corresponding acids."}, {"number": "6", "text": "The compounds of headings 2930 and 2931 are organic compounds the molecules of which contain, in addition to atoms of hydrogen, oxygen or nitrogen, atoms of other non-metals or of metals(such assulphur, arsenic, or lead) directly linked to carbon atoms. Heading 2930 (organosulphur compounds) and heading 2931 (other organo-inorganic compounds) do notinclude sulphonated or halogenated derivatives(includingcompound derivatives)which, apart from hydrogen, oxygen and nitrogen, only have directly linked to carbon the atoms ofsulphur or of a halogen which give them their nature of sulphonated or halogenated derivatives(or compound derivatives)."}, {"number": "7", "text": "Headings 2932, 2933 and 2934 do not include epoxides with a three-membered ring, ketone peroxides, cyclic polymers of aldehydes or of thioaldehydes, anhydrides of polybasic carboxylic acids, cyclic esters of polyhydric alcohols or phenols with polybasic acids or imides of polybasic acids. These provisions apply only when the ring-position hetero-atoms are those resulting solely from the cyclising function or functions here listed."}, {"number": "8", "text": "For the purpose of heading 2937 : (a) the term \"\"\"\"hormones\"\"\"\" includes hormone-releasing or hormone-stimulating factors, hormone inhibitors and hormone antagonists(anti-hormones); (b) the expression \"\"\"\"used primarily as hormones\"\"\"\" applies not only to hormone derivatives and structural analogues used primarily for their hormonal effect, but also to those derivatives and structural analogues used primarily as intermediates in the synthesis of products of this heading."}]'::jsonb, '[{"number": "1", "text": "Within any one heading of this Chapter, derivatives of a chemical compound (or group of chemical compounds) are to be classified in the same sub-heading asthat compound (or group of compounds) provided that they are not more specially covered by any other sub-heading and that there is no residual sub-heading named \"other\" in the series of sub-headings concerned."}, {"number": "2", "text": "Note 3 to this Chapter shall not be applicable to the sub-heading of this Chapter."}]'::jsonb, '[{"number": "1", "text": "For the purposes of the tariff item 2906 11 10, the term “Natural Menthol” means an organic compound (C10H20O) which is obtained from the distillation of the Japanese type oil of mint or menthol mint known as Mentha arvensis but does not include those made synthetically through any chemical routes."}, {"number": "15", "text": "Tariff item 2933 59 50 covers one of the following goods of sub-heading 2933 59 : Bispyribac-sodium (ISO), ametroctradin, azoxystrobin, benzpyrimoxam, buprimate, florasulam, polyoxin D zinc salt, primiphos-methyl, pyribenzoxim, pyriftalid, pyrithiobac sodium, triflumezopyrim.", "notification_date": "15/10/2025", "notification_no": "44/2025-26"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["PDF source uses 8-digit codes without dots (e.g., ''29011000'') and 6-digit subheading codes without dots (e.g., ''290129''). Normalized to NNNN.NN.NN format (e.g., ''2901.10.00'') and NNNN.NN format (e.g., ''2901.29'') per project schema.", "PDF table-chrome headers (''Main Notes'', ''Sub-Heading Notes'', ''Supplementary Notes'', ''Policy Condition'', ''Product Description and Export Policy'', ''Sl.No. Notes Notification No Notification Date'', ''Itc(hs) Code. Description Export Policy Policy Condition'') were recognized as table chrome and EXCLUDED from the legal notes per extraction rules.", "Section VI ''Main Notes'' (4 notes) are attributed to section_notes per project convention; Chapter 28 already opened the section and these notes are duplicated as a header before each chapter in this Schedule 2 source PDF.", "Supplementary Notes table in the PDF contains only Sl.No. ''1'' (Natural Menthol definition) and Sl.No. ''15'' (tariff item 2933 59 50 covered goods). Sl.Nos. 2-14 and 16-19 are referenced by tariff-line descriptions (e.g., ''29163970 Goods specified in Supplementary Note 2 to this Chapter'') but their full textual definitions are NOT present in the PDF source. Captured as ''referenced_only'' entries with null text and a warning.", "Narcotics Commissioner of India, Gwalior NOC requirements appear on many tariff lines (Methyl Ethyl Ketone, 1-Phenyl-2 Propanone, Acetic Anhydride, Phenyl Acetic Acid, Anthranilic Acid, 2-Acetamidobenzoic acid, Isosafrole, 3,4-Methylenedioxyphenyl-2-Propanone, Piperonal, Safrole, Ephedrine, Pseudoephedrine, Norephedrine, Ergometrine, Ergotamine, Lysergic acid). These are narcotic/psychotropic precursors under the NDPS Act. Captured in policy_conditions where the PDF prints a per-line condition column.", "Policy Condition rows printed at the chapter header are: 1 (HFCs export authorization via Ozone Cell, MoEF&CC) and 2 (Montreal Protocol chemicals — Restricted/Prohibited per signatory status). Many tariff lines under heading 2903 (halogenated derivatives — HFCs/HCFCs/Halons/HBCDs) reference ''Subject to Policy Condition 1 of the Chapter'' or ''Subject to policy condition 2 of the chapter''. These references are captured but per-tariff-line policy_condition fields are not stored on each tariff line in this schema; chapter-level policy_conditions list holds the canonical text.", "Heading 2941 (Antibiotics) and heading 2942 (Other organic compounds) ostensibly close the chapter. The PDF ends with a stray code ''29909091 --- Other : ---- Ethanol, 2,2-thiobis-'' that does not match any valid heading 29 code (29.90.90.91 not in HS schedule). This appears to be a print-overflow artifact carried from heading 2930.90 (similar text appears at 29309091 ''Ethanol, 2,2-thiobis-''). EXCLUDED from extraction as malformed.", "Subheading 290129 ''Unsaturated : -- Other'' (residual subheading) is captured at the 4-digit + 2-digit level. Tariff lines 2901.29.10 through 2901.29.90 sit under it. The source PDF prints the subheading code dotlessly as ''290129'' on its own row before its tariff lines.", "Subheading 2932.91 / 2932.92 / 2932.93 / 2932.94 are precursor compounds (Isosafrole, Piperonal, Safrole, 1-(1,3-Benzodioxol-5-yl) propan-2-one) controlled under the NDPS Act / Precursor Drugs Rules. Each subheading carries a Narcotics Commissioner NOC requirement printed inline in the Policy Condition column.", "Sub-headings 2939.20 (Alkaloids of cinchona), 2939.41 (Ephedrine), 2939.42 (Pseudoephedrine), 2939.44 (Norephedrine), 2939.61 (Ergometrine), 2939.62 (Ergotamine), 2939.63 (Lysergic acid), 2939.72 (Cocaine, ecgonine) are controlled narcotic precursors / alkaloids per the NDPS Act. NOC from Narcotics Commissioner, India (Gwalior) is required for export per the per-line Policy Condition column.", "Heading 2934 (Nucleic acids etc.) has a recurring per-line note: ''However, Export of \"Deoxy nucleotide triphosphates\" will be in Restricted category and permitted under Restricted Export Authorization.'' This applies to all tariff lines under heading 2934. Captured in export_licensing_notes.", "Some PDF heading-title text is rendered in ALL CAPS with internal spacing artifacts (e.g., heading 2909 prints ''ETHERS, ETHER-ALCOHOLS, ...'', heading 2911 ''ACETALS AND HEMIACETALS, ...'', heading 2928 ''ORGANIC DERIVATIVES OF HYDRAZINE OR OF HYDROXYLAMINE''). Preserved verbatim.", "Several tariff lines have a duplicate row in the PDF (e.g., 29146930 ---Spinetoram, spinosad appears twice on page 32; 29147960 ---Tembotrione appears twice on page 33). Captured once in the JSON (deduplicated).", "Tariff line description column in the PDF contains many concatenated multi-product entries (e.g., 29214221-29214226 all begin with the same prefix list ''Benzyl ethyl aniline, Ethyl aniline, Diethylaniline, Dimethylaniline, Meta nitroaniline, Para nitroaniline:''). This is the WCO HS ''----'' (4-dash) inner-sub indicator convention; preserved verbatim including the prefix.", "Tariff line 29329500 description in the PDF reads ''Other : -- Tetrahydrocannabinols (all isomers)''. Tetrahydrocannabinols are a controlled narcotic but the source PDF does NOT print a Narcotics Commissioner NOC against this specific tariff line. Captured verbatim without inferring a policy condition.", "Tariff line 29302010 / 29242970 / 29336950 / 29336960 / 29349940 cross-reference Supplementary Notes whose text is absent from the source PDF (see warning above). Description preserved verbatim including the cross-reference text.", "Source PDF contains ''?'' encoding artifacts in place of typographic quote marks in one note (e.g., ''3,4-Methylenedioxyphenyl ? 2- Propanone''). Preserved verbatim as they appear in source.", "Heading-level title strings as printed in the source PDF use varying punctuation (full stop, colon, no terminator). Preserved verbatim including trailing period where present (e.g., ''Acyclic hydrocarbons.'', ''Cyclic hydrocarbons.'').", "Subheading 2917.13 PDF description ends with a stray quote '': Azelaic acid, sebacic acid, their salts and esters:\"'' — print artifact preserved verbatim."]'::jsonb, '{}'::jsonb, 'Chapter 29 Organic Chemicals.pdf', ('2026-05-22')::timestamptz, NOW()),
  ('30', 'VI', 'PHARMACEUTICAL PRODUCTS', '[{"number": "1", "text": "This Chapter does not cover: (a) foods or beverages(suchas dietetic, diabeticorfortified foods,food supplements,tonic beverages and mineral waters), other than nutritional preparations for intravenous administration (Section IV); (b) products, such as tablets, chewing gum or patches (transdermal systems), containing nicotine and intended to assist tobacco use cessation (heading 2404); (c) plasters specially calcined or finely ground for use in dentistry (heading 2520); (d) aqueous distillates or aqueous solutions of essential oil, suitable for medicinal uses (heading 3301); (e) preparations of headings 3303 to 3307, even if they have therapeutic or prophylactic properties; (f)soap or other products of heading 3401 containing added medicaments; (g) preparations with a basis of plaster for use in dentistry (heading 3407); (h) blood albumin not prepared for therapeutic or prophylactic uses (heading 3502); or. (ij) diagnostic reagents of heading 3822."}, {"number": "2", "text": "For the purposes of heading 3002, the expression \"immunological products\" appliesto peptides and proteins (other than goods of heading 2937) which are directly involved in the regulation of immunological processes, such as monoclonal antibodies (MAB), antibody fragments, antibody conjugates and antibody fragment conjugates, interleukins, interferons (IFN), chemokines and certain tumor necrosis factors (TNF), growth factors(GF), hematopoietins and colony stimulating factors(CSF).;"}, {"number": "3", "text": "For the purposes of headings 3003 and 3004 and of Note 4(d) to this Chapter, the following are to be treated: (a) as unmixed products: (1) unmixed products dissolved in water; (2) all goods of Chapter 28 or 29; and (3)simple vegetable extracts of heading1302,merelystandardised or dissolved in any solvent; (b) as products which have been mixed: (1) colloidalsolutions and suspensions(other than colloidalsulphur); (2) vegetable extracts obtained by the treatment of mixture of vegetable materials; and (3) salts and concentrates obtained by evaporating natural mineral waters."}, {"number": "4", "text": "Heading 3006 applies only to the following, which are to be classified in that heading and in no other heading of this Schedule? (a) sterile surgical catgut,similar sterile suture materials (including sterile absorbable surgical or dental yarns) and sterile tissue adhesives for surgical wound closure; (b)sterile laminaria and sterile laminaria tents; (c) sterile absorbable surgical or dental haemostatics sterile surgical or dental adhesion barriers, whether or not absorbable; (d) opacifying preparations for X-ray examinations and diagnostic reagents designed to be administered to the patient, being unmixed products put up in measured doses or products consisting of two or more ingredients which have been mixed together for such uses; (e) placebos and blinded (or double-blinded) clinical trial kits for use in recognized clinical trials, put up in measured doses, even if they might contain active medicaments; (f) dental cements and other dental fillings; bone reconstruction cements; (g) first-aid boxes and kits; (h) chemical contraceptive preparations based on hormones, on other products of heading 2937 or on spermicides; (i) gel preparations designed to be used in human or veterinary medicine as a lubricant for parts of the body for surgical operations or physical examinations or as a coupling agent between the body and medical instruments; and (j)waste pharmaceuticals, that is, pharmaceutical products which are unfit for their original intended purpose due to, for example, expiry ofshelf-life. (k) appliancesidentifiable for ostomy use, that is, colostomy, ileostomy and urostomy pouches cut to shape and their adhesive wafers or faceplates."}]'::jsonb, '[{"number": "1", "text": "For the purposes of sub-headings 3002 13 and 3002 14, the following are to be treated: (a) as unmixed products, pure products, whether or not containing impurities; (b) as products which have been mixed: (1) the products mentioned in (a) above dissolved in water or in other solvents; (2) the products mentioned in (a) and (b) (1) above with an added stabiliser necessary for their preservation or transport; and (3) the products mentioned in (a), (b) (1) and (b) (2) above with any other additive."}, {"number": "2", "text": "Sub-headings 3003 60 and 3004 60 cover medicaments containing artemisinin (INN) for oral ingestion combined with other pharmaceutical active ingredients, or containing any of the following active principles, whether or not combined with other pharmaceutical active ingredients: amodi aquine (INN); artelinic acid oritssalts; artenimol(INN); artemotil(INN); artemether(INN); artesunate (INN); chloroquine (INN); dihydroartemisinin (INN); lumefantrine (INN);mefloquine (INN); piperaquine (INN); pyrimethamine (INN) or sulfadoxine (INN)."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '["PDF source uses 8-digit codes without dots (e.g., ''30012010'') and 6-digit subheading codes without dots (e.g., ''300120''). Normalized to NNNN.NN.NN format (e.g., ''3001.20.10'') and NNNN.NN format (e.g., ''3001.20'') per project schema.", "PDF table-chrome headers (''Main Notes'', ''Sl.No. Notes Notification No Notification Date'', ''Sub-Heading Notes'', ''Policy Condition'', ''Export Licensing Notes'', ''Product Description and Export Policy'', ''Itc(hs) Code. Description Export Policy Policy Condition'') were recognized as table chrome and EXCLUDED from the legal notes per extraction rules.", "PDF contains ''?'' characters in place of typographic quote marks in several notes (e.g., ''?CITES?'', ''?Shipment Clearance Certificate?'', ''?Health Certificate?'', ''?The words Heavy metals within permissible limits?''). These are OCR/encoding artifacts from the source PDF — preserved verbatim as they appear in the source.", "Chapter title on PDF page 1 (above the Section VI notes table) reads ''Chapter 30 Pharmaceutical Products.'' The canonical ITC(HS) chapter title ''PHARMACEUTICAL PRODUCTS'' is used in the title field; source_pdf preserves the PDF filename.", "Section VI ''Main Notes'' (4 notes) are attributed to section_notes (Section VI, Products of the Chemical or Allied Industries), not chapter_notes.", "The Policy Condition section in the source PDF (page 3-4) lists 6 numbered rows but only Sl.No. ''1'' is shown with explicit numbering text; rows 2-6 appear without their own ''Policy Condition N'' numeric label in the header. Tariff-line Policy Condition references in the table cite ''Policy Condition 1'', ''2'', ''4 & 5'', and ''6'' of the Chapter. Policy conditions are captured by their PDF row Sl.No.", "Heading 3002 description on the PDF spans multiple lines and is rendered in ALL CAPS with internal spacing artifacts (e.g., ''FORTHERAPEUTIC'' as one word). Preserved verbatim — the intended text is ''FOR THERAPEUTIC''.", "Subheading 3002.41 PDF description includes ''Vaccines, toxins, cultures of micro-organisms (excluding yeasts) and similar products: - - Vaccines for human medicine:'' — contains hyphen-prefix indicators (''- -'') from the WCO HS nomenclature and a trailing colon.", "Several tariff-line descriptions in heading 3003 (subheading 3003.90) and 3004 (subheading 3004.90) are very long compound descriptions covering multiple sub-groups joined by '': ----'' (e.g., ''Bovine Albumin and drugs of animal origin, Merbromine National Formulary XII (Mercurochrome), Calcium Sennoside, Anaesthetic agents used in human or veterinary medicine or surgery, Aluminium hydroxide gel: ---- Bovine Albumin and drugs of animal origin''). These are preserved verbatim as they appear in the PDF.", "Tariff lines 3001.20.10, 3001.20.20, 3001.20.30, 3001.20.90 in the PDF appear under subheading 3001.20 (''Extracts of glands or other organs or of their secretions''). Tariff lines 3001.90.10, 3001.90.91, 3001.90.99 appear under subheading 3001.90 (''Other'').", "Subheading 3002.10 (''Antisera and other blood fractions and immunological products...'') has tariff line code ''3002.10.20'' followed by ''3002.10.91''. There is no ''3002.10.10'' or ''3002.10.99'' tariff line shown in the PDF — preserved verbatim. Code ''3002.10.20'' appears once in the PDF without a separate sub-classification description.", "The ''Export Policy'' and ''Policy Condition'' columns are not part of the tariff line description field; they are captured separately. Unit-of-measure column (kg/u/etc) is NOT shown in this chapter''s PDF — unit field set to null for all tariff lines.", "Subheading 3002.10 row 3002.10.20 has an empty Export Policy/Policy Condition column in the PDF. Preserved verbatim.", "Policy Condition row Sl.No. 6 in the PDF appears as ''1. Any human biological materials/samples/products which are related to activities covered under the provision of Drugs &Cosmetics Act 1940 &Rules thereunder are free for export subject to No objection from CDSCO. 2. Any human biological materials/samples/products NOT covered under (1) above are free for export subject to No objection from ICMR/DHR.'' — Sl.No. ''6'' was implicit (numbering inferred from sequence after rows 1-5).", "Tariff line code 30049014 (3004.90.14) description spans across page break: ''Ayurvedic, Unani, Homoeopathic, Siddha or Bio-chemic systems medicaments, put up for retail sale: ---- Of Homoeopathic System''. Concatenated verbatim from page 22-23.", "Tariff line code 30049096 (3004.90.96) Policy Condition column contains additional text after the standard ''Subject to Policy Condition 1 of the Chapter'': ''Furthermore, export of Ketamine is allowed subject to obtaining No Objection Certificate from Narcotics Commissioner''. Captured in policy_conditions metadata.", "Heading 3006 description in PDF reads ''Pharmaceutical goods specified in Note 4 to this Chapter.'' — verbatim including the trailing period."]'::jsonb, '{}'::jsonb, 'Chapter 30 Pharmaceutical Products.pdf', ('2026-05-21')::timestamptz, NOW()),
  ('31', 'VI', 'FERTILISERS', '[{"number": "1", "text": "This Chapter does not cover : (a) animal blood of heading 0511; (b) separate chemically defined compounds [other than those answering to the descriptions in Note 2(a), 3(a), 4(a) or 5 below]; or (c) cultured potassiumchloride crystals(other than optical elements) weighing not lessthan 2.5 g. each, of heading 3824; optical elements of potassiumchloride (heading 9001)."}, {"number": "2", "text": "Heading 3102 applies only to the following goods, provided that they are not put up in the forms or packages described in heading 3105: (a) goods which answer to one or other of the descriptions given below: (i) sodium nitrate, whether or not pure; (ii) ammonium nitrate, whether or not pure; (iii) double salts, whether or not pure, of ammonium sulphate and ammonium nitrate; (iv) ammonium sulphate, whether or not pure; (v) double salts (whether or not pure) or mixtures of calcium nitrate and ammonium nitrate; (vi) double salts(whether or not pure) or mixtures of calciumnitrate and magnesiumnitrate; (vii) calcium cyanamide, whether or not pure or treated with oil; (viii) urea, whether or not pure; (b) fertilisers consisting of any of the goods described in (A) above mixed together; (c) fertilisers consisting of ammonium chloride or of any of the goods described in (A) or (B) above mixed with chalk, gypsumor other inorganic non-fertilising substances; (d) liquid fertilisers consisting of the goods ofsub-paragraph (A) (ii) or (viii) above, or of mixtures of those goods, in an aqueous or ammoniacal solution."}, {"number": "3", "text": "Heading 3103 applies only to the following goods, provided that they are not put up in the forms or packages described in heading 3105: (a) goods which answer to one or other of the descriptions given below: (i) basic slag; (ii) natural phosphates of heading 2510, calcined or further heat-treated than for the removal of impurities; (iii) super phosphates(single, double or triple); (iv) calcium hydrogen orthophosphate containing not less than 0.2 per cent. by weight of fluorine calculated on the dry anhydrous product; (b) fertilisers consisting of any of the goods described in (A) above mixed together, but with no account being taken of the flourine content limit; (c) fertilisers consisting of any of the goods described in (A) or (B) above, but with no account being taken of the flourine content limit, mixed with chalk, gypsum or other inorganic nonfertilising substances."}, {"number": "4", "text": "Heading 3104 applies only to the following goods, provided that they are not put up in the forms or packages described in heading 3105 : (a) goods which answer to one or other of the descriptions given below: (i) crude natural potassiumsalts (for example, carnallite, kainite and sylvite); (ii) potassium chloride, whether or not pure, except as provided in Note 1(C) above; (iii) potassium sulphate, whether or not pure; (iv) magnesium potassium sulphate, whether or not pure; (b) fertilisers consisting of any of the goods described in (A) above mixed together."}, {"number": "5", "text": "Ammonium dihydrogen orthophosphate (monoammonium phosphate) and diammonium hydrogen orthophosphate (diammoniumphosphate) whether or not pure, and intermixturesthereof, are to be classified in heading 3105."}, {"number": "6", "text": "For the purposes of heading 3105, the term \"other fertilisers\" applies only to products of a kind used as fertilisers and containing, as an essential constituent, at least one of the fertilising elements nitrogen, phosphorus or potassium."}]'::jsonb, '[]'::jsonb, '[{"number": "1", "text": "In this Chapter, reference to any standard of the Bureau of Indian Standards refers to the last published version of that standard. Illustration : IS 1459 refers to IS 1459: 2018 and not to IS 1459: 1974."}]'::jsonb, '[{"number": "1", "text": "Manufacturers of SSP, DAP and NP / NPK who can freely export their own manufactures subject to the conditions mentioned i